globalThis.ETERNA_LIBRARY_CONTENT={"release_id":"eterna-library-2026.09-v2-160","coverage_complete":false,"human_teacher_reviewed":false,"archive_release":"eterna-library-2026.09-v1","lessons":[{"id":"i-count","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Contar objetos","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Contar objetos","contar","conteo","aprender a contar"],"explanation":"Contar sirve para saber cuántas cosas hay. Señala un objeto cada vez y di los números en orden. El último número que dices indica cuántos objetos has contado.","simpler":"Vamos despacito: toca una pieza, di «uno»; toca otra, di «dos». No vuelvas a contar la misma pieza.","example":"Con un adulto, coloca tres piezas grandes: cuenta una, dos y tres. Hay tres piezas, aunque las separes un poco.","why":"El número describe la cantidad, no el espacio que ocupan los objetos. Moverlos sin añadir ni quitar conserva la cantidad.","misconception":"Separar los objetos no cambia cuántos hay.","hints":["Toca cada objeto una sola vez y escucha el último número.","Vamos despacito: toca una pieza, di «uno»; toca otra, di «dos». No vuelvas a contar la misma pieza.","Con un adulto, coloca tres piezas grandes: cuenta una, dos y tres. Hay tres piezas, aunque las separes un poco."],"quiz":[{"id":"i-count:q0","question":"Si cuentas uno, dos y tres, ¿cuántas piezas hay?","options":["Dos","Tres","Cuatro"],"answer":"B","hint":"Toca cada objeto una sola vez y escucha el último número.","level":1},{"id":"i-count:q1","question":"¿Qué haces al contar?","options":["Señalar cada pieza una vez","Contar siempre la misma","Saltar piezas"],"answer":"A","hint":"Toca cada objeto una sola vez y escucha el último número.","level":2},{"id":"i-count:q2","question":"Si separas las tres piezas sin quitar ninguna, ¿cuántas quedan?","options":["Una","Cuatro","Tres"],"answer":"C","hint":"Toca cada objeto una sola vez y escucha el último número.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-shapes","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Formas geométricas","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Formas geométricas","formas","circulo","triangulo","cuadrado"],"explanation":"Podemos reconocer formas por su borde. Un círculo tiene un borde curvo. Un triángulo tiene tres lados rectos. Un cuadrado tiene cuatro lados iguales y cuatro esquinas como las de una hoja.","simpler":"Un círculo es redondito. Un triángulo tiene tres lados. Un cuadrado tiene cuatro lados iguales.","example":"Con un adulto, busca una tapa redonda y una hoja cuadrada. Recorre sus bordes con el dedo sin usar objetos cortantes.","why":"Los lados y las esquinas nos ayudan a clasificar las figuras aunque tengan otro color o estén giradas.","misconception":"Girar una figura no hace que deje de ser la misma forma.","hints":["Mira el borde y cuenta los lados rectos.","Un círculo es redondito. Un triángulo tiene tres lados. Un cuadrado tiene cuatro lados iguales.","Con un adulto, busca una tapa redonda y una hoja cuadrada. Recorre sus bordes con el dedo sin usar objetos cortantes."],"quiz":[{"id":"i-shapes:q0","question":"¿Qué forma tiene tres lados?","options":["Círculo","Cuadrado","Triángulo"],"answer":"C","hint":"Mira el borde y cuenta los lados rectos.","level":1},{"id":"i-shapes:q1","question":"¿Cuál tiene un borde curvo?","options":["Círculo","Triángulo","Cuadrado"],"answer":"A","hint":"Mira el borde y cuenta los lados rectos.","level":2},{"id":"i-shapes:q2","question":"¿Cuántos lados tiene un cuadrado?","options":["Tres","Cuatro","Cinco"],"answer":"B","hint":"Mira el borde y cuenta los lados rectos.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-patterns","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Series y patrones","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Series y patrones","series","patrones","series logicas"],"explanation":"Un patrón repite una regla. Antes de continuar una serie, busca qué grupo se repite. Puede ser una secuencia de colores, formas o sonidos.","simpler":"Busca el trocito que se repite: rojo, azul; rojo, azul.","example":"Con piezas grandes, forma círculo, cuadrado, círculo, cuadrado. El grupo que se repite es círculo-cuadrado.","why":"Reconocer la regla permite anticipar lo que viene después sin memorizar una lista entera.","misconception":"Una serie no se continúa eligiendo al azar.","hints":["Repite en voz baja el grupo más pequeño de la serie.","Busca el trocito que se repite: rojo, azul; rojo, azul.","Con piezas grandes, forma círculo, cuadrado, círculo, cuadrado. El grupo que se repite es círculo-cuadrado."],"quiz":[{"id":"i-patterns:q0","question":"En rojo, azul, rojo, azul, ¿qué sigue?","options":["Rojo","Verde","Azul"],"answer":"A","hint":"Repite en voz baja el grupo más pequeño de la serie.","level":1},{"id":"i-patterns:q1","question":"En palma, pie, palma, pie, ¿qué sigue?","options":["Pie","Palma","Silencio"],"answer":"B","hint":"Repite en voz baja el grupo más pequeño de la serie.","level":2},{"id":"i-patterns:q2","question":"¿Qué conviene buscar primero?","options":["El color favorito","La pieza más grande","El grupo que se repite"],"answer":"C","hint":"Repite en voz baja el grupo más pequeño de la serie.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-position","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Dentro y fuera","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Dentro y fuera","dentro y fuera","posiciones","ubicacion"],"explanation":"Dentro y fuera indican dónde está algo respecto a un límite. Una pieza está dentro si está en el espacio de la caja; está fuera si no está en ese espacio.","simpler":"Mira la caja: lo que está en su interior está dentro. Lo que está al lado, fuera.","example":"Coloca una pieza grande dentro de una caja y otra junto a la caja, con un adulto. Describe dónde está cada una.","why":"Estas palabras necesitan una referencia: dentro de la caja, fuera del aro o dentro de la habitación.","misconception":"La misma pieza puede cambiar de posición sin cambiar de tamaño.","hints":["Observa el borde de la caja.","Mira la caja: lo que está en su interior está dentro. Lo que está al lado, fuera.","Coloca una pieza grande dentro de una caja y otra junto a la caja, con un adulto. Describe dónde está cada una."],"quiz":[{"id":"i-position:q0","question":"Una pieza en el interior de la caja está…","options":["Lejos","Dentro","Fuera"],"answer":"B","hint":"Observa el borde de la caja.","level":1},{"id":"i-position:q1","question":"Una pieza al lado de la caja está…","options":["Fuera","Dentro","Debajo siempre"],"answer":"A","hint":"Observa el borde de la caja.","level":2},{"id":"i-position:q2","question":"Para decir dentro o fuera, ¿qué debemos mirar?","options":["Solo el color","Solo el tamaño","El límite del recipiente"],"answer":"C","hint":"Observa el borde de la caja.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-emotions","stage":"infantil","subject":"Crecimiento en armonía","title":"Reconocer emociones","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Reconocer emociones","emociones","sentimientos"],"explanation":"Las emociones nos ayudan a reconocer cómo vivimos una situación. Podemos sentir alegría, tristeza, enfado o miedo. Todas pueden aparecer; lo importante es expresarlas sin hacernos daño ni dañar a otros.","simpler":"Puedes decir «estoy triste» o «estoy enfadado». Un adulto de confianza puede escucharte y ayudarte.","example":"Si una torre se cae y te enfadas, puedes parar, respirar despacio y decirle al adulto que necesitas ayuda para reconstruirla.","why":"Nombrar una emoción permite comunicar una necesidad; no es una etiqueta permanente sobre quién eres.","misconception":"No hay que fingir estar contento todo el tiempo.","hints":["Pon nombre a lo que sientes y busca apoyo cercano.","Puedes decir «estoy triste» o «estoy enfadado». Un adulto de confianza puede escucharte y ayudarte.","Si una torre se cae y te enfadas, puedes parar, respirar despacio y decirle al adulto que necesitas ayuda para reconstruirla."],"quiz":[{"id":"i-emotions:q0","question":"¿A quién puedes contar que estás triste?","options":["A un adulto de confianza","A nadie nunca","Solo a la pantalla"],"answer":"A","hint":"Pon nombre a lo que sientes y busca apoyo cercano.","level":1},{"id":"i-emotions:q1","question":"Si te enfadas, ¿qué puedes hacer?","options":["Pegar","Romperlo todo","Parar y pedir ayuda"],"answer":"C","hint":"Pon nombre a lo que sientes y busca apoyo cercano.","level":2},{"id":"i-emotions:q2","question":"¿Sentir tristeza significa portarse mal?","options":["Siempre","No","Solo por la noche"],"answer":"B","hint":"Pon nombre a lo que sientes y busca apoyo cercano.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-turns","stage":"infantil","subject":"Crecimiento en armonía","title":"Respetar los turnos","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Respetar los turnos","turnos","esperar el turno"],"explanation":"Compartir un juego significa dar espacio a otras personas. Respetar un turno es esperar mientras participa otra persona y actuar cuando te corresponde. Puedes pedir ayuda para organizarlo.","simpler":"Ahora juega una persona y después otra. Esperar no significa que te hayan olvidado.","example":"En un juego con una pelota, Ana la pasa a Luis y después Luis a Ana. Ambos participan.","why":"Las reglas compartidas hacen el juego más previsible y ayudan a resolver desacuerdos sin daño.","misconception":"Esperar un turno no elimina tu derecho a participar.","hints":["Piensa en qué permite jugar también a la otra persona.","Ahora juega una persona y después otra. Esperar no significa que te hayan olvidado.","En un juego con una pelota, Ana la pasa a Luis y después Luis a Ana. Ambos participan."],"quiz":[{"id":"i-turns:q0","question":"¿Qué haces mientras le toca a otra persona?","options":["Quitarle el material","Esperar tu turno","Gritar para empezar"],"answer":"B","hint":"Piensa en qué permite jugar también a la otra persona.","level":1},{"id":"i-turns:q1","question":"¿Qué ayuda si no sabemos a quién le toca?","options":["Pedir ayuda para acordarlo","Abandonar siempre","Empujar"],"answer":"A","hint":"Piensa en qué permite jugar también a la otra persona.","level":2},{"id":"i-turns:q2","question":"¿Para qué sirven los turnos?","options":["Para que juegue solo uno","Para decidir quién vale más","Para que todos puedan participar"],"answer":"C","hint":"Piensa en qué permite jugar también a la otra persona.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-sequence","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Antes y después","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Antes y después","antes y despues","secuencias temporales"],"explanation":"Antes y después nos ayudan a ordenar lo que ocurre. Una acción puede ir antes de otra. Podemos contar una historia siguiendo ese orden.","simpler":"Primero ocurre una cosa y luego otra. Mira cuál sucede antes.","example":"Antes de salir, te pones los zapatos. Después sales con el adulto que te acompaña.","why":"Ordenar los hechos ayuda a explicar una rutina y a anticipar qué necesitamos hacer.","misconception":"Antes y después dependen del acontecimiento que tomamos como referencia.","hints":["Busca qué pasó primero.","Primero ocurre una cosa y luego otra. Mira cuál sucede antes.","Antes de salir, te pones los zapatos. Después sales con el adulto que te acompaña."],"quiz":[{"id":"i-sequence:q0","question":"Si primero te pones los zapatos y luego sales, ¿qué va antes?","options":["Ponerte los zapatos","Salir","Las dos a la vez siempre"],"answer":"A","hint":"Busca qué pasó primero.","level":1},{"id":"i-sequence:q1","question":"¿Qué palabra indica que algo ocurre más tarde?","options":["Antes","Dentro","Después"],"answer":"C","hint":"Busca qué pasó primero.","level":2},{"id":"i-sequence:q2","question":"Para contar una historia, ayuda…","options":["Mezclar siempre todo","Ordenar lo que ocurrió","Cambiar todos los personajes"],"answer":"B","hint":"Busca qué pasó primero.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-rhymes","stage":"infantil","subject":"Comunicación y representación de la realidad","title":"Rimas","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Rimas","rimas","rimar"],"explanation":"Dos palabras riman cuando comparten sonidos al final de una forma reconocible. Podemos escuchar sus finales y jugar a compararlos.","simpler":"Escucha el final: gato y pato suenan parecido al terminar.","example":"Di despacio «gato» y «pato». Comparten el final «ato». Después compáralas con «sol».","why":"Al fijarte en los sonidos entrenas la atención al lenguaje; no hace falta saber leer para jugar con rimas.","misconception":"Rimar depende de los sonidos, no del significado.","hints":["Repite despacio la última parte de cada palabra.","Escucha el final: gato y pato suenan parecido al terminar.","Di despacio «gato» y «pato». Comparten el final «ato». Después compáralas con «sol»."],"quiz":[{"id":"i-rhymes:q0","question":"¿Qué palabra rima con gato?","options":["Mesa","Pato","Sol"],"answer":"B","hint":"Repite despacio la última parte de cada palabra.","level":1},{"id":"i-rhymes:q1","question":"¿Qué escuchamos para buscar una rima?","options":["El final de las palabras","El color de las letras","El tamaño del papel"],"answer":"A","hint":"Repite despacio la última parte de cada palabra.","level":2},{"id":"i-rhymes:q2","question":"¿Qué pareja rima?","options":["Pan y nube","Flor y mesa","Luna y cuna"],"answer":"C","hint":"Repite despacio la última parte de cada palabra.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-senses","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Los sentidos","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Los sentidos","sentidos","cinco sentidos"],"explanation":"Usamos los sentidos para obtener información del entorno. La vista permite ver, el oído escuchar, el olfato oler, el gusto saborear y el tacto notar, por ejemplo, una textura. No necesitamos tocar o probar algo para conocerlo si puede ser peligroso.","simpler":"Los ojos ven y los oídos escuchan. Las manos pueden notar si una tela es suave.","example":"Con un adulto, mira un pañuelo, escucha unas palmas y toca una tela segura. Nunca pruebes ni huelas sustancias desconocidas.","why":"Cada sentido aporta información distinta; podemos combinarlos de forma segura para explorar.","misconception":"La curiosidad no obliga a tocar ni probar objetos desconocidos.","hints":["Relaciona la información con el sentido que la detecta.","Los ojos ven y los oídos escuchan. Las manos pueden notar si una tela es suave.","Con un adulto, mira un pañuelo, escucha unas palmas y toca una tela segura. Nunca pruebes ni huelas sustancias desconocidas."],"quiz":[{"id":"i-senses:q0","question":"¿Qué usamos principalmente para escuchar?","options":["Ojos","Lengua","Oídos"],"answer":"C","hint":"Relaciona la información con el sentido que la detecta.","level":1},{"id":"i-senses:q1","question":"¿Qué sentido permite notar una tela suave?","options":["Tacto","Vista únicamente","Olfato"],"answer":"A","hint":"Relaciona la información con el sentido que la detecta.","level":2},{"id":"i-senses:q2","question":"¿Debemos probar una sustancia desconocida?","options":["Siempre","No","Solo si tiene buen color"],"answer":"B","hint":"Relaciona la información con el sentido que la detecta.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-syllables","stage":"infantil","subject":"Comunicación y representación de la realidad","title":"Sílabas","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Sílabas","silabas","separar palabras"],"explanation":"Las palabras se pueden pronunciar en partes llamadas sílabas. Podemos marcar cada parte con una palmada suave mientras hablamos.","simpler":"Di «ca-sa»: oyes dos partes. Da una palmada por cada parte.","example":"Pronuncia «ma-ri-po-sa» despacio: son cuatro sílabas. No confundas las sílabas con el número de letras.","why":"Escuchar partes dentro de las palabras prepara para relacionar el habla con la lectura y la escritura.","misconception":"Una sílaba puede contener más de una letra.","hints":["Pronuncia la palabra, sin añadir ni quitar sonidos.","Di «ca-sa»: oyes dos partes. Da una palmada por cada parte.","Pronuncia «ma-ri-po-sa» despacio: son cuatro sílabas. No confundas las sílabas con el número de letras."],"quiz":[{"id":"i-syllables:q0","question":"¿Cuántas sílabas tiene casa?","options":["Una","Dos","Tres"],"answer":"B","hint":"Pronuncia la palabra, sin añadir ni quitar sonidos.","level":1},{"id":"i-syllables:q1","question":"¿Cómo se separa mariposa?","options":["Ma-ri-po-sa","Mar-ip-osa","Mari-po-sa siempre"],"answer":"A","hint":"Pronuncia la palabra, sin añadir ni quitar sonidos.","level":2},{"id":"i-syllables:q2","question":"Una palmada por cada parte nos ayuda a contar…","options":["Los colores","Las letras exactas","Las sílabas"],"answer":"C","hint":"Pronuncia la palabra, sin añadir ni quitar sonidos.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-compare","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Más y menos","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Más y menos","mas y menos","comparar cantidades"],"explanation":"Para comparar dos grupos puedes emparejar un objeto de uno con otro del segundo. Si sobran objetos en un grupo, ese grupo tiene más. Si no sobra ninguno, tienen la misma cantidad.","simpler":"Haz parejas entre los dos grupos. Mira en cuál quedan piezas sin pareja.","example":"Coloca tres piezas grandes y, enfrente, dos. Al emparejarlas sobra una en el grupo de tres: tiene más.","why":"La correspondencia uno a uno permite comparar cantidades sin depender del tamaño de los objetos.","misconception":"Un grupo más extendido no tiene necesariamente más objetos.","hints":["Empareja un objeto de cada grupo.","Haz parejas entre los dos grupos. Mira en cuál quedan piezas sin pareja.","Coloca tres piezas grandes y, enfrente, dos. Al emparejarlas sobra una en el grupo de tres: tiene más."],"quiz":[{"id":"i-compare:q0","question":"Entre tres piezas y dos piezas, ¿dónde hay más?","options":["En el grupo de tres","En el de dos","Siempre lo mismo"],"answer":"A","hint":"Empareja un objeto de cada grupo.","level":1},{"id":"i-compare:q1","question":"Si todos los objetos tienen pareja y no sobra ninguno, hay…","options":["Más en el primero","Menos en el segundo","La misma cantidad"],"answer":"C","hint":"Empareja un objeto de cada grupo.","level":2},{"id":"i-compare:q2","question":"Para comparar sin contar podemos…","options":["Mirar solo la separación","Emparejar objetos","Cambiar los colores"],"answer":"B","hint":"Empareja un objeto de cada grupo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-living","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Seres vivos","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Seres vivos","seres vivos","plantas y animales"],"explanation":"Los seres vivos realizan funciones vitales, como nutrirse y relacionarse con el entorno; las poblaciones continúan mediante la reproducción. Las plantas y los animales son seres vivos. No todo lo que se mueve está vivo.","simpler":"Una planta necesita agua y condiciones adecuadas para vivir. Un coche se mueve, pero no está vivo.","example":"Observa una planta con un adulto durante varios días. Puedes ver cómo crece, sin arrancar sus hojas ni molestar a animales.","why":"Las funciones vitales distinguen a los organismos de los objetos, aunque algunos objetos se muevan o consuman energía.","misconception":"Moverse no basta para decir que algo es un ser vivo.","hints":["Compara una planta con un objeto construido.","Una planta necesita agua y condiciones adecuadas para vivir. Un coche se mueve, pero no está vivo.","Observa una planta con un adulto durante varios días. Puedes ver cómo crece, sin arrancar sus hojas ni molestar a animales."],"quiz":[{"id":"i-living:q0","question":"¿Cuál es un ser vivo?","options":["Una bicicleta","Una planta","Una piedra"],"answer":"B","hint":"Compara una planta con un objeto construido.","level":1},{"id":"i-living:q1","question":"¿Todo lo que se mueve está vivo?","options":["No","Sí","Solo si va rápido"],"answer":"A","hint":"Compara una planta con un objeto construido.","level":2},{"id":"i-living:q2","question":"¿Cómo podemos observar una planta?","options":["Arrancándola siempre","Sin cuidarla","Mirándola y cuidándola con un adulto"],"answer":"C","hint":"Compara una planta con un objeto construido.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-add","stage":"primaria","subject":"Matemáticas","title":"La suma","grade_min":1,"grade_max":6,"school_years":["1º de Primaria","2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La suma","sumas","sumar","adicion"],"explanation":"Sumar reúne cantidades o añade una cantidad a otra. El resultado se llama suma. Puedes comprobar una suma cambiando el orden de sus sumandos: el resultado se conserva.","simpler":"Junta un grupo con otro y cuenta cuántos elementos hay en total.","example":"Si tienes 3 lápices y recibes 2, ahora tienes 5: 3 + 2 = 5.","why":"La suma de cantidades cuenta todos los elementos sin contarlos dos veces.","misconception":"Sumar cero no cambia una cantidad.","hints":["Empieza por la primera cantidad y añade la segunda.","Junta un grupo con otro y cuenta cuántos elementos hay en total.","Si tienes 3 lápices y recibes 2, ahora tienes 5: 3 + 2 = 5."],"quiz":[{"id":"p-add:q0","question":"¿Cuánto es 4 + 3?","options":["6","7","8"],"answer":"B","hint":"Empieza por la primera cantidad y añade la segunda.","level":1},{"id":"p-add:q1","question":"¿Cómo se llaman los números que sumamos?","options":["Sumandos","Divisores","Denominadores"],"answer":"A","hint":"Empieza por la primera cantidad y añade la segunda.","level":2},{"id":"p-add:q2","question":"¿Cuánto es 8 + 0?","options":["0","1","8"],"answer":"C","hint":"Empieza por la primera cantidad y añade la segunda.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-sub","stage":"primaria","subject":"Matemáticas","title":"La resta","grade_min":1,"grade_max":6,"school_years":["1º de Primaria","2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La resta","restas","restar","sustraccion"],"explanation":"Restar permite quitar una cantidad o calcular cuánto separa dos cantidades. Puedes comprobar una resta sumando el resultado y la cantidad que quitaste.","simpler":"Imagina lo que tienes, quita una parte y mira cuánto queda.","example":"De 9 cromos entregas 4: quedan 5. La comprobación es 5 + 4 = 9.","why":"La resta y la suma se relacionan: una permite deshacer la otra en estas operaciones.","misconception":"Cambiar el orden de una resta suele cambiar el resultado.","hints":["Piensa qué cantidad debes añadir al número menor para llegar al mayor.","Imagina lo que tienes, quita una parte y mira cuánto queda.","De 9 cromos entregas 4: quedan 5. La comprobación es 5 + 4 = 9."],"quiz":[{"id":"p-sub:q0","question":"¿Cuánto es 9 − 4?","options":["5","4","13"],"answer":"A","hint":"Piensa qué cantidad debes añadir al número menor para llegar al mayor.","level":1},{"id":"p-sub:q1","question":"¿Cómo compruebas 12 − 5 = 7?","options":["12 + 7","5 − 7","7 + 5 = 12"],"answer":"C","hint":"Piensa qué cantidad debes añadir al número menor para llegar al mayor.","level":2},{"id":"p-sub:q2","question":"¿Cuánto es 6 − 0?","options":["0","6","1"],"answer":"B","hint":"Piensa qué cantidad debes añadir al número menor para llegar al mayor.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-mul","stage":"primaria","subject":"Matemáticas","title":"La multiplicación","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La multiplicación","multiplicaciones","multiplicar","tablas de multiplicar"],"explanation":"La multiplicación de números naturales puede representar grupos con la misma cantidad. Primero identifica cuántos grupos hay y cuántos elementos tiene cada uno. El resultado se llama producto.","simpler":"Cuenta grupos iguales en vez de ir objeto por objeto.","example":"Cuatro bolsas con tres canicas cada una contienen 4 × 3 = 12 canicas.","why":"La multiplicación abrevia una suma repetida cuando todos los grupos son iguales.","misconception":"Sumar el número de grupos y el tamaño del grupo no da el total.","hints":["Puedes sumar varias veces la misma cantidad.","Cuenta grupos iguales en vez de ir objeto por objeto.","Cuatro bolsas con tres canicas cada una contienen 4 × 3 = 12 canicas."],"quiz":[{"id":"p-mul:q0","question":"¿Cuánto es 6 × 4?","options":["10","24","20"],"answer":"B","hint":"Puedes sumar varias veces la misma cantidad.","level":1},{"id":"p-mul:q1","question":"Tres cajas con 5 piezas cada una tienen…","options":["15 piezas","8 piezas","2 piezas"],"answer":"A","hint":"Puedes sumar varias veces la misma cantidad.","level":2},{"id":"p-mul:q2","question":"¿Cuánto es 9 × 1?","options":["1","0","9"],"answer":"C","hint":"Puedes sumar varias veces la misma cantidad.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-div","stage":"primaria","subject":"Matemáticas","title":"La división","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La división","divisiones","dividir","division exacta"],"explanation":"Dividir puede servir para repartir en partes iguales o para averiguar cuántos grupos de un tamaño caben. En una división exacta, divisor por cociente da el dividendo. No se divide entre cero.","simpler":"Reparte la misma cantidad a cada grupo, sin favorecer a ninguno.","example":"Reparte 18 fichas entre 3 grupos: cada uno recibe 6. Comprueba: 3 × 6 = 18.","why":"El reparto y la agrupación son dos interpretaciones de la misma relación entre multiplicación y división.","misconception":"Dividir no siempre es simplemente hacer un número menor: depende del divisor.","hints":["Busca un número que, multiplicado por el divisor, produzca el dividendo.","Reparte la misma cantidad a cada grupo, sin favorecer a ninguno.","Reparte 18 fichas entre 3 grupos: cada uno recibe 6. Comprueba: 3 × 6 = 18."],"quiz":[{"id":"p-div:q0","question":"¿Cuánto es 18 ÷ 3?","options":["15","9","6"],"answer":"C","hint":"Busca un número que, multiplicado por el divisor, produzca el dividendo.","level":1},{"id":"p-div:q1","question":"¿Qué comprueba 24 ÷ 4 = 6?","options":["4 × 6 = 24","24 + 6 = 4","4 − 6 = 24"],"answer":"A","hint":"Busca un número que, multiplicado por el divisor, produzca el dividendo.","level":2},{"id":"p-div:q2","question":"¿Se puede dividir entre cero?","options":["Sí, siempre","No está definido","Da siempre uno"],"answer":"B","hint":"Busca un número que, multiplicado por el divisor, produzca el dividendo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-place","stage":"primaria","subject":"Matemáticas","title":"Valor posicional","grade_min":1,"grade_max":6,"school_years":["1º de Primaria","2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Valor posicional","valor posicional","unidades decenas y centenas"],"explanation":"En nuestro sistema decimal, el valor de una cifra depende de su posición. Diez unidades forman una decena y diez decenas una centena. El cero puede indicar que no hay unidades de un orden.","simpler":"Una cifra cambia de valor cuando cambia de sitio. En 24, el 2 vale dos decenas.","example":"En 305 hay 3 centenas, 0 decenas y 5 unidades: 300 + 0 + 5.","why":"Agrupar de diez en diez permite escribir muchas cantidades con solo diez cifras.","misconception":"La cifra y el valor de esa cifra no son lo mismo.","hints":["Lee el nombre de cada posición desde la derecha.","Una cifra cambia de valor cuando cambia de sitio. En 24, el 2 vale dos decenas.","En 305 hay 3 centenas, 0 decenas y 5 unidades: 300 + 0 + 5."],"quiz":[{"id":"p-place:q0","question":"En 472, el 7 representa…","options":["7 unidades","70 unidades","700 unidades"],"answer":"B","hint":"Lee el nombre de cada posición desde la derecha.","level":1},{"id":"p-place:q1","question":"¿Cuántas unidades hay en una decena?","options":["10","100","1"],"answer":"A","hint":"Lee el nombre de cada posición desde la derecha.","level":2},{"id":"p-place:q2","question":"305 se descompone como…","options":["30 + 5","300 + 50","300 + 5"],"answer":"C","hint":"Lee el nombre de cada posición desde la derecha.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-fractions","stage":"primaria","subject":"Matemáticas","title":"Las fracciones","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Las fracciones","fracciones","fraccion","partes de un todo"],"explanation":"Una fracción puede representar partes iguales de una unidad. El denominador indica en cuántas partes iguales se divide la unidad; el numerador, cuántas partes consideramos. Siempre hay que saber cuál es la unidad.","simpler":"Divide una barra en partes iguales. El número de abajo dice cuántas partes tiene; el de arriba, cuántas tomas.","example":"Si una barra se divide en 4 partes iguales y tomas 3, tomas 3/4 de la barra.","why":"Sin una unidad de referencia, decir «la mitad» no basta para saber qué cantidad concreta tenemos.","misconception":"Las partes de la unidad deben ser iguales en esta representación.","hints":["Distingue el número de partes de la unidad y las partes que tomas.","Divide una barra en partes iguales. El número de abajo dice cuántas partes tiene; el de arriba, cuántas tomas.","Si una barra se divide en 4 partes iguales y tomas 3, tomas 3/4 de la barra."],"quiz":[{"id":"p-fractions:q0","question":"En 3/4, ¿cuál es el denominador?","options":["3","7","4"],"answer":"C","hint":"Distingue el número de partes de la unidad y las partes que tomas.","level":1},{"id":"p-fractions:q1","question":"En 2/5, consideramos…","options":["2 de las 5 partes iguales","5 de 2 partes","Siempre 2 unidades enteras"],"answer":"A","hint":"Distingue el número de partes de la unidad y las partes que tomas.","level":2},{"id":"p-fractions:q2","question":"Para comparar dibujos de fracciones, la unidad debe ser…","options":["De cualquier tamaño sin indicarlo","La misma o estar claramente definida","Siempre una pizza"],"answer":"B","hint":"Distingue el número de partes de la unidad y las partes que tomas.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-denominator","stage":"primaria","subject":"Matemáticas","title":"El denominador","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El denominador","denominador","denominadores"],"explanation":"El denominador es el número de abajo en una fracción. Al representar partes de una unidad, dice en cuántas partes iguales la dividimos. Con la misma unidad, dividir en más partes produce partes más pequeñas.","simpler":"En 1/4, el 4 significa que has dividido la unidad en cuatro partes iguales.","example":"Imagina dos barras iguales: divide una en 2 partes y otra en 4. Un cuarto es más pequeño que un medio.","why":"Al repartir la misma unidad entre más partes, cada parte tiene que ser menor.","misconception":"Un denominador mayor no implica una fracción mayor si el numerador es el mismo y positivo.","hints":["Mira el número situado debajo de la línea de fracción.","En 1/4, el 4 significa que has dividido la unidad en cuatro partes iguales.","Imagina dos barras iguales: divide una en 2 partes y otra en 4. Un cuarto es más pequeño que un medio."],"quiz":[{"id":"p-denominator:q0","question":"En 5/8, ¿cuál es el denominador?","options":["5","8","13"],"answer":"B","hint":"Mira el número situado debajo de la línea de fracción.","level":1},{"id":"p-denominator:q1","question":"Con barras iguales, ¿qué parte es mayor?","options":["1/2","1/4","Son siempre iguales"],"answer":"A","hint":"Mira el número situado debajo de la línea de fracción.","level":2},{"id":"p-denominator:q2","question":"El denominador indica…","options":["Las partes tomadas siempre","El color de las partes","Las partes iguales en que se divide la unidad"],"answer":"C","hint":"Mira el número situado debajo de la línea de fracción.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-equivalent","stage":"primaria","subject":"Matemáticas","title":"Fracciones equivalentes","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Fracciones equivalentes","fracciones equivalentes","equivalencia de fracciones"],"explanation":"Dos fracciones son equivalentes si representan el mismo número. Puedes obtener una equivalente multiplicando numerador y denominador por el mismo número distinto de cero. No basta con cambiar solo uno.","simpler":"Puedes partir cada trozo en trozos más pequeños sin cambiar lo que tenías.","example":"La mitad de una barra es lo mismo que dos cuartos: 1/2 = 2/4.","why":"Multiplicar arriba y abajo por el mismo factor equivale a multiplicar la fracción por uno.","misconception":"Sumar el mismo número al numerador y al denominador no conserva siempre el valor.","hints":["Aplica el mismo factor arriba y abajo.","Puedes partir cada trozo en trozos más pequeños sin cambiar lo que tenías.","La mitad de una barra es lo mismo que dos cuartos: 1/2 = 2/4."],"quiz":[{"id":"p-equivalent:q0","question":"¿Cuál equivale a 1/2?","options":["1/4","3/4","2/4"],"answer":"C","hint":"Aplica el mismo factor arriba y abajo.","level":1},{"id":"p-equivalent:q1","question":"Para pasar de 2/3 a una equivalente con denominador 6, el numerador es…","options":["4","2","6"],"answer":"A","hint":"Aplica el mismo factor arriba y abajo.","level":2},{"id":"p-equivalent:q2","question":"Multiplicar solo el denominador por 2…","options":["Conserva siempre el valor","Cambia el valor de una fracción no nula","Duplica siempre la fracción"],"answer":"B","hint":"Aplica el mismo factor arriba y abajo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-decimal","stage":"primaria","subject":"Matemáticas","title":"Números decimales","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Números decimales","decimales","numeros decimales"],"explanation":"Los decimales amplían el valor posicional a partes de la unidad. Tras la coma aparecen décimas, centésimas y milésimas. Para compararlos, alinea las posiciones, no cuentes solo las cifras.","simpler":"Una décima es una de diez partes iguales. Una centésima es una de cien.","example":"0,5 y 0,50 representan la misma cantidad: cinco décimas son cincuenta centésimas.","why":"Cada posición a la derecha representa una parte diez veces menor que la anterior.","misconception":"Tener más cifras decimales no significa ser mayor.","hints":["Compara primero unidades, luego décimas y después centésimas.","Una décima es una de diez partes iguales. Una centésima es una de cien.","0,5 y 0,50 representan la misma cantidad: cinco décimas son cincuenta centésimas."],"quiz":[{"id":"p-decimal:q0","question":"¿Qué número es mayor?","options":["0,7","0,65","Son iguales"],"answer":"A","hint":"Compara primero unidades, luego décimas y después centésimas.","level":1},{"id":"p-decimal:q1","question":"0,50 equivale a…","options":["5","50","0,5"],"answer":"C","hint":"Compara primero unidades, luego décimas y después centésimas.","level":2},{"id":"p-decimal:q2","question":"La primera cifra tras la coma representa…","options":["Centenas","Décimas","Unidades"],"answer":"B","hint":"Compara primero unidades, luego décimas y después centésimas.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-percent","stage":"primaria","subject":"Matemáticas","title":"Porcentajes","grade_min":5,"grade_max":6,"school_years":["5º de Primaria","6º de Primaria"],"aliases":["Porcentajes","porcentajes","porcentaje","tanto por ciento"],"explanation":"Un porcentaje expresa una cantidad por cada cien. Para calcular un porcentaje de una cantidad puedes multiplicarla por el porcentaje y dividir entre cien. El total de referencia importa.","simpler":"El 25 % significa 25 de cada 100, es decir, una cuarta parte.","example":"El 20 % de 50 es 10: 50 × 20 ÷ 100 = 10.","why":"El porcentaje compara una parte con un total usando siempre cien como referencia.","misconception":"El mismo porcentaje de dos totales distintos puede dar cantidades distintas.","hints":["Busca primero cuánto representa una parte sencilla, como el 10 % o el 50 %.","El 25 % significa 25 de cada 100, es decir, una cuarta parte.","El 20 % de 50 es 10: 50 × 20 ÷ 100 = 10."],"quiz":[{"id":"p-percent:q0","question":"¿Cuánto es el 50 % de 80?","options":["20","40","50"],"answer":"B","hint":"Busca primero cuánto representa una parte sencilla, como el 10 % o el 50 %.","level":1},{"id":"p-percent:q1","question":"El 25 % equivale a…","options":["Una cuarta parte","La mitad","El doble"],"answer":"A","hint":"Busca primero cuánto representa una parte sencilla, como el 10 % o el 50 %.","level":2},{"id":"p-percent:q2","question":"El 10 % de 200 es…","options":["2","10","20"],"answer":"C","hint":"Busca primero cuánto representa una parte sencilla, como el 10 % o el 50 %.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-prime","stage":"primaria","subject":"Matemáticas","title":"Números primos","grade_min":5,"grade_max":6,"school_years":["5º de Primaria","6º de Primaria"],"aliases":["Números primos","numeros primos","numero primo","primos"],"explanation":"Un número primo es un número natural mayor que 1 que tiene exactamente dos divisores positivos: 1 y él mismo. El 2 es primo y es el único primo par. El 1 no es primo.","simpler":"Un primo solo puede repartirse exactamente en grupos de 1 o en un único grupo con todo.","example":"El 7 solo tiene como divisores positivos 1 y 7. El 8 no es primo, porque también se divide exactamente entre 2 y 4.","why":"Tener exactamente dos divisores diferencia a los primos de los compuestos y del número 1.","misconception":"No todos los impares son primos: 9 = 3 × 3.","hints":["Cuenta los divisores positivos, no solo si el número es impar.","Un primo solo puede repartirse exactamente en grupos de 1 o en un único grupo con todo.","El 7 solo tiene como divisores positivos 1 y 7. El 8 no es primo, porque también se divide exactamente entre 2 y 4."],"quiz":[{"id":"p-prime:q0","question":"¿Cuál es primo?","options":["9","15","7"],"answer":"C","hint":"Cuenta los divisores positivos, no solo si el número es impar.","level":1},{"id":"p-prime:q1","question":"¿El 1 es primo?","options":["No","Sí","Solo a veces"],"answer":"A","hint":"Cuenta los divisores positivos, no solo si el número es impar.","level":2},{"id":"p-prime:q2","question":"¿Cuál es el único primo par?","options":["4","2","6"],"answer":"B","hint":"Cuenta los divisores positivos, no solo si el número es impar.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-perimeter","stage":"primaria","subject":"Matemáticas","title":"El perímetro","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El perímetro","perimetro","perimetros"],"explanation":"El perímetro es la longitud del contorno de una figura. Se calcula sumando las longitudes de todos sus lados. Sus unidades son de longitud, como centímetros o metros.","simpler":"Imagina una cuerda rodeando la figura. Su longitud es el perímetro.","example":"Un rectángulo de 5 cm por 3 cm tiene perímetro 5 + 3 + 5 + 3 = 16 cm.","why":"Sumar los lados equivale a sumar todos los tramos del recorrido alrededor de la figura.","misconception":"Perímetro y área miden cosas diferentes.","hints":["Recorre el borde y no olvides ningún lado.","Imagina una cuerda rodeando la figura. Su longitud es el perímetro.","Un rectángulo de 5 cm por 3 cm tiene perímetro 5 + 3 + 5 + 3 = 16 cm."],"quiz":[{"id":"p-perimeter:q0","question":"Un cuadrado de lado 4 cm tiene perímetro…","options":["8 cm","16 cm","16 cm²"],"answer":"B","hint":"Recorre el borde y no olvides ningún lado.","level":1},{"id":"p-perimeter:q1","question":"El perímetro mide…","options":["El contorno","La superficie interior","El volumen"],"answer":"A","hint":"Recorre el borde y no olvides ningún lado.","level":2},{"id":"p-perimeter:q2","question":"Un triángulo con lados de 3, 4 y 5 cm tiene perímetro…","options":["20 cm","60 cm","12 cm"],"answer":"C","hint":"Recorre el borde y no olvides ningún lado.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-area","stage":"primaria","subject":"Matemáticas","title":"El área","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El área","area","areas","area del rectangulo"],"explanation":"El área mide la superficie que ocupa una figura. Usamos unidades cuadradas. En un rectángulo, área = base × altura, siempre con medidas en la misma unidad.","simpler":"Cuenta cuántos cuadrados de una unidad cubren el interior sin huecos ni solapamientos.","example":"Un rectángulo de 4 cm por 3 cm se cubre con 12 cuadrados de 1 cm²: su área es 12 cm².","why":"Multiplicar filas por cuadrados de cada fila cuenta todos los cuadrados que cubren la superficie.","misconception":"Sumar base y altura no da el área de un rectángulo.","hints":["Piensa en filas y columnas de cuadrados iguales.","Cuenta cuántos cuadrados de una unidad cubren el interior sin huecos ni solapamientos.","Un rectángulo de 4 cm por 3 cm se cubre con 12 cuadrados de 1 cm²: su área es 12 cm²."],"quiz":[{"id":"p-area:q0","question":"El área de un rectángulo de 6 m por 2 m es…","options":["8 m","12 m","12 m²"],"answer":"C","hint":"Piensa en filas y columnas de cuadrados iguales.","level":1},{"id":"p-area:q1","question":"El área se expresa en…","options":["Unidades cuadradas","Solo unidades de longitud","Grados"],"answer":"A","hint":"Piensa en filas y columnas de cuadrados iguales.","level":2},{"id":"p-area:q2","question":"Un cuadrado de lado 5 cm tiene área…","options":["20 cm²","25 cm²","10 cm²"],"answer":"B","hint":"Piensa en filas y columnas de cuadrados iguales.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-measure","stage":"primaria","subject":"Matemáticas","title":"Unidades de longitud","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Unidades de longitud","longitud","unidades de longitud","metros y centimetros"],"explanation":"Medir una longitud es compararla con una unidad. Un metro equivale a 100 centímetros y un kilómetro a 1000 metros. Al cambiar de unidad, la longitud real no cambia.","simpler":"Puedes medir el mismo objeto con unidades grandes o pequeñas: necesitarás más unidades pequeñas.","example":"Una cinta de 2 metros mide también 200 centímetros.","why":"La medida numérica depende de la unidad elegida: unidades menores producen números mayores para la misma longitud.","misconception":"Convertir unidades no altera el tamaño del objeto.","hints":["Recuerda cuántas unidades pequeñas forman una grande.","Puedes medir el mismo objeto con unidades grandes o pequeñas: necesitarás más unidades pequeñas.","Una cinta de 2 metros mide también 200 centímetros."],"quiz":[{"id":"p-measure:q0","question":"1 metro equivale a…","options":["10 cm","100 cm","1000 cm"],"answer":"B","hint":"Recuerda cuántas unidades pequeñas forman una grande.","level":1},{"id":"p-measure:q1","question":"2 kilómetros equivalen a…","options":["2000 metros","200 metros","20 metros"],"answer":"A","hint":"Recuerda cuántas unidades pequeñas forman una grande.","level":2},{"id":"p-measure:q2","question":"Al expresar una distancia en centímetros en vez de metros…","options":["La distancia crece","El objeto cambia","Cambia el número, no la distancia"],"answer":"C","hint":"Recuerda cuántas unidades pequeñas forman una grande.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-clock","stage":"primaria","subject":"Matemáticas","title":"Leer la hora","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Leer la hora","la hora","leer el reloj","horas y minutos"],"explanation":"Una hora tiene 60 minutos y un minuto 60 segundos. En un reloj de agujas, la aguja larga indica los minutos y la corta las horas. No confundas la hora del día con una duración.","simpler":"La aguja larga da una vuelta en una hora. Media hora son 30 minutos.","example":"Si empiezas a las 10:15 y pasan 30 minutos, serán las 10:45.","why":"El reloj combina unidades distintas; por eso al llegar a 60 minutos se completa otra hora.","misconception":"Una hora no tiene cien minutos.","hints":["Calcula cuántos minutos faltan y comprueba si cambia la hora.","La aguja larga da una vuelta en una hora. Media hora son 30 minutos.","Si empiezas a las 10:15 y pasan 30 minutos, serán las 10:45."],"quiz":[{"id":"p-clock:q0","question":"Media hora son…","options":["15 minutos","60 minutos","30 minutos"],"answer":"C","hint":"Calcula cuántos minutos faltan y comprueba si cambia la hora.","level":1},{"id":"p-clock:q1","question":"De 9:10 a 9:40 pasan…","options":["30 minutos","40 minutos","50 minutos"],"answer":"A","hint":"Calcula cuántos minutos faltan y comprueba si cambia la hora.","level":2},{"id":"p-clock:q2","question":"Una hora tiene…","options":["100 minutos","60 minutos","24 minutos"],"answer":"B","hint":"Calcula cuántos minutos faltan y comprueba si cambia la hora.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-mean","stage":"primaria","subject":"Matemáticas","title":"La media aritmética","grade_min":5,"grade_max":6,"school_years":["5º de Primaria","6º de Primaria"],"aliases":["La media aritmética","media aritmetica","promedio"],"explanation":"La media aritmética se calcula sumando los valores y dividiendo entre el número de datos. Representa un reparto igual del total, pero no cuenta por sí sola toda la información.","simpler":"Junta todas las cantidades y reparte el total en tantos grupos iguales como datos había.","example":"Para 4, 6 y 8, la media es (4 + 6 + 8) ÷ 3 = 6.","why":"La media es el valor que tendría cada dato si redistribuyéramos el total por igual.","misconception":"La media puede no coincidir con ninguno de los datos originales.","hints":["Cuenta los datos antes de dividir la suma.","Junta todas las cantidades y reparte el total en tantos grupos iguales como datos había.","Para 4, 6 y 8, la media es (4 + 6 + 8) ÷ 3 = 6."],"quiz":[{"id":"p-mean:q0","question":"La media de 2 y 8 es…","options":["10","5","6"],"answer":"B","hint":"Cuenta los datos antes de dividir la suma.","level":1},{"id":"p-mean:q1","question":"¿Por qué dividimos entre 3 con tres datos?","options":["Porque hay tres valores","Porque el mayor es tres","Porque siempre se divide entre tres"],"answer":"A","hint":"Cuenta los datos antes de dividir la suma.","level":2},{"id":"p-mean:q2","question":"La media de 5, 5 y 5 es…","options":["15","3","5"],"answer":"C","hint":"Cuenta los datos antes de dividir la suma.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-noun","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"El sustantivo","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El sustantivo","sustantivo","sustantivos","nombres en gramatica"],"explanation":"Un sustantivo es una palabra que nombra personas, animales, objetos, lugares o ideas. Puede ser común, como ciudad, o propio, como Málaga. Para identificarlo, observa qué nombra y cómo funciona en la oración.","simpler":"Un sustantivo sirve para nombrar: niña, perro, mesa, alegría.","example":"En «La niña abre la mochila», niña y mochila son sustantivos. «Abre» indica una acción y es un verbo.","why":"Las categorías gramaticales describen el comportamiento de las palabras, no solo si podemos ver aquello que nombran.","misconception":"No todos los sustantivos nombran cosas que se puedan tocar.","hints":["Busca la palabra que nombra una entidad o una idea.","Un sustantivo sirve para nombrar: niña, perro, mesa, alegría.","En «La niña abre la mochila», niña y mochila son sustantivos. «Abre» indica una acción y es un verbo."],"quiz":[{"id":"p-noun:q0","question":"¿Cuál es un sustantivo?","options":["Correr","Mochila","Azul"],"answer":"B","hint":"Busca la palabra que nombra una entidad o una idea.","level":1},{"id":"p-noun:q1","question":"Málaga es un nombre…","options":["Propio","Verbal","Adjetivo"],"answer":"A","hint":"Busca la palabra que nombra una entidad o una idea.","level":2},{"id":"p-noun:q2","question":"En «El perro duerme», el sustantivo es…","options":["El","Duerme","Perro"],"answer":"C","hint":"Busca la palabra que nombra una entidad o una idea.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-adjective","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"El adjetivo","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El adjetivo","adjetivo","adjetivos"],"explanation":"Un adjetivo aporta una cualidad o característica de un sustantivo. Normalmente concuerda con él en género y número cuando su forma permite esos cambios.","simpler":"El sustantivo nombra algo y el adjetivo dice cómo es.","example":"En «las montañas altas», montañas es el sustantivo y altas es el adjetivo. Ambos están en femenino plural.","why":"La concordancia ayuda a reconocer qué palabras están relacionadas dentro de un grupo nominal.","misconception":"Una misma palabra puede tener funciones distintas según la oración.","hints":["Pregunta qué palabra describe al sustantivo.","El sustantivo nombra algo y el adjetivo dice cómo es.","En «las montañas altas», montañas es el sustantivo y altas es el adjetivo. Ambos están en femenino plural."],"quiz":[{"id":"p-adjective:q0","question":"En «un coche rápido», el adjetivo es…","options":["Coche","Un","Rápido"],"answer":"C","hint":"Pregunta qué palabra describe al sustantivo.","level":1},{"id":"p-adjective:q1","question":"¿Qué expresión concuerda?","options":["Las casas blancas","Las casas blanco","La casas blancas"],"answer":"A","hint":"Pregunta qué palabra describe al sustantivo.","level":2},{"id":"p-adjective:q2","question":"El adjetivo aporta…","options":["Una operación","Una característica del sustantivo","Siempre una acción"],"answer":"B","hint":"Pregunta qué palabra describe al sustantivo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-verb","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"El verbo","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El verbo","verbo","verbos"],"explanation":"El verbo puede expresar una acción, un estado o un proceso. Su forma puede indicar persona, número y tiempo. No todos los verbos describen movimientos.","simpler":"Correr es una acción; estar puede expresar un estado. Los dos son verbos.","example":"«Ayer jugamos» se sitúa en el pasado; «mañana jugaremos», en el futuro.","why":"La conjugación sitúa lo que se dice en el tiempo y lo relaciona con quienes participan.","misconception":"Ser y estar también son verbos aunque no describan una acción visible.","hints":["Busca la palabra que cambia cuando cambias hoy por ayer o mañana.","Correr es una acción; estar puede expresar un estado. Los dos son verbos.","«Ayer jugamos» se sitúa en el pasado; «mañana jugaremos», en el futuro."],"quiz":[{"id":"p-verb:q0","question":"En «Marta lee», el verbo es…","options":["Lee","Marta","Ninguno"],"answer":"A","hint":"Busca la palabra que cambia cuando cambias hoy por ayer o mañana.","level":1},{"id":"p-verb:q1","question":"«Jugaremos» indica normalmente…","options":["Pasado","Presente","Futuro"],"answer":"C","hint":"Busca la palabra que cambia cuando cambias hoy por ayer o mañana.","level":2},{"id":"p-verb:q2","question":"¿Todos los verbos indican movimiento?","options":["Sí","No","Solo en plural"],"answer":"B","hint":"Busca la palabra que cambia cuando cambias hoy por ayer o mañana.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-subject","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"Sujeto y predicado","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Sujeto y predicado","sujeto y predicado","el sujeto","el predicado"],"explanation":"En muchas oraciones, el sujeto es el grupo que concuerda en número y persona con el verbo. El predicado contiene el verbo y lo que se dice del sujeto. El sujeto puede no estar escrito y hay oraciones impersonales.","simpler":"Busca primero el verbo. Después observa qué grupo concuerda con él.","example":"En «Los pájaros cantan», «los pájaros» es el sujeto y «cantan» el predicado. En «Llueve» no hay un sujeto que realice la lluvia.","why":"La concordancia proporciona una pista gramatical más fiable que identificar siempre un supuesto agente.","misconception":"No basta preguntar quién hace la acción: no todos los verbos expresan acciones.","hints":["Comprueba la concordancia con el verbo.","Busca primero el verbo. Después observa qué grupo concuerda con él.","En «Los pájaros cantan», «los pájaros» es el sujeto y «cantan» el predicado. En «Llueve» no hay un sujeto que realice la lluvia."],"quiz":[{"id":"p-subject:q0","question":"El sujeto de «Las niñas leen» es…","options":["Leen","Las niñas","Las"],"answer":"B","hint":"Comprueba la concordancia con el verbo.","level":1},{"id":"p-subject:q1","question":"En «El gato duerme», el predicado es…","options":["Duerme","El gato","El"],"answer":"A","hint":"Comprueba la concordancia con el verbo.","level":2},{"id":"p-subject:q2","question":"¿Toda oración tiene un sujeto escrito?","options":["Sí","Solo si es corta","No"],"answer":"C","hint":"Comprueba la concordancia con el verbo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-accent","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"Acentuación","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Acentuación","acentuacion","tildes","agudas llanas y esdrujulas"],"explanation":"La sílaba tónica es la que pronunciamos con más fuerza. Las agudas llevan tilde si terminan en vocal, n o s; las llanas, si no terminan en vocal, n o s. Las esdrújulas siempre llevan tilde. Existen casos especiales que se estudian aparte.","simpler":"Escucha dónde suena la fuerza de la palabra. Después aplica la regla de su grupo.","example":"«Café» es aguda y termina en vocal; «árbol» es llana y termina en l; «música» es esdrújula.","why":"La tilde sigue convenciones de escritura y no aparece en todas las sílabas tónicas.","misconception":"Acento prosódico y tilde no son lo mismo.","hints":["Pronuncia la palabra antes de mirar su última letra.","Escucha dónde suena la fuerza de la palabra. Después aplica la regla de su grupo.","«Café» es aguda y termina en vocal; «árbol» es llana y termina en l; «música» es esdrújula."],"quiz":[{"id":"p-accent:q0","question":"¿Qué palabra es esdrújula?","options":["Papel","Casa","Música"],"answer":"C","hint":"Pronuncia la palabra antes de mirar su última letra.","level":1},{"id":"p-accent:q1","question":"«Café» lleva tilde porque es…","options":["Aguda terminada en vocal","Llana terminada en consonante","Monosílaba siempre"],"answer":"A","hint":"Pronuncia la palabra antes de mirar su última letra.","level":2},{"id":"p-accent:q2","question":"¿Dónde está la sílaba tónica de árbol?","options":["En bol","En ár","No tiene"],"answer":"B","hint":"Pronuncia la palabra antes de mirar su última letra.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-summary","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"Hacer un resumen","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Hacer un resumen","resumen","resumir","hacer un resumen"],"explanation":"Resumir consiste en expresar las ideas principales de un texto con menos palabras, sin cambiar su sentido. Primero comprende, después selecciona lo esencial y finalmente redacta con tus palabras. No añadas datos que no aparecen.","simpler":"Cuenta lo más importante del texto, sin copiarlo entero ni inventar detalles.","example":"Si un texto explica que las abejas transportan polen al visitar flores, el resumen debe conservar esa idea; no necesita repetir cada ejemplo.","why":"Seleccionar lo esencial exige comprender las relaciones entre las ideas, no únicamente reducir la longitud.","misconception":"Un resumen no es solo quitar frases al azar.","hints":["Pregúntate qué información no puede faltar para entender el texto.","Cuenta lo más importante del texto, sin copiarlo entero ni inventar detalles.","Si un texto explica que las abejas transportan polen al visitar flores, el resumen debe conservar esa idea; no necesita repetir cada ejemplo."],"quiz":[{"id":"p-summary:q0","question":"Un resumen debe conservar…","options":["Todas las palabras","Las ideas principales","Solo el título"],"answer":"B","hint":"Pregúntate qué información no puede faltar para entender el texto.","level":1},{"id":"p-summary:q1","question":"¿Qué haces primero?","options":["Comprender el texto","Inventar un final","Acortarlo sin leer"],"answer":"A","hint":"Pregúntate qué información no puede faltar para entender el texto.","level":2},{"id":"p-summary:q2","question":"¿Debemos añadir datos nuevos al resumen?","options":["Siempre","Para hacerlo más largo","No"],"answer":"C","hint":"Pregúntate qué información no puede faltar para entender el texto.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-water","stage":"primaria","subject":"Conocimiento del Medio","title":"El ciclo del agua","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El ciclo del agua","ciclo del agua","el ciclo del agua"],"explanation":"El agua circula entre la superficie terrestre y la atmósfera. Puede evaporarse, condensarse formando gotitas o cristales y caer como precipitación. También se infiltra en el suelo o fluye hacia ríos y mares. No es una única ruta igual para cada gota.","simpler":"El agua puede pasar al aire como vapor, formar nubes y volver a la superficie como lluvia o nieve.","example":"Un charco disminuye cuando parte del agua se evapora. El vapor puede condensarse y participar en la formación de nubes.","why":"La energía solar y la gravedad impulsan distintas partes del ciclo; el agua cambia de lugar y de estado.","misconception":"Las nubes no son vapor de agua visible: contienen gotitas o cristales.","hints":["Sigue el agua y nombra cada cambio.","El agua puede pasar al aire como vapor, formar nubes y volver a la superficie como lluvia o nieve.","Un charco disminuye cuando parte del agua se evapora. El vapor puede condensarse y participar en la formación de nubes."],"quiz":[{"id":"p-water:q0","question":"El paso de agua líquida a vapor se llama…","options":["Condensación","Precipitación","Evaporación"],"answer":"C","hint":"Sigue el agua y nombra cada cambio.","level":1},{"id":"p-water:q1","question":"La lluvia es un ejemplo de…","options":["Precipitación","Evaporación","Infiltración siempre"],"answer":"A","hint":"Sigue el agua y nombra cada cambio.","level":2},{"id":"p-water:q2","question":"El agua que entra en el suelo realiza…","options":["Fusión","Infiltración","Combustión"],"answer":"B","hint":"Sigue el agua y nombra cada cambio.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-photosynthesis","stage":"primaria","subject":"Conocimiento del Medio","title":"La fotosíntesis","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La fotosíntesis","fotosintesis","la fotosintesis"],"explanation":"En la fotosíntesis, las plantas y otros organismos fotosintéticos utilizan energía luminosa para formar materia orgánica a partir de agua y dióxido de carbono. En la fotosíntesis oxigénica se libera oxígeno. Las plantas también respiran.","simpler":"La planta usa luz como energía para fabricar materia orgánica con agua y dióxido de carbono.","example":"Las hojas de una planta reciben luz; el agua llega desde las raíces y el dióxido de carbono entra principalmente por pequeños poros.","why":"La luz aporta energía, pero la materia orgánica se construye con materia: principalmente agua y dióxido de carbono.","misconception":"Las plantas no se alimentan simplemente de la luz ni dejan de respirar por hacer fotosíntesis.","hints":["Distingue los materiales que entran y la energía que permite transformarlos.","La planta usa luz como energía para fabricar materia orgánica con agua y dióxido de carbono.","Las hojas de una planta reciben luz; el agua llega desde las raíces y el dióxido de carbono entra principalmente por pequeños poros."],"quiz":[{"id":"p-photosynthesis:q0","question":"¿Qué aporta la luz?","options":["Tierra","Energía","Agua"],"answer":"B","hint":"Distingue los materiales que entran y la energía que permite transformarlos.","level":1},{"id":"p-photosynthesis:q1","question":"¿Qué gas utilizan para formar materia orgánica?","options":["Dióxido de carbono","Helio","Neón"],"answer":"A","hint":"Distingue los materiales que entran y la energía que permite transformarlos.","level":2},{"id":"p-photosynthesis:q2","question":"¿Las plantas también respiran?","options":["No","Solo de pequeñas","Sí"],"answer":"C","hint":"Distingue los materiales que entran y la energía que permite transformarlos.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-states","stage":"primaria","subject":"Conocimiento del Medio","title":"Estados de la materia","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Estados de la materia","estados de la materia","solido liquido y gas"],"explanation":"La materia puede presentarse en distintos estados. En un sólido se conserva aproximadamente la forma y el volumen; un líquido conserva aproximadamente el volumen y adopta la forma del recipiente; un gas se expande para ocupar el espacio disponible.","simpler":"Un cubito mantiene su forma; el agua líquida se adapta al vaso; un gas puede extenderse.","example":"El hielo se funde y se convierte en agua líquida. Sigue siendo agua: ha cambiado de estado.","why":"Al cambiar la energía y las condiciones, cambia la organización y movilidad de las partículas.","misconception":"Un cambio de estado no implica necesariamente una nueva sustancia.","hints":["Pregunta si cambió la sustancia o solo su estado.","Un cubito mantiene su forma; el agua líquida se adapta al vaso; un gas puede extenderse.","El hielo se funde y se convierte en agua líquida. Sigue siendo agua: ha cambiado de estado."],"quiz":[{"id":"p-states:q0","question":"El paso de sólido a líquido se llama…","options":["Fusión","Evaporación","Condensación"],"answer":"A","hint":"Pregunta si cambió la sustancia o solo su estado.","level":1},{"id":"p-states:q1","question":"¿Qué estado ocupa el espacio disponible?","options":["Sólido","Líquido siempre","Gas"],"answer":"C","hint":"Pregunta si cambió la sustancia o solo su estado.","level":2},{"id":"p-states:q2","question":"Al fundirse el hielo…","options":["Deja de ser agua","Cambia de estado","Se convierte en madera"],"answer":"B","hint":"Pregunta si cambió la sustancia o solo su estado.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-ecosystem","stage":"primaria","subject":"Conocimiento del Medio","title":"Los ecosistemas","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Los ecosistemas","ecosistema","ecosistemas"],"explanation":"Un ecosistema incluye seres vivos, el medio físico y sus relaciones. El agua, la luz y el suelo influyen en los organismos; los organismos también modifican su entorno. Cambiar un elemento puede afectar a otros.","simpler":"No estudias solo los animales: también dónde viven y cómo se relacionan.","example":"En una charca hay plantas, insectos y otros organismos, junto con agua, luz y temperatura. Sus relaciones forman parte del ecosistema.","why":"Las relaciones hacen que un cambio se propague; por eso estudiamos el sistema y no solo cada pieza por separado.","misconception":"Un ecosistema no es únicamente una lista de especies.","hints":["Busca tanto los componentes vivos como los no vivos.","No estudias solo los animales: también dónde viven y cómo se relacionan.","En una charca hay plantas, insectos y otros organismos, junto con agua, luz y temperatura. Sus relaciones forman parte del ecosistema."],"quiz":[{"id":"p-ecosystem:q0","question":"¿Qué incluye un ecosistema?","options":["Solo animales","Solo agua","Seres vivos, medio y relaciones"],"answer":"C","hint":"Busca tanto los componentes vivos como los no vivos.","level":1},{"id":"p-ecosystem:q1","question":"La luz es un factor…","options":["Del medio físico","Siempre un animal","Sin influencia"],"answer":"A","hint":"Busca tanto los componentes vivos como los no vivos.","level":2},{"id":"p-ecosystem:q2","question":"Un cambio en el agua puede afectar…","options":["Solo al color","A distintos organismos","A ninguno nunca"],"answer":"B","hint":"Busca tanto los componentes vivos como los no vivos.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-maps","stage":"primaria","subject":"Conocimiento del Medio","title":"Los mapas","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Los mapas","mapas","mapa","escala de un mapa"],"explanation":"Un mapa representa un espacio de forma reducida y selecciona cierta información. La leyenda explica sus símbolos y la escala relaciona distancias del mapa con distancias reales. Hay mapas que sirven para tareas diferentes.","simpler":"La leyenda te dice qué significa cada dibujo. La escala indica cuánto se ha reducido la distancia.","example":"Si 1 cm en el mapa representa 1 km real, dos puntos separados 3 cm están a 3 km en línea recta según esa escala.","why":"Un mapa simplifica la realidad para una finalidad; elegir el tipo adecuado evita interpretaciones equivocadas.","misconception":"La distancia en línea recta puede diferir de la distancia por carretera.","hints":["Lee antes la leyenda y la escala.","La leyenda te dice qué significa cada dibujo. La escala indica cuánto se ha reducido la distancia.","Si 1 cm en el mapa representa 1 km real, dos puntos separados 3 cm están a 3 km en línea recta según esa escala."],"quiz":[{"id":"p-maps:q0","question":"¿Para qué sirve la leyenda?","options":["Para medir el tiempo","Para interpretar símbolos","Para cambiar el norte"],"answer":"B","hint":"Lee antes la leyenda y la escala.","level":1},{"id":"p-maps:q1","question":"Con 1 cm = 1 km, 4 cm representan…","options":["4 km","40 km","400 km"],"answer":"A","hint":"Lee antes la leyenda y la escala.","level":2},{"id":"p-maps:q2","question":"La escala relaciona…","options":["Colores y animales","Días y horas","Distancias representadas y reales"],"answer":"C","hint":"Lee antes la leyenda y la escala.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"p-to-be","stage":"primaria","subject":"Lengua Extranjera: Inglés","title":"El verbo to be","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El verbo to be","to be","verbo to be","am is are"],"explanation":"To be puede corresponder a ser o estar según el contexto. En presente usamos I am; he, she, it is; y you, we, they are. Para preguntar, colocamos esa forma verbal antes del sujeto.","simpler":"Recuerda tres formas: am con I, is con he/she/it y are con you/we/they.","example":"«She is happy» significa «Ella está contenta». La pregunta es «Is she happy?».","why":"La forma verbal depende del sujeto; en estas preguntas no añadimos do porque invertimos sujeto y to be.","misconception":"To be no se traduce siempre con la misma palabra española.","hints":["Identifica primero el sujeto.","Recuerda tres formas: am con I, is con he/she/it y are con you/we/they.","«She is happy» significa «Ella está contenta». La pregunta es «Is she happy?»."],"quiz":[{"id":"p-to-be:q0","question":"Completa: I ___ ready.","options":["Is","Are","Am"],"answer":"C","hint":"Identifica primero el sujeto.","level":1},{"id":"p-to-be:q1","question":"Completa: They ___ students.","options":["Are","Is","Am"],"answer":"A","hint":"Identifica primero el sujeto.","level":2},{"id":"p-to-be:q2","question":"¿Qué pregunta está bien formada?","options":["She is happy? siempre","Is she happy?","Does she is happy?"],"answer":"B","hint":"Identifica primero el sujeto.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-integers","stage":"eso","subject":"Matemáticas","title":"Números enteros","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Números enteros","numeros enteros","enteros","negativos"],"explanation":"Los enteros incluyen negativos, cero y positivos. En la recta numérica, un número situado más a la derecha es mayor. Para sumar un negativo puedes desplazarte a la izquierda.","simpler":"Los negativos están a la izquierda del cero. Entre −2 y −5, −2 está más a la derecha y es mayor.","example":"Partiendo de 3, sumar −5 significa moverte cinco unidades a la izquierda: llegas a −2.","why":"El orden depende de la posición, mientras que el valor absoluto mide la distancia al cero.","misconception":"El entero con mayor valor absoluto no es siempre el mayor.","hints":["Dibuja una recta y sitúa el cero.","Los negativos están a la izquierda del cero. Entre −2 y −5, −2 está más a la derecha y es mayor.","Partiendo de 3, sumar −5 significa moverte cinco unidades a la izquierda: llegas a −2."],"quiz":[{"id":"e-integers:q0","question":"¿Cuál es mayor?","options":["−5","−2","−8"],"answer":"B","hint":"Dibuja una recta y sitúa el cero.","level":1},{"id":"e-integers:q1","question":"3 + (−5) es…","options":["−2","2","8"],"answer":"A","hint":"Dibuja una recta y sitúa el cero.","level":2},{"id":"e-integers:q2","question":"El opuesto de −7 es…","options":["−14","0","7"],"answer":"C","hint":"Dibuja una recta y sitúa el cero.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-equation","stage":"eso","subject":"Matemáticas","title":"Ecuaciones de primer grado","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Ecuaciones de primer grado","ecuaciones de primer grado","ecuacion lineal","ecuaciones lineales"],"explanation":"Una ecuación afirma que dos expresiones tienen el mismo valor. Resolverla es encontrar el valor de la incógnita que hace verdadera esa igualdad. Puedes operar en ambos miembros de forma equivalente para conservarla.","simpler":"Piensa en una balanza: cambia ambos lados de la misma manera para que sigan equilibrados.","example":"En 2x + 3 = 11, restamos 3 en ambos lados: 2x = 8. Después dividimos ambos por 2: x = 4.","why":"Las transformaciones equivalentes conservan el conjunto de soluciones cuando cumplen sus condiciones.","misconception":"«Pasar cambiando de signo» es una abreviatura, no una regla mágica sin operación equivalente.","hints":["Deshaz las operaciones en orden inverso y conserva la igualdad.","Piensa en una balanza: cambia ambos lados de la misma manera para que sigan equilibrados.","En 2x + 3 = 11, restamos 3 en ambos lados: 2x = 8. Después dividimos ambos por 2: x = 4."],"quiz":[{"id":"e-equation:q0","question":"La solución de x + 5 = 9 es…","options":["14","5","4"],"answer":"C","hint":"Deshaz las operaciones en orden inverso y conserva la igualdad.","level":1},{"id":"e-equation:q1","question":"Para conservar una igualdad al restar 3, lo hacemos…","options":["En ambos miembros","Solo a la izquierda","Solo a la derecha"],"answer":"A","hint":"Deshaz las operaciones en orden inverso y conserva la igualdad.","level":2},{"id":"e-equation:q2","question":"¿Cómo comprobamos una solución?","options":["Mirando solo el signo","Sustituyendo en la ecuación original","Sumando todos los números"],"answer":"B","hint":"Deshaz las operaciones en orden inverso y conserva la igualdad.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-powers","stage":"eso","subject":"Matemáticas","title":"Potencias","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Potencias","potencias","potencia","exponentes"],"explanation":"Una potencia con exponente natural expresa un producto repetido de la base. En a elevado a n, n indica cuántos factores iguales a a se multiplican. No significa multiplicar base por exponente.","simpler":"2³ significa multiplicar tres factores iguales: 2 × 2 × 2. No significa hacer 2 × 3.","example":"3² = 3 × 3 = 9. Para una base distinta de cero, a⁰ = 1.","why":"Las reglas de potencias condensan cómo se agrupan productos de factores iguales.","misconception":"El exponente no es un factor que multiplicas directamente por la base.","hints":["Escribe el producto completo antes de calcular.","2³ significa multiplicar tres factores iguales: 2 × 2 × 2. No significa hacer 2 × 3.","3² = 3 × 3 = 9. Para una base distinta de cero, a⁰ = 1."],"quiz":[{"id":"e-powers:q0","question":"El resultado de la potencia 2³ es…","options":["8","6","9"],"answer":"A","hint":"Escribe el producto completo antes de calcular.","level":1},{"id":"e-powers:q1","question":"5² significa…","options":["5 + 5","5 × 2","5 × 5"],"answer":"C","hint":"Escribe el producto completo antes de calcular.","level":2},{"id":"e-powers:q2","question":"Para a distinto de cero, a⁰ vale…","options":["0","1","a"],"answer":"B","hint":"Escribe el producto completo antes de calcular.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-proportionality","stage":"eso","subject":"Matemáticas","title":"Proporcionalidad directa","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Proporcionalidad directa","proporcionalidad directa","proporciones"],"explanation":"Dos magnitudes son directamente proporcionales si una se obtiene multiplicando la otra por una constante. Al duplicar una, se duplica la otra. Que ambas aumenten no basta para demostrar proporcionalidad.","simpler":"Busca si el cociente entre las cantidades correspondientes es siempre el mismo.","example":"Si cada cuaderno cuesta 3 €, 2 cuestan 6 € y 5 cuestan 15 €, sin descuentos ni gastos fijos.","why":"La constante de proporcionalidad permite expresar la relación como y = kx.","misconception":"Una relación con una cuota fija inicial no suele ser proporcional directa.","hints":["Calcula cuánto corresponde a una unidad.","Busca si el cociente entre las cantidades correspondientes es siempre el mismo.","Si cada cuaderno cuesta 3 €, 2 cuestan 6 € y 5 cuestan 15 €, sin descuentos ni gastos fijos."],"quiz":[{"id":"e-proportionality:q0","question":"Con precio fijo de 4 € por pieza, 3 piezas cuestan…","options":["7 €","12 €","1 €"],"answer":"B","hint":"Calcula cuánto corresponde a una unidad.","level":1},{"id":"e-proportionality:q1","question":"En proporcionalidad directa, al duplicar una magnitud la otra…","options":["Se duplica","Se divide siempre por dos","No cambia"],"answer":"A","hint":"Calcula cuánto corresponde a una unidad.","level":2},{"id":"e-proportionality:q2","question":"¿Basta con que ambas aumenten?","options":["Sí","Solo si son positivas","No"],"answer":"C","hint":"Calcula cuánto corresponde a una unidad.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-pythagoras","stage":"eso","subject":"Matemáticas","title":"Teorema de Pitágoras","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Teorema de Pitágoras","pitagoras","teorema de pitagoras"],"explanation":"En un triángulo rectángulo, el cuadrado de la hipotenusa es igual a la suma de los cuadrados de los catetos. La hipotenusa está enfrente del ángulo recto y es el lado más largo. Comprueba primero que el triángulo sea rectángulo.","simpler":"Si los catetos son a y b y la hipotenusa c, entonces a² + b² = c².","example":"Con catetos 3 y 4, c² = 9 + 16 = 25; como es una longitud positiva, c = 5.","why":"La relación se establece entre áreas de cuadrados construidos sobre los lados, no entre sus longitudes sin elevar al cuadrado.","misconception":"No sumes las longitudes de los catetos para obtener la hipotenusa.","hints":["Identifica la hipotenusa antes de sustituir los valores.","Si los catetos son a y b y la hipotenusa c, entonces a² + b² = c².","Con catetos 3 y 4, c² = 9 + 16 = 25; como es una longitud positiva, c = 5."],"quiz":[{"id":"e-pythagoras:q0","question":"Con catetos 6 y 8, la hipotenusa mide…","options":["14","2","10"],"answer":"C","hint":"Identifica la hipotenusa antes de sustituir los valores.","level":1},{"id":"e-pythagoras:q1","question":"El teorema se aplica directamente a triángulos…","options":["Rectángulos","De cualquier tipo","Solo equiláteros"],"answer":"A","hint":"Identifica la hipotenusa antes de sustituir los valores.","level":2},{"id":"e-pythagoras:q2","question":"La hipotenusa está…","options":["Junto al ángulo más pequeño siempre","Frente al ángulo recto","En el interior del triángulo"],"answer":"B","hint":"Identifica la hipotenusa antes de sustituir los valores.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-functions","stage":"eso","subject":"Matemáticas","title":"Las funciones","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Las funciones","funciones","funcion matematica"],"explanation":"Una función asigna a cada valor permitido de entrada un único valor de salida. El dominio reúne las entradas admitidas. Una fórmula, tabla o gráfica puede describir la misma relación.","simpler":"Cada entrada tiene una sola salida, aunque distintas entradas puedan tener la misma salida.","example":"En f(x) = 2x + 1, la entrada 3 produce 7. La entrada 0 produce 1.","why":"La unicidad se exige por entrada, no por salida: una misma entrada no puede producir dos salidas diferentes dentro de la misma función.","misconception":"Dos entradas pueden compartir salida sin dejar de ser una función.","hints":["Sustituye la variable por el valor de entrada.","Cada entrada tiene una sola salida, aunque distintas entradas puedan tener la misma salida.","En f(x) = 2x + 1, la entrada 3 produce 7. La entrada 0 produce 1."],"quiz":[{"id":"e-functions:q0","question":"Si f(x) = 2x + 1, f(4) vale…","options":["8","9","5"],"answer":"B","hint":"Sustituye la variable por el valor de entrada.","level":1},{"id":"e-functions:q1","question":"Cada entrada admitida debe tener…","options":["Una única salida","Todas las salidas posibles","Ninguna salida"],"answer":"A","hint":"Sustituye la variable por el valor de entrada.","level":2},{"id":"e-functions:q2","question":"El dominio contiene…","options":["Solo los resultados","Los nombres de los ejes","Las entradas permitidas"],"answer":"C","hint":"Sustituye la variable por el valor de entrada.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-probability","stage":"eso","subject":"Matemáticas","title":"Probabilidad","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Probabilidad","probabilidad","probabilidades"],"explanation":"La probabilidad mide la posibilidad de un suceso. Si todos los resultados elementales son igual de probables, se calcula dividiendo casos favorables entre casos posibles. Un resultado más probable no es seguro.","simpler":"Cuenta primero las opciones posibles y después las que cumplen lo pedido, solo si todas tienen la misma posibilidad.","example":"En un dado equilibrado, obtener un número par tiene probabilidad 3/6 = 1/2.","why":"La probabilidad describe incertidumbre; las frecuencias observadas pueden variar en muestras pequeñas.","misconception":"Una probabilidad alta no garantiza que el suceso ocurra en un intento.","hints":["Comprueba la equiprobabilidad antes de contar.","Cuenta primero las opciones posibles y después las que cumplen lo pedido, solo si todas tienen la misma posibilidad.","En un dado equilibrado, obtener un número par tiene probabilidad 3/6 = 1/2."],"quiz":[{"id":"e-probability:q0","question":"En un dado equilibrado, obtener un 6 tiene probabilidad…","options":["1/2","1","1/6"],"answer":"C","hint":"Comprueba la equiprobabilidad antes de contar.","level":1},{"id":"e-probability:q1","question":"La probabilidad de un suceso imposible es…","options":["0","1","2"],"answer":"A","hint":"Comprueba la equiprobabilidad antes de contar.","level":2},{"id":"e-probability:q2","question":"La regla casos favorables/casos posibles exige…","options":["Resultados todos distintos de cero","Resultados elementales equiprobables","Que el suceso sea seguro"],"answer":"B","hint":"Comprueba la equiprobabilidad antes de contar.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-cell","stage":"eso","subject":"Biología y Geología","title":"La célula","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["La célula","celula","celulas","la celula"],"explanation":"La célula es la unidad estructural y funcional básica de los seres vivos. Las células tienen membrana plasmática, material genético y un medio interno donde ocurren procesos. Las eucariotas tienen núcleo; las procariotas no tienen un núcleo delimitado por membrana.","simpler":"Los seres vivos están formados por células. Algunas tienen núcleo y otras no.","example":"Una bacteria es un organismo procariota; una célula de una hoja es eucariota y suele tener pared celular y cloroplastos.","why":"El núcleo es una forma de organizar el ADN, no un requisito para que exista una célula.","misconception":"Las procariotas tienen material genético aunque carezcan de núcleo membranoso.","hints":["Distingue tener material genético de tener núcleo.","Los seres vivos están formados por células. Algunas tienen núcleo y otras no.","Una bacteria es un organismo procariota; una célula de una hoja es eucariota y suele tener pared celular y cloroplastos."],"quiz":[{"id":"e-cell:q0","question":"¿Qué tipo tiene núcleo delimitado por membrana?","options":["Eucariota","Procariota","Todas sin excepción"],"answer":"A","hint":"Distingue tener material genético de tener núcleo.","level":1},{"id":"e-cell:q1","question":"Una bacteria es normalmente…","options":["Un tejido","Una célula sin material genético","Un organismo procariota"],"answer":"C","hint":"Distingue tener material genético de tener núcleo.","level":2},{"id":"e-cell:q2","question":"¿Qué estructura delimita una célula?","options":["Solo el núcleo","La membrana plasmática","La atmósfera"],"answer":"B","hint":"Distingue tener material genético de tener núcleo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-atoms","stage":"eso","subject":"Física y Química","title":"Átomos y moléculas","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Átomos y moléculas","atomos y moleculas","atomos","moleculas"],"explanation":"Un átomo es una unidad de un elemento químico. Tiene núcleo con protones y, normalmente, neutrones; los electrones ocupan regiones alrededor del núcleo. Una molécula reúne átomos enlazados. No todas las sustancias están formadas por moléculas discretas.","simpler":"Un átomo pertenece a un elemento; una molécula puede unir varios átomos.","example":"H₂O indica una molécula con dos átomos de hidrógeno y uno de oxígeno. No significa dos moléculas de agua.","why":"Las fórmulas muestran proporciones y composición; su interpretación depende del tipo de sustancia.","misconception":"Un átomo no es una pequeña esfera con órbitas planetarias exactas.","hints":["Separa elemento, átomo y molécula.","Un átomo pertenece a un elemento; una molécula puede unir varios átomos.","H₂O indica una molécula con dos átomos de hidrógeno y uno de oxígeno. No significa dos moléculas de agua."],"quiz":[{"id":"e-atoms:q0","question":"Una molécula de H₂O contiene…","options":["Dos oxígenos y un hidrógeno","Dos hidrógenos y un oxígeno","Solo hidrógeno"],"answer":"B","hint":"Separa elemento, átomo y molécula.","level":1},{"id":"e-atoms:q1","question":"La carga del protón es…","options":["Positiva","Negativa","Nula siempre"],"answer":"A","hint":"Separa elemento, átomo y molécula.","level":2},{"id":"e-atoms:q2","question":"¿Toda sustancia está hecha de moléculas discretas?","options":["Sí","Solo las sólidas","No"],"answer":"C","hint":"Separa elemento, átomo y molécula.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-density","stage":"eso","subject":"Física y Química","title":"La densidad","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["La densidad","densidad","masa y volumen"],"explanation":"La densidad relaciona masa y volumen: densidad = masa/volumen. Describe cuánta masa corresponde a cada unidad de volumen. Compara valores usando las mismas unidades y teniendo en cuenta las condiciones.","simpler":"Dos objetos del mismo volumen pueden tener distinta masa; el más masivo tiene mayor densidad media.","example":"Si una muestra tiene masa 20 g y volumen 10 cm³, su densidad es 2 g/cm³.","why":"La densidad es una razón: aumentar la cantidad de la misma sustancia no cambia esa razón bajo las mismas condiciones.","misconception":"Masa, peso y densidad no son la misma magnitud.","hints":["Divide la masa por el volumen y conserva las unidades.","Dos objetos del mismo volumen pueden tener distinta masa; el más masivo tiene mayor densidad media.","Si una muestra tiene masa 20 g y volumen 10 cm³, su densidad es 2 g/cm³."],"quiz":[{"id":"e-density:q0","question":"20 g en 10 cm³ dan una densidad de…","options":["200 g/cm³","10 g/cm³","2 g/cm³"],"answer":"C","hint":"Divide la masa por el volumen y conserva las unidades.","level":1},{"id":"e-density:q1","question":"La densidad relaciona…","options":["Masa y volumen","Tiempo y velocidad","Longitud y temperatura solamente"],"answer":"A","hint":"Divide la masa por el volumen y conserva las unidades.","level":2},{"id":"e-density:q2","question":"Si duplicas masa y volumen de una muestra homogénea…","options":["La densidad se duplica","La densidad se conserva","La densidad se hace cero"],"answer":"B","hint":"Divide la masa por el volumen y conserva las unidades.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-force","stage":"eso","subject":"Física y Química","title":"Las fuerzas","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Las fuerzas","fuerzas","la fuerza","fuerza y movimiento"],"explanation":"Una fuerza es una interacción que puede cambiar el movimiento o deformar un cuerpo. La fuerza neta es la suma vectorial de las fuerzas. Si es cero, un cuerpo puede estar en reposo o moverse con velocidad constante.","simpler":"No hace falta una fuerza neta para mantener una velocidad constante; sí para cambiarla.","example":"Un libro apoyado en una mesa recibe su peso hacia abajo y la fuerza de la mesa hacia arriba. Si se equilibran, no acelera.","why":"La aceleración responde a la fuerza neta; el estado de movimiento no necesita cambiar si esta es cero.","misconception":"Movimiento y fuerza neta no son equivalentes.","hints":["Dibuja todas las fuerzas y sus direcciones.","No hace falta una fuerza neta para mantener una velocidad constante; sí para cambiarla.","Un libro apoyado en una mesa recibe su peso hacia abajo y la fuerza de la mesa hacia arriba. Si se equilibran, no acelera."],"quiz":[{"id":"e-force:q0","question":"La unidad de fuerza del SI es…","options":["Newton","Julio","Vatio"],"answer":"A","hint":"Dibuja todas las fuerzas y sus direcciones.","level":1},{"id":"e-force:q1","question":"Con fuerza neta cero, un cuerpo puede…","options":["Solo estar parado","Acelerar siempre","Mantener velocidad constante"],"answer":"C","hint":"Dibuja todas las fuerzas y sus direcciones.","level":2},{"id":"e-force:q2","question":"La fuerza neta es…","options":["La mayor fuerza sin más","La suma vectorial de las fuerzas","Siempre el peso"],"answer":"B","hint":"Dibuja todas las fuerzas y sus direcciones.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-energy","stage":"eso","subject":"Física y Química","title":"La energía","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["La energía","energia","la energia","conservacion de la energia"],"explanation":"La energía permite describir cambios y transferencias en un sistema. Puede almacenarse de distintas formas y transferirse mediante trabajo o calor, entre otros procesos. La energía total se conserva en un sistema aislado; su utilidad para producir ciertos cambios puede disminuir.","simpler":"La energía no desaparece: se transforma o se transfiere. No todas sus formas son igual de aprovechables.","example":"Al frenar una bicicleta, parte de su energía cinética se transforma en energía interna de frenos, ruedas y entorno.","why":"La conservación requiere contabilizar también las transferencias y formas de energía menos evidentes.","misconception":"Conservar energía no significa que toda pueda recuperarse para el mismo uso.","hints":["Define qué incluyes dentro del sistema.","La energía no desaparece: se transforma o se transfiere. No todas sus formas son igual de aprovechables.","Al frenar una bicicleta, parte de su energía cinética se transforma en energía interna de frenos, ruedas y entorno."],"quiz":[{"id":"e-energy:q0","question":"La unidad de energía del SI es…","options":["Newton","Julio","Metro"],"answer":"B","hint":"Define qué incluyes dentro del sistema.","level":1},{"id":"e-energy:q1","question":"Al frenar, parte de la energía cinética…","options":["Se transforma en energía interna","Deja de existir","Se convierte en masa nula"],"answer":"A","hint":"Define qué incluyes dentro del sistema.","level":2},{"id":"e-energy:q2","question":"En un sistema aislado, la energía total…","options":["Aumenta siempre","Desaparece","Se conserva"],"answer":"C","hint":"Define qué incluyes dentro del sistema.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-reaction","stage":"eso","subject":"Física y Química","title":"Reacciones químicas","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Reacciones químicas","reacciones quimicas","reaccion quimica"],"explanation":"En una reacción química se transforman unas sustancias, reactivos, en otras, productos. Los átomos se reorganizan y, en las reacciones químicas ordinarias, se conserva el número de átomos de cada elemento. Ajustar una ecuación respeta esa conservación.","simpler":"Los átomos se recombinan: no se inventan ni desaparecen durante una reacción química ordinaria.","example":"2 H₂ + O₂ → 2 H₂O conserva cuatro átomos de hidrógeno y dos de oxígeno a cada lado.","why":"Los coeficientes indican cantidades relativas de partículas sin alterar su composición.","misconception":"Cambiar un subíndice puede cambiar la sustancia; no es el método para ajustar.","hints":["Cuenta cada elemento en ambos miembros.","Los átomos se recombinan: no se inventan ni desaparecen durante una reacción química ordinaria.","2 H₂ + O₂ → 2 H₂O conserva cuatro átomos de hidrógeno y dos de oxígeno a cada lado."],"quiz":[{"id":"e-reaction:q0","question":"Las sustancias iniciales se llaman…","options":["Productos","Disolventes siempre","Reactivos"],"answer":"C","hint":"Cuenta cada elemento en ambos miembros.","level":1},{"id":"e-reaction:q1","question":"En 2 H₂ + O₂ → 2 H₂O hay a cada lado…","options":["4 H y 2 O","2 H y 4 O","1 H y 1 O"],"answer":"A","hint":"Cuenta cada elemento en ambos miembros.","level":2},{"id":"e-reaction:q2","question":"Ajustar cambia principalmente…","options":["Los símbolos de los elementos","Los coeficientes","La identidad de los átomos"],"answer":"B","hint":"Cuenta cada elemento en ambos miembros.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-tectonics","stage":"eso","subject":"Biología y Geología","title":"Tectónica de placas","grade_min":3,"grade_max":4,"school_years":["3º de ESO","4º de ESO"],"aliases":["Tectónica de placas","tectonica de placas","placas tectonicas"],"explanation":"La litosfera terrestre está dividida en placas que se mueven lentamente sobre regiones más deformables del manto superior. Sus interacciones ayudan a explicar muchos terremotos, volcanes y cordilleras. Las placas no son solo continentes.","simpler":"La superficie rígida forma piezas móviles que incluyen partes continentales y oceánicas.","example":"Cuando dos placas convergen, puede haber subducción o colisión continental, según los tipos de litosfera implicados.","why":"Las rocas del manto pueden deformarse y fluir muy lentamente aunque sean mayoritariamente sólidas.","misconception":"El manto no es un océano global de roca totalmente líquida.","hints":["Relaciona el movimiento relativo con el tipo de límite.","La superficie rígida forma piezas móviles que incluyen partes continentales y oceánicas.","Cuando dos placas convergen, puede haber subducción o colisión continental, según los tipos de litosfera implicados."],"quiz":[{"id":"e-tectonics:q0","question":"Las placas forman parte de la…","options":["Litosfera","Atmósfera","Hidrosfera únicamente"],"answer":"A","hint":"Relaciona el movimiento relativo con el tipo de límite.","level":1},{"id":"e-tectonics:q1","question":"¿Una placa contiene solo continente?","options":["Siempre","Solo en Europa","No necesariamente"],"answer":"C","hint":"Relaciona el movimiento relativo con el tipo de límite.","level":2},{"id":"e-tectonics:q2","question":"Dos placas que se acercan tienen un límite…","options":["Divergente","Convergente","Sin movimiento"],"answer":"B","hint":"Relaciona el movimiento relativo con el tipo de límite.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-middle-ages","stage":"eso","subject":"Geografía e Historia","title":"La Edad Media","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["La Edad Media","edad media","la edad media"],"explanation":"La Edad Media es una periodización de la historia europea. Se sitúa convencionalmente entre la caída del Imperio romano de Occidente en 476 y finales del siglo XV; se usan hitos como 1453 o 1492 según el enfoque. No describe de la misma forma la historia de todo el mundo.","simpler":"Es una etapa histórica de unos mil años en Europa. Las fechas son referencias para organizar procesos, no cambios instantáneos.","example":"476 marca una referencia política; 1492 suele utilizarse en la enseñanza española como cierre convencional. La vida social no cambió toda en un solo día.","why":"Las periodizaciones son herramientas: destacan ciertos procesos y deben explicitar su ámbito geográfico y sus criterios.","misconception":"No presentes 1492 como la única fecha académicamente posible.","hints":["Distingue una convención cronológica de un proceso histórico.","Es una etapa histórica de unos mil años en Europa. Las fechas son referencias para organizar procesos, no cambios instantáneos.","476 marca una referencia política; 1492 suele utilizarse en la enseñanza española como cierre convencional. La vida social no cambió toda en un solo día."],"quiz":[{"id":"e-middle-ages:q0","question":"476 se asocia con…","options":["La Revolución francesa","La caída del Imperio romano de Occidente","La llegada del ferrocarril"],"answer":"B","hint":"Distingue una convención cronológica de un proceso histórico.","level":1},{"id":"e-middle-ages:q1","question":"Las fechas de una periodización son…","options":["Referencias convencionales","Fronteras instantáneas para toda sociedad","Leyes físicas"],"answer":"A","hint":"Distingue una convención cronológica de un proceso histórico.","level":2},{"id":"e-middle-ages:q2","question":"¿La Edad Media europea describe igual toda la historia mundial?","options":["Sí","Solo desde 1492","No"],"answer":"C","hint":"Distingue una convención cronológica de un proceso histórico.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-industrial","stage":"eso","subject":"Geografía e Historia","title":"La Revolución Industrial","grade_min":3,"grade_max":4,"school_years":["3º de ESO","4º de ESO"],"aliases":["La Revolución Industrial","revolucion industrial","industrializacion"],"explanation":"La Revolución Industrial fue un proceso de transformación económica y social iniciado en Gran Bretaña en la segunda mitad del siglo XVIII. La mecanización, nuevas fuentes de energía y el sistema fabril modificaron producción, transportes y trabajo. Su difusión fue desigual.","simpler":"Se pasó progresivamente de muchas tareas manuales a una producción mecanizada en fábricas, con importantes cambios sociales.","example":"La máquina de vapor permitió accionar maquinaria y, después, impulsar transportes; no fue el único factor del cambio.","why":"Las innovaciones actúan junto con recursos, instituciones, mercados y cambios sociales.","misconception":"Una sola invención no explica por sí sola toda la industrialización.","hints":["Relaciona tecnología, energía, capital, trabajo y sociedad.","Se pasó progresivamente de muchas tareas manuales a una producción mecanizada en fábricas, con importantes cambios sociales.","La máquina de vapor permitió accionar maquinaria y, después, impulsar transportes; no fue el único factor del cambio."],"quiz":[{"id":"e-industrial:q0","question":"El inicio se sitúa principalmente en…","options":["Gran Bretaña","La Antártida","El Imperio romano"],"answer":"A","hint":"Relaciona tecnología, energía, capital, trabajo y sociedad.","level":1},{"id":"e-industrial:q1","question":"Fue un proceso…","options":["Instantáneo","Igual en todos los países","Desigual y prolongado"],"answer":"C","hint":"Relaciona tecnología, energía, capital, trabajo y sociedad.","level":2},{"id":"e-industrial:q2","question":"El sistema fabril se relaciona con…","options":["Eliminar toda máquina","Concentrar producción y trabajo en fábricas","Producir solo para autoconsumo"],"answer":"B","hint":"Relaciona tecnología, energía, capital, trabajo y sociedad.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-climate","stage":"eso","subject":"Geografía e Historia","title":"Tiempo y clima","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Tiempo y clima","tiempo y clima","diferencia entre tiempo y clima"],"explanation":"El tiempo atmosférico describe las condiciones de la atmósfera en un lugar y momento. El clima caracteriza sus patrones y variabilidad durante períodos largos, habitualmente de varias décadas. Un día concreto no basta para definir el clima.","simpler":"Tiempo es lo que ocurre ahora; clima es cómo suelen variar esas condiciones a lo largo de muchos años.","example":"«Hoy llueve» describe el tiempo. «Los veranos suelen ser secos» describe un rasgo climático de un lugar.","why":"El clima se describe estadísticamente; los días particulares pueden apartarse de sus valores habituales.","misconception":"No confundas la variabilidad diaria con una tendencia a largo plazo.","hints":["Pregunta si el dato se refiere a un momento o a una serie prolongada.","Tiempo es lo que ocurre ahora; clima es cómo suelen variar esas condiciones a lo largo de muchos años.","«Hoy llueve» describe el tiempo. «Los veranos suelen ser secos» describe un rasgo climático de un lugar."],"quiz":[{"id":"e-climate:q0","question":"«Hoy hay 15 °C» describe…","options":["El clima completo","El tiempo","La latitud"],"answer":"B","hint":"Pregunta si el dato se refiere a un momento o a una serie prolongada.","level":1},{"id":"e-climate:q1","question":"Para estudiar el clima necesitamos…","options":["Series de muchos años","Solo el día más cálido","Una fotografía"],"answer":"A","hint":"Pregunta si el dato se refiere a un momento o a una serie prolongada.","level":2},{"id":"e-climate:q2","question":"Un día frío…","options":["Demuestra por sí solo enfriamiento global","Define todo un clima","No basta para concluir una tendencia climática"],"answer":"C","hint":"Pregunta si el dato se refiere a un momento o a una serie prolongada.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-sources","stage":"eso","subject":"Geografía e Historia","title":"Fuentes históricas","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Fuentes históricas","fuentes historicas","fuentes primarias y secundarias"],"explanation":"Una fuente histórica aporta información para investigar el pasado. Una fuente primaria procede del contexto estudiado; una secundaria lo analiza posteriormente. Hay que valorar autoría, fecha, finalidad, contexto y límites, y contrastar fuentes.","simpler":"Una carta de la época y un estudio actual pueden informar del pasado de formas diferentes.","example":"Una carta de 1910 puede ser primaria para estudiar su época; un libro de un historiador que la analiza es una fuente secundaria.","why":"Cada fuente refleja una perspectiva; contrastarlas ayuda a justificar interpretaciones con pruebas.","misconception":"Primaria no significa automáticamente verdadera, completa o neutral.","hints":["Pregunta quién produjo la fuente y con qué propósito.","Una carta de la época y un estudio actual pueden informar del pasado de formas diferentes.","Una carta de 1910 puede ser primaria para estudiar su época; un libro de un historiador que la analiza es una fuente secundaria."],"quiz":[{"id":"e-sources:q0","question":"Una carta de la época estudiada suele ser…","options":["Una fuente primaria","Siempre una mentira","Una fuente secundaria por definición"],"answer":"A","hint":"Pregunta quién produjo la fuente y con qué propósito.","level":1},{"id":"e-sources:q1","question":"¿Qué conviene hacer con una fuente?","options":["Creerla sin contexto","Ignorar quién la hizo","Analizarla y contrastarla"],"answer":"C","hint":"Pregunta quién produjo la fuente y con qué propósito.","level":2},{"id":"e-sources:q2","question":"Una fuente primaria…","options":["Siempre es neutral","También puede tener sesgos","No necesita fecha"],"answer":"B","hint":"Pregunta quién produjo la fuente y con qué propósito.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-text","stage":"eso","subject":"Lengua Castellana y Literatura","title":"Coherencia y cohesión","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Coherencia y cohesión","coherencia y cohesion","coherencia textual","cohesion textual"],"explanation":"La coherencia hace que las ideas formen un sentido global y no se contradigan sin explicación. La cohesión relaciona las partes mediante conectores, referencias, elipsis y otros recursos. Un texto puede tener conectores y aun así ser incoherente.","simpler":"Coherencia es que las ideas encajen; cohesión es cómo enlazas sus partes.","example":"«Estudié el tema. Por eso pude explicarlo» conecta una causa con una consecuencia. El conector debe corresponder a la relación real.","why":"Los mecanismos lingüísticos deben expresar relaciones que tengan sentido, no sustituirlas.","misconception":"Añadir conectores no repara por sí solo una contradicción.","hints":["Comprueba primero la relación entre ideas y luego el recurso que las une.","Coherencia es que las ideas encajen; cohesión es cómo enlazas sus partes.","«Estudié el tema. Por eso pude explicarlo» conecta una causa con una consecuencia. El conector debe corresponder a la relación real."],"quiz":[{"id":"e-text:q0","question":"Los conectores contribuyen principalmente a…","options":["La ortografía de todas las palabras","La cohesión","El tamaño del texto"],"answer":"B","hint":"Comprueba primero la relación entre ideas y luego el recurso que las une.","level":1},{"id":"e-text:q1","question":"La coherencia exige…","options":["Sentido global entre las ideas","Muchos conectores sin criterio","Solo frases largas"],"answer":"A","hint":"Comprueba primero la relación entre ideas y luego el recurso que las une.","level":2},{"id":"e-text:q2","question":"Un texto con conectores puede ser…","options":["Siempre perfecto","Siempre argumentativo","Incoherente"],"answer":"C","hint":"Comprueba primero la relación entre ideas y luego el recurso que las une.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-metaphor","stage":"eso","subject":"Lengua Castellana y Literatura","title":"Metáfora y comparación","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Metáfora y comparación","metafora y comparacion","metafora","simil"],"explanation":"Una metáfora presenta una realidad en términos de otra por una relación de semejanza, sin formular necesariamente una comparación explícita. Un símil hace explícita esa comparación, a menudo con «como». Hay que interpretarlos en contexto.","simpler":"«Tus ojos son estrellas» es una metáfora. «Tus ojos brillan como estrellas» es una comparación explícita.","example":"La imagen de estrellas sugiere brillo; no afirma que haya astros físicamente en los ojos.","why":"La semejanza seleccionada crea un significado que el contexto ayuda a precisar.","misconception":"El lenguaje figurado no se interpreta siempre como una afirmación literal.","hints":["Busca qué cualidad relaciona las dos realidades.","«Tus ojos son estrellas» es una metáfora. «Tus ojos brillan como estrellas» es una comparación explícita.","La imagen de estrellas sugiere brillo; no afirma que haya astros físicamente en los ojos."],"quiz":[{"id":"e-metaphor:q0","question":"«Corre como el viento» es un…","options":["Símil","Artículo","Número"],"answer":"A","hint":"Busca qué cualidad relaciona las dos realidades.","level":1},{"id":"e-metaphor:q1","question":"Una metáfora debe interpretarse…","options":["Siempre literalmente","Sin leer el texto","En contexto"],"answer":"C","hint":"Busca qué cualidad relaciona las dos realidades.","level":2},{"id":"e-metaphor:q2","question":"«El tiempo es oro» sugiere que el tiempo…","options":["Es un metal","Es valioso","Pesa igual que el oro"],"answer":"B","hint":"Busca qué cualidad relaciona las dos realidades.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-present","stage":"eso","subject":"Lengua Extranjera: Inglés","title":"Present simple","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Present simple","present simple","presente simple en ingles"],"explanation":"El present simple se utiliza, entre otros usos, para hábitos y hechos generales. En afirmativa, he, she e it suelen añadir -s o -es al verbo. En preguntas y negativas con verbos léxicos usamos do o does; el verbo principal vuelve a la forma base.","simpler":"«She plays» lleva -s, pero «Does she play?» no la lleva en play.","example":"«He reads every day». Pregunta: «Does he read every day?». Negativa: «He does not read every day».","why":"El auxiliar lleva la marca gramatical de persona; el verbo principal se mantiene en su forma base.","misconception":"No pongas la marca de tercera persona a la vez en does y en el verbo principal.","hints":["Mira si does ya expresa la tercera persona.","«She plays» lleva -s, pero «Does she play?» no la lleva en play.","«He reads every day». Pregunta: «Does he read every day?». Negativa: «He does not read every day»."],"quiz":[{"id":"e-present:q0","question":"Completa: She ___ tennis.","options":["Play","Playing","Plays"],"answer":"C","hint":"Mira si does ya expresa la tercera persona.","level":1},{"id":"e-present:q1","question":"¿Qué pregunta es correcta?","options":["Does he work?","Does he works?","Do he works?"],"answer":"A","hint":"Mira si does ya expresa la tercera persona.","level":2},{"id":"e-present:q2","question":"En «She does not eat», eat está en…","options":["Pasado","Forma base","Participio"],"answer":"B","hint":"Mira si does ya expresa la tercera persona.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-algorithm","stage":"eso","subject":"Tecnología y Digitalización","title":"Los algoritmos","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Los algoritmos","algoritmos","algoritmo","pensamiento computacional"],"explanation":"Un algoritmo es una secuencia precisa de pasos para resolver una tarea o problema. Puede incluir decisiones y repeticiones. Debe indicar qué datos necesita y qué resultado se espera, y debe comprobarse con casos diferentes.","simpler":"Escribe pasos claros que otra persona o una máquina pueda seguir sin adivinar.","example":"Para decidir si un entero es par: calcula el resto de dividirlo entre 2; si es 0, es par; en caso contrario, es impar.","why":"Los casos límite revelan errores que no aparecen con ejemplos habituales.","misconception":"Que un programa funcione una vez no demuestra que sea correcto para todos los casos.","hints":["Define entrada, pasos y salida.","Escribe pasos claros que otra persona o una máquina pueda seguir sin adivinar.","Para decidir si un entero es par: calcula el resto de dividirlo entre 2; si es 0, es par; en caso contrario, es impar."],"quiz":[{"id":"e-algorithm:q0","question":"Un algoritmo necesita pasos…","options":["Precisos","Ambiguos siempre","Aleatorios sin finalidad"],"answer":"A","hint":"Define entrada, pasos y salida.","level":1},{"id":"e-algorithm:q1","question":"Una condición permite…","options":["Solo repetir texto","Guardar cualquier contraseña","Elegir entre acciones"],"answer":"C","hint":"Define entrada, pasos y salida.","level":2},{"id":"e-algorithm:q2","question":"Probar varios casos ayuda a…","options":["Garantizar perfección absoluta","Encontrar errores y límites","Eliminar los datos"],"answer":"B","hint":"Define entrada, pasos y salida.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-digital","stage":"eso","subject":"Tecnología y Digitalización","title":"Privacidad digital","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Privacidad digital","privacidad digital","datos personales","seguridad digital"],"explanation":"La privacidad digital consiste en controlar cómo se usan y comparten los datos personales. Antes de publicar, piensa quién podrá acceder y para qué. Usa contraseñas robustas y diferentes y pide ayuda a un adulto de confianza ante solicitudes sospechosas.","simpler":"No hace falta compartir dirección, contraseñas o ubicación exacta para aprender en línea.","example":"Un mensaje que pide tu contraseña para darte un premio es una señal de alerta. No la envíes; verifica por un canal de confianza.","why":"La apariencia se puede copiar; la verificación debe basarse en el origen y no solo en el diseño.","misconception":"Un logotipo conocido no prueba que un mensaje sea auténtico.","hints":["Comparte solo los datos necesarios y verifica la identidad por otra vía.","No hace falta compartir dirección, contraseñas o ubicación exacta para aprender en línea.","Un mensaje que pide tu contraseña para darte un premio es una señal de alerta. No la envíes; verifica por un canal de confianza."],"quiz":[{"id":"e-digital:q0","question":"¿Qué dato no debes enviar por chat a un desconocido?","options":["El resultado de una suma","Tu contraseña","El título de un libro"],"answer":"B","hint":"Comparte solo los datos necesarios y verifica la identidad por otra vía.","level":1},{"id":"e-digital:q1","question":"Ante un mensaje sospechoso conviene…","options":["Parar y verificar con ayuda","Responder deprisa","Abrir todos los enlaces"],"answer":"A","hint":"Comparte solo los datos necesarios y verifica la identidad por otra vía.","level":2},{"id":"e-digital:q2","question":"Una contraseña para todas las cuentas…","options":["Siempre es lo más seguro","Nunca puede filtrarse","Aumenta el riesgo si se filtra"],"answer":"C","hint":"Comparte solo los datos necesarios y verifica la identidad por otra vía.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"e-rhythm","stage":"eso","subject":"Música","title":"Pulso y ritmo","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Pulso y ritmo","pulso y ritmo","ritmo musical","pulso musical"],"explanation":"El pulso es la referencia regular que puede acompañar la música. El ritmo organiza duraciones, acentos y silencios sobre esa referencia. Pueden aparecer varios sonidos dentro de un pulso o mantenerse un sonido durante varios.","simpler":"Marca un paso regular: ese es el pulso. Cambia las palmadas encima: cambias el ritmo.","example":"Mantén cuatro golpes regulares con el pie y da dos palmadas suaves en uno de ellos. El pulso sigue mientras varía el ritmo.","why":"La referencia periódica ayuda a percibir cómo se distribuyen los acontecimientos sonoros.","misconception":"Pulso y ritmo no son sinónimos.","hints":["Mantén una referencia regular mientras escuchas las duraciones.","Marca un paso regular: ese es el pulso. Cambia las palmadas encima: cambias el ritmo.","Mantén cuatro golpes regulares con el pie y da dos palmadas suaves en uno de ellos. El pulso sigue mientras varía el ritmo."],"quiz":[{"id":"e-rhythm:q0","question":"El pulso suele ser una referencia…","options":["Regular","Siempre silenciosa","Sin relación con el tiempo"],"answer":"A","hint":"Mantén una referencia regular mientras escuchas las duraciones.","level":1},{"id":"e-rhythm:q1","question":"El ritmo organiza…","options":["Solo la intensidad","Solo la altura","Duraciones, acentos y silencios"],"answer":"C","hint":"Mantén una referencia regular mientras escuchas las duraciones.","level":2},{"id":"e-rhythm:q2","question":"Dentro de un pulso puede haber…","options":["Siempre exactamente una nota","Varios sonidos","Ninguna subdivisión posible"],"answer":"B","hint":"Mantén una referencia regular mientras escuchas las duraciones.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-limits","stage":"bachillerato","subject":"Matemáticas","title":"Límites de funciones","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Límites de funciones","limites","limites de funciones","limite de una funcion"],"explanation":"El límite describe a qué valor se aproxima una función cuando la variable se aproxima a un punto o crece sin cota. Puede existir aunque la función no esté definida en el punto. Sustituir directamente funciona en muchos casos de continuidad, pero no resuelve todas las indeterminaciones.","simpler":"No preguntamos necesariamente cuánto vale la función en el punto, sino a qué valor se acercan sus resultados.","example":"Para x distinto de 1, (x² − 1)/(x − 1) = x + 1. Al acercarse x a 1, el límite es 2, aunque la expresión original no esté definida en 1.","why":"El límite depende del comportamiento próximo al punto, no necesariamente de su valor puntual.","misconception":"0/0 no es un valor numérico ni demuestra por sí solo que no exista límite.","hints":["Estudia el comportamiento alrededor del punto y las condiciones de cada transformación.","No preguntamos necesariamente cuánto vale la función en el punto, sino a qué valor se acercan sus resultados.","Para x distinto de 1, (x² − 1)/(x − 1) = x + 1. Al acercarse x a 1, el límite es 2, aunque la expresión original no esté definida en 1."],"quiz":[{"id":"b-limits:q0","question":"El límite al acercarse x a 1 de (x²−1)/(x−1) es…","options":["1","2","No existe necesariamente"],"answer":"B","hint":"Estudia el comportamiento alrededor del punto y las condiciones de cada transformación.","level":1},{"id":"b-limits:q1","question":"¿Puede existir un límite donde la función no esté definida?","options":["Sí","Nunca","Solo si vale cero"],"answer":"A","hint":"Estudia el comportamiento alrededor del punto y las condiciones de cada transformación.","level":2},{"id":"b-limits:q2","question":"Obtener 0/0 por sustitución indica…","options":["Que el límite es cero","Que el límite es uno","Una indeterminación que exige análisis"],"answer":"C","hint":"Estudia el comportamiento alrededor del punto y las condiciones de cada transformación.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-derivative","stage":"bachillerato","subject":"Matemáticas","title":"La derivada","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["La derivada","derivadas","derivada","la derivada"],"explanation":"La derivada mide una tasa de variación instantánea. Geométricamente, cuando existe, es la pendiente de la recta tangente a la gráfica. Se define mediante el límite del cociente incremental; no es simplemente una división entre coordenadas.","simpler":"Compara cambios cada vez más pequeños para describir cómo cambia la función justo en un punto.","example":"Si f(x) = x², f'(x) = 2x. En x = 3, la pendiente de la tangente es 6.","why":"La definición exige un límite de pendientes secantes; si no converge de forma compatible, no hay derivada en ese punto.","misconception":"Una función puede ser continua y no ser derivable en algún punto.","hints":["Distingue la función derivada del valor de la derivada en un punto.","Compara cambios cada vez más pequeños para describir cómo cambia la función justo en un punto.","Si f(x) = x², f'(x) = 2x. En x = 3, la pendiente de la tangente es 6."],"quiz":[{"id":"b-derivative:q0","question":"La derivada de x² es…","options":["x","x²/2","2x"],"answer":"C","hint":"Distingue la función derivada del valor de la derivada en un punto.","level":1},{"id":"b-derivative:q1","question":"Para f(x) = x², f'(3) es…","options":["6","9","3"],"answer":"A","hint":"Distingue la función derivada del valor de la derivada en un punto.","level":2},{"id":"b-derivative:q2","question":"Una derivada expresa una tasa de variación…","options":["Solo media en un intervalo fijo","Instantánea","Siempre positiva"],"answer":"B","hint":"Distingue la función derivada del valor de la derivada en un punto.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-integral","stage":"bachillerato","subject":"Matemáticas","title":"La integral definida","grade_min":2,"grade_max":2,"school_years":["2º de Bachillerato"],"aliases":["La integral definida","integrales","integral definida","integracion"],"explanation":"La integral definida acumula contribuciones de una función en un intervalo. Puede interpretarse como área con signo: las zonas bajo el eje contribuyen negativamente. Si F es una primitiva de una función continua f, la integral entre a y b es F(b) − F(a).","simpler":"Sumamos aportaciones muy pequeñas a lo largo de un intervalo. El signo importa.","example":"La integral de 2x entre 0 y 2 es [x²] entre 0 y 2: 4 − 0 = 4.","why":"La integral suma valores con signo; el área geométrica requiere contabilizar las regiones como cantidades no negativas.","misconception":"Una integral definida negativa no es un error por el mero hecho de ser negativa.","hints":["Encuentra una primitiva y evalúala en ambos extremos, respetando el orden.","Sumamos aportaciones muy pequeñas a lo largo de un intervalo. El signo importa.","La integral de 2x entre 0 y 2 es [x²] entre 0 y 2: 4 − 0 = 4."],"quiz":[{"id":"b-integral:q0","question":"Una primitiva de 2x es…","options":["x²","2","x"],"answer":"A","hint":"Encuentra una primitiva y evalúala en ambos extremos, respetando el orden.","level":1},{"id":"b-integral:q1","question":"La integral de 2x entre 0 y 2 vale…","options":["2","8","4"],"answer":"C","hint":"Encuentra una primitiva y evalúala en ambos extremos, respetando el orden.","level":2},{"id":"b-integral:q2","question":"El área geométrica y el área con signo…","options":["Son siempre iguales","Pueden ser distintas","Nunca están relacionadas"],"answer":"B","hint":"Encuentra una primitiva y evalúala en ambos extremos, respetando el orden.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-matrices","stage":"bachillerato","subject":"Matemáticas","title":"Las matrices","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Las matrices","matrices","matriz"],"explanation":"Una matriz organiza números en filas y columnas. Su dimensión se expresa como número de filas por número de columnas. Para sumar matrices deben tener la misma dimensión. Para multiplicar A por B, las columnas de A deben coincidir con las filas de B.","simpler":"Identifica primero filas y columnas. Después comprueba si la operación está definida.","example":"Una matriz de 2 × 3 puede multiplicarse por una de 3 × 4; el resultado tiene dimensión 2 × 4.","why":"Cada entrada del producto combina una fila de la primera matriz con una columna de la segunda.","misconception":"La multiplicación de matrices no es conmutativa en general.","hints":["Comprueba las dimensiones antes de calcular.","Identifica primero filas y columnas. Después comprueba si la operación está definida.","Una matriz de 2 × 3 puede multiplicarse por una de 3 × 4; el resultado tiene dimensión 2 × 4."],"quiz":[{"id":"b-matrices:q0","question":"Una matriz de 2 × 3 tiene…","options":["3 filas y 2 columnas","2 filas y 3 columnas","6 filas"],"answer":"B","hint":"Comprueba las dimensiones antes de calcular.","level":1},{"id":"b-matrices:q1","question":"El producto (2 × 3) por (3 × 4) da dimensión…","options":["2 × 4","3 × 3","4 × 2"],"answer":"A","hint":"Comprueba las dimensiones antes de calcular.","level":2},{"id":"b-matrices:q2","question":"En general, AB y BA…","options":["Son siempre iguales","Siempre existen ambos","Pueden no coincidir o no estar ambos definidos"],"answer":"C","hint":"Comprueba las dimensiones antes de calcular.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-newton","stage":"bachillerato","subject":"Física","title":"Segunda ley de Newton","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Segunda ley de Newton","segunda ley de newton","fuerza masa y aceleracion"],"explanation":"En un sistema de referencia inercial y para masa constante, la fuerza neta es igual a la masa por la aceleración: ΣF = ma. Es una relación vectorial. Debemos sumar todas las fuerzas y distinguirlas de la velocidad.","simpler":"La fuerza neta determina cómo cambia la velocidad, no cuál es la velocidad en ese instante.","example":"Una fuerza neta de 10 N sobre una masa de 2 kg produce una aceleración de 5 m/s² en la dirección de esa fuerza.","why":"La aceleración es el cambio de velocidad; un movimiento uniforme puede tener fuerza neta nula.","misconception":"La presencia de movimiento no implica una fuerza neta en su dirección.","hints":["Elige el sistema, representa las fuerzas y suma por componentes.","La fuerza neta determina cómo cambia la velocidad, no cuál es la velocidad en ese instante.","Una fuerza neta de 10 N sobre una masa de 2 kg produce una aceleración de 5 m/s² en la dirección de esa fuerza."],"quiz":[{"id":"b-newton:q0","question":"Con F neta = 12 N y m = 3 kg, la aceleración es…","options":["36 m/s²","9 m/s²","4 m/s²"],"answer":"C","hint":"Elige el sistema, representa las fuerzas y suma por componentes.","level":1},{"id":"b-newton:q1","question":"La ley usa…","options":["La fuerza neta","Solo la mayor fuerza","La velocidad en lugar de fuerza"],"answer":"A","hint":"Elige el sistema, representa las fuerzas y suma por componentes.","level":2},{"id":"b-newton:q2","question":"Fuerza y aceleración son magnitudes…","options":["Siempre escalares","Vectoriales","Sin unidades"],"answer":"B","hint":"Elige el sistema, representa las fuerzas y suma por componentes.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-ohm","stage":"bachillerato","subject":"Física","title":"Ley de Ohm","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Ley de Ohm","ley de ohm","resistencia electrica"],"explanation":"Para un elemento óhmico en condiciones constantes, tensión, intensidad y resistencia se relacionan mediante V = IR. Voltios, amperios y ohmios son sus unidades respectivas. La relación no describe todos los dispositivos ni todas las condiciones.","simpler":"En una resistencia óhmica, a mayor tensión corresponde mayor corriente si la resistencia no cambia.","example":"Con una resistencia ideal de 6 Ω y una tensión de 12 V, la intensidad es 2 A. Trabajamos con el modelo; no hagas conexiones a la red eléctrica.","why":"La resistencia expresa la proporcionalidad entre tensión y corriente para el comportamiento óhmico considerado.","misconception":"Tensión e intensidad no son la misma magnitud.","hints":["Despeja la incógnita antes de sustituir.","En una resistencia óhmica, a mayor tensión corresponde mayor corriente si la resistencia no cambia.","Con una resistencia ideal de 6 Ω y una tensión de 12 V, la intensidad es 2 A. Trabajamos con el modelo; no hagas conexiones a la red eléctrica."],"quiz":[{"id":"b-ohm:q0","question":"Con V = 12 V y R = 6 Ω, I es…","options":["2 A","72 A","6 A"],"answer":"A","hint":"Despeja la incógnita antes de sustituir.","level":1},{"id":"b-ohm:q1","question":"La unidad de resistencia es…","options":["Amperio","Voltio","Ohmio"],"answer":"C","hint":"Despeja la incógnita antes de sustituir.","level":2},{"id":"b-ohm:q2","question":"La ley se aplica en su forma simple a…","options":["Todo dispositivo sin condiciones","Elementos óhmicos bajo condiciones adecuadas","Solo corrientes nulas"],"answer":"B","hint":"Despeja la incógnita antes de sustituir.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-mole","stage":"bachillerato","subject":"Química","title":"El mol","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["El mol","mol","el mol","cantidad de sustancia"],"explanation":"El mol es la unidad del SI de cantidad de sustancia. Un mol contiene exactamente 6,02214076 × 10²³ entidades elementales especificadas. Para una sustancia dada, n = m/M relaciona cantidad, masa y masa molar. Hay que indicar si contamos átomos, moléculas u otras entidades.","simpler":"El mol funciona como una unidad de recuento enorme; no es una masa fija para todas las sustancias.","example":"Si usamos M = 18 g/mol para un ejercicio aproximado con agua, 36 g corresponden a 2 mol de moléculas de agua.","why":"Las partículas tienen masas diferentes; el mismo número de entidades puede corresponder a masas distintas.","misconception":"El número de Avogadro no significa que un mol pese siempre un gramo.","hints":["Especifica las entidades y revisa las unidades de masa molar.","El mol funciona como una unidad de recuento enorme; no es una masa fija para todas las sustancias.","Si usamos M = 18 g/mol para un ejercicio aproximado con agua, 36 g corresponden a 2 mol de moléculas de agua."],"quiz":[{"id":"b-mole:q0","question":"Con m = 36 g y M = 18 g/mol, n es…","options":["18 mol","2 mol","648 mol"],"answer":"B","hint":"Especifica las entidades y revisa las unidades de masa molar.","level":1},{"id":"b-mole:q1","question":"¿Un mol tiene la misma masa en todas las sustancias?","options":["No","Sí","Solo si son gases"],"answer":"A","hint":"Especifica las entidades y revisa las unidades de masa molar.","level":2},{"id":"b-mole:q2","question":"La expresión n = m/M requiere…","options":["Sumar unidades sin mirar","Confundir masa y cantidad","Usar unidades compatibles"],"answer":"C","hint":"Especifica las entidades y revisa las unidades de masa molar.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-ph","stage":"bachillerato","subject":"Química","title":"El pH","grade_min":2,"grade_max":2,"school_years":["2º de Bachillerato"],"aliases":["El pH","ph","el ph","acidez y ph"],"explanation":"El pH se define mediante el logaritmo negativo de la actividad del ion hidrógeno. En disoluciones acuosas suficientemente diluidas se aproxima como −log₁₀[H₃O⁺], con la convención de concentración adecuada. La neutralidad depende de la temperatura; a 25 °C se sitúa aproximadamente en pH 7.","simpler":"La escala es logarítmica: cambiar una unidad representa un factor diez en la actividad correspondiente.","example":"En la aproximación diluida, [H₃O⁺] = 10⁻³ mol/L da pH ≈ 3. No manipules sustancias desconocidas para probarlo.","why":"El producto iónico del agua varía con la temperatura y la actividad no coincide siempre con la concentración.","misconception":"La escala 0–14 no es un límite universal del pH en todas las disoluciones.","hints":["Recuerda que es una escala logarítmica y especifica las condiciones.","La escala es logarítmica: cambiar una unidad representa un factor diez en la actividad correspondiente.","En la aproximación diluida, [H₃O⁺] = 10⁻³ mol/L da pH ≈ 3. No manipules sustancias desconocidas para probarlo."],"quiz":[{"id":"b-ph:q0","question":"Con [H₃O⁺] ≈ 10⁻³ mol/L, el pH aproximado es…","options":["−3","10","3"],"answer":"C","hint":"Recuerda que es una escala logarítmica y especifica las condiciones.","level":1},{"id":"b-ph:q1","question":"Una unidad de pH corresponde a un factor aproximado de…","options":["10","2","1000"],"answer":"A","hint":"Recuerda que es una escala logarítmica y especifica las condiciones.","level":2},{"id":"b-ph:q2","question":"La neutralidad a pH 7 se asocia aproximadamente a…","options":["Cualquier temperatura sin excepción","25 °C","La ausencia de agua"],"answer":"B","hint":"Recuerda que es una escala logarítmica y especifica las condiciones.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-dna","stage":"bachillerato","subject":"Biología","title":"ADN y expresión génica","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["ADN y expresión génica","adn","expresion genica","adn y arn"],"explanation":"El ADN almacena información genética en su secuencia de nucleótidos. En la expresión de muchos genes, se transcribe ARN y, para genes codificantes, se traduce la secuencia del ARN mensajero a una proteína. No todos los genes codifican proteínas.","simpler":"Transcripción: del ADN al ARN. Traducción: del ARN mensajero a una secuencia de aminoácidos.","example":"Un ribosoma lee codones del ARN mensajero durante la traducción. El ADN no se convierte físicamente en proteína.","why":"La información se expresa mediante procesos moleculares distintos; no implica que una molécula se transforme directamente en otra de naturaleza diferente.","misconception":"Los aminoácidos no son las unidades básicas del ADN.","hints":["Distingue copia de información, molécula original y producto.","Transcripción: del ADN al ARN. Traducción: del ARN mensajero a una secuencia de aminoácidos.","Un ribosoma lee codones del ARN mensajero durante la traducción. El ADN no se convierte físicamente en proteína."],"quiz":[{"id":"b-dna:q0","question":"La transcripción produce…","options":["ARN","Siempre glucosa","Una membrana"],"answer":"A","hint":"Distingue copia de información, molécula original y producto.","level":1},{"id":"b-dna:q1","question":"La traducción ocurre en…","options":["Los cromosomas como órgano","El aparato circulatorio","Los ribosomas"],"answer":"C","hint":"Distingue copia de información, molécula original y producto.","level":2},{"id":"b-dna:q2","question":"¿Todos los genes codifican proteínas?","options":["Sí","No","Solo en bacterias"],"answer":"B","hint":"Distingue copia de información, molécula original y producto.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-meiosis","stage":"bachillerato","subject":"Biología","title":"La meiosis","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["La meiosis","meiosis","la meiosis"],"explanation":"La meiosis es una división celular especializada que reduce el número de juegos cromosómicos. Comprende dos divisiones tras una replicación de ADN. La recombinación y la distribución de cromosomas contribuyen a la variabilidad genética.","simpler":"Primero se replica el ADN y después ocurren dos divisiones. El resultado reduce la dotación cromosómica.","example":"En un modelo diploide con 2n = 6, las células finales tienen n = 3 cromosomas, si el proceso transcurre normalmente.","why":"La reducción permite que la fecundación restablezca la dotación y la recombinación reorganiza variantes heredadas.","misconception":"Reducir dotación cromosómica no equivale a perder genes de forma arbitraria.","hints":["Distingue cromosomas homólogos de cromátidas hermanas.","Primero se replica el ADN y después ocurren dos divisiones. El resultado reduce la dotación cromosómica.","En un modelo diploide con 2n = 6, las células finales tienen n = 3 cromosomas, si el proceso transcurre normalmente."],"quiz":[{"id":"b-meiosis:q0","question":"Tras meiosis de una célula con 2n = 6, la dotación final es…","options":["6n","n = 3","2n = 12"],"answer":"B","hint":"Distingue cromosomas homólogos de cromátidas hermanas.","level":1},{"id":"b-meiosis:q1","question":"Antes de las dos divisiones hay…","options":["Una replicación de ADN","Dos replicaciones obligatorias","Ninguna replicación"],"answer":"A","hint":"Distingue cromosomas homólogos de cromátidas hermanas.","level":2},{"id":"b-meiosis:q2","question":"La recombinación contribuye a…","options":["Eliminar toda variación","Duplicar siempre la especie","La variabilidad genética"],"answer":"C","hint":"Distingue cromosomas homólogos de cromátidas hermanas.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-argument","stage":"bachillerato","subject":"Lengua Castellana y Literatura","title":"El texto argumentativo","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["El texto argumentativo","texto argumentativo","argumentacion","argumentar"],"explanation":"Argumentar consiste en sostener una tesis mediante razones y, cuando corresponde, pruebas. Hay que distinguir afirmaciones, evidencia y supuestos; considerar objeciones pertinentes y responderlas sin deformar la posición contraria.","simpler":"No basta decir qué opinas: explica por qué y qué apoya tus razones.","example":"Tesis: conviene contrastar fuentes antes de compartir una noticia. Razón: así podemos detectar errores. Evidencia: comparar autoría, fecha y documentos originales en un caso concreto.","why":"La calidad de un argumento depende del respaldo y de la relación entre premisas y conclusión, no solo de su fuerza retórica.","misconception":"Persuadir y demostrar no son exactamente lo mismo.","hints":["Separa tesis, razones, pruebas y posibles objeciones.","No basta decir qué opinas: explica por qué y qué apoya tus razones.","Tesis: conviene contrastar fuentes antes de compartir una noticia. Razón: así podemos detectar errores. Evidencia: comparar autoría, fecha y documentos originales en un caso concreto."],"quiz":[{"id":"b-argument:q0","question":"La tesis es…","options":["La posición que se defiende","Cualquier ejemplo aislado","El título siempre"],"answer":"A","hint":"Separa tesis, razones, pruebas y posibles objeciones.","level":1},{"id":"b-argument:q1","question":"Una objeción debe…","options":["Ocultarse siempre","Ridiculizarse","Analizarse con honestidad"],"answer":"C","hint":"Separa tesis, razones, pruebas y posibles objeciones.","level":2},{"id":"b-argument:q2","question":"Una afirmación repetida muchas veces…","options":["Se convierte en prueba","No es por eso verdadera","Deja de necesitar justificación"],"answer":"B","hint":"Separa tesis, razones, pruebas y posibles objeciones.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-deduction","stage":"bachillerato","subject":"Filosofía","title":"Deducción e inducción","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Deducción e inducción","deduccion e induccion","razonamiento deductivo","razonamiento inductivo"],"explanation":"Un argumento deductivo válido no permite premisas verdaderas y conclusión falsa al mismo tiempo. La inducción apoya una conclusión ampliativa con grados de fuerza, pero no la garantiza del mismo modo. Validez y verdad de las premisas son cuestiones diferentes.","simpler":"En deducción válida, la conclusión se sigue necesariamente si las premisas son verdaderas. En inducción hay apoyo, no garantía lógica absoluta.","example":"«Todos los mamíferos son vertebrados; las ballenas son mamíferos; luego las ballenas son vertebrados» tiene forma deductiva válida.","why":"La forma lógica garantiza una relación condicional, no certifica por sí sola los hechos enunciados.","misconception":"Un argumento válido no es automáticamente un argumento con premisas verdaderas.","hints":["Pregunta si sería posible que las premisas fueran verdaderas y la conclusión falsa.","En deducción válida, la conclusión se sigue necesariamente si las premisas son verdaderas. En inducción hay apoyo, no garantía lógica absoluta.","«Todos los mamíferos son vertebrados; las ballenas son mamíferos; luego las ballenas son vertebrados» tiene forma deductiva válida."],"quiz":[{"id":"b-deduction:q0","question":"La validez deductiva depende de…","options":["Que guste la conclusión","La relación lógica entre premisas y conclusión","La longitud del texto"],"answer":"B","hint":"Pregunta si sería posible que las premisas fueran verdaderas y la conclusión falsa.","level":1},{"id":"b-deduction:q1","question":"¿Un argumento válido puede tener una premisa falsa?","options":["Sí","No","Solo si es inductivo"],"answer":"A","hint":"Pregunta si sería posible que las premisas fueran verdaderas y la conclusión falsa.","level":2},{"id":"b-deduction:q2","question":"Una inducción fuerte proporciona…","options":["Certeza lógica absoluta siempre","Una definición sin datos","Apoyo a una conclusión ampliativa"],"answer":"C","hint":"Pregunta si sería posible que las premisas fueran verdaderas y la conclusión falsa.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-1812","stage":"bachillerato","subject":"Historia de España","title":"La Constitución de 1812","grade_min":2,"grade_max":2,"school_years":["2º de Bachillerato"],"aliases":["La Constitución de 1812","constitucion de 1812","la pepa","cortes de cadiz"],"explanation":"La Constitución de 1812 fue aprobada por las Cortes de Cádiz durante la Guerra de la Independencia. Defendió principios como la soberanía nacional y la división de poderes, dentro de una monarquía constitucional. Su liberalismo coexistía con límites y exclusiones propios del contexto.","simpler":"Fue un texto clave del primer liberalismo español, no una democracia idéntica a las actuales.","example":"Su aprobación el 19 de marzo explica el sobrenombre «la Pepa». Para analizarla conviene comparar principios, instituciones y límites de participación.","why":"El análisis histórico combina avances respecto al orden anterior con las limitaciones efectivas del nuevo sistema.","misconception":"No proyectes automáticamente categorías actuales sobre instituciones del siglo XIX.","hints":["Sitúa el documento en su contexto bélico y político.","Fue un texto clave del primer liberalismo español, no una democracia idéntica a las actuales.","Su aprobación el 19 de marzo explica el sobrenombre «la Pepa». Para analizarla conviene comparar principios, instituciones y límites de participación."],"quiz":[{"id":"b-1812:q0","question":"La Constitución se aprobó en…","options":["Cádiz","Barcelona","Lisboa"],"answer":"A","hint":"Sitúa el documento en su contexto bélico y político.","level":1},{"id":"b-1812:q1","question":"La soberanía nacional atribuye la soberanía a…","options":["Un propietario individual","Un ejército extranjero","La nación"],"answer":"C","hint":"Sitúa el documento en su contexto bélico y político.","level":2},{"id":"b-1812:q2","question":"¿Equivale sin matices a una democracia actual?","options":["Sí","No","Solo por su apodo"],"answer":"B","hint":"Sitúa el documento en su contexto bélico y político.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-opportunity","stage":"bachillerato","subject":"Economía","title":"Coste de oportunidad","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Coste de oportunidad","coste de oportunidad","escasez economica"],"explanation":"El coste de oportunidad es el valor de la mejor alternativa a la que renuncias cuando eliges. Aparece porque tiempo y recursos son limitados. No equivale a sumar todas las alternativas ni se reduce siempre a un pago monetario.","simpler":"Elegir una opción significa dejar otra posible sin realizar. Importa la mejor alternativa descartada.","example":"Si dedicas una hora a una actividad y tu mejor alternativa era estudiar, el coste de oportunidad incluye el valor de ese estudio no realizado.","why":"Una decisión utiliza recursos que no pueden destinarse simultáneamente a su mejor uso alternativo.","misconception":"No todas las renuncias se suman para calcular el coste de oportunidad.","hints":["Identifica alternativas reales y cuál era la mejor descartada.","Elegir una opción significa dejar otra posible sin realizar. Importa la mejor alternativa descartada.","Si dedicas una hora a una actividad y tu mejor alternativa era estudiar, el coste de oportunidad incluye el valor de ese estudio no realizado."],"quiz":[{"id":"b-opportunity:q0","question":"El coste de oportunidad se refiere a…","options":["Todas las opciones sumadas","La mejor alternativa descartada","Solo el precio pagado"],"answer":"B","hint":"Identifica alternativas reales y cuál era la mejor descartada.","level":1},{"id":"b-opportunity:q1","question":"Puede existir aunque no haya dinero…","options":["Sí","Nunca","Solo en empresas"],"answer":"A","hint":"Identifica alternativas reales y cuál era la mejor descartada.","level":2},{"id":"b-opportunity:q2","question":"Se relaciona con…","options":["Recursos ilimitados","No tomar decisiones","La escasez y la elección"],"answer":"C","hint":"Identifica alternativas reales y cuál era la mejor descartada.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-passive","stage":"bachillerato","subject":"Lengua Extranjera: Inglés","title":"La voz pasiva en inglés","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["La voz pasiva en inglés","voz pasiva en ingles","passive voice","pasiva inglesa"],"explanation":"La pasiva inglesa suele formarse con be en el tiempo correspondiente y el participio pasado del verbo principal. Destaca la entidad afectada por la acción. El complemento con by puede indicar el agente cuando resulta relevante.","simpler":"Mantén el tiempo verbal en be y utiliza el participio del verbo principal.","example":"«They built the bridge» puede transformarse en «The bridge was built». El sujeto cambia de función, pero debemos conservar el sentido y el tiempo.","why":"La pasiva reorganiza la información de la oración; la elección depende de qué queremos destacar.","misconception":"No todos los participios se forman añadiendo -ed.","hints":["Localiza el objeto de la activa y conserva el tiempo verbal.","Mantén el tiempo verbal en be y utiliza el participio del verbo principal.","«They built the bridge» puede transformarse en «The bridge was built». El sujeto cambia de función, pero debemos conservar el sentido y el tiempo."],"quiz":[{"id":"b-passive:q0","question":"La pasiva de «They built the bridge» es…","options":["The bridge builds","The bridge is build","The bridge was built"],"answer":"C","hint":"Localiza el objeto de la activa y conserva el tiempo verbal.","level":1},{"id":"b-passive:q1","question":"La estructura básica incluye…","options":["Be + participio pasado","Have + infinitivo siempre","Do + gerundio"],"answer":"A","hint":"Localiza el objeto de la activa y conserva el tiempo verbal.","level":2},{"id":"b-passive:q2","question":"El agente con by…","options":["Es obligatorio en todas las pasivas","Puede omitirse según el contexto","Indica siempre un lugar"],"answer":"B","hint":"Localiza el objeto de la activa y conserva el tiempo verbal.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"b-perspective","stage":"bachillerato","subject":"Dibujo Técnico","title":"Perspectiva cónica","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Perspectiva cónica","perspectiva conica","puntos de fuga"],"explanation":"La perspectiva cónica representa el espacio mediante proyecciones desde un punto de vista. Las rectas paralelas con una dirección que no sea paralela al plano del cuadro pueden converger en un punto de fuga. El horizonte se relaciona con la altura visual del observador.","simpler":"Las líneas que se alejan pueden parecer acercarse entre sí en el dibujo, aunque en el espacio sean paralelas.","example":"Los bordes paralelos de una carretera recta pueden dirigirse hacia un mismo punto de fuga en una representación adecuada.","why":"Cada dirección espacial puede tener su propio punto de fuga; algunas direcciones permanecen paralelas en la representación.","misconception":"Perspectiva cónica y dibujo a escala ortogonal no se interpretan igual.","hints":["Agrupa las rectas según su dirección espacial.","Las líneas que se alejan pueden parecer acercarse entre sí en el dibujo, aunque en el espacio sean paralelas.","Los bordes paralelos de una carretera recta pueden dirigirse hacia un mismo punto de fuga en una representación adecuada."],"quiz":[{"id":"b-perspective:q0","question":"Un punto de fuga representa la convergencia aparente de…","options":["Ciertas rectas paralelas","Todas las curvas","Solo círculos"],"answer":"A","hint":"Agrupa las rectas según su dirección espacial.","level":1},{"id":"b-perspective:q1","question":"El horizonte se relaciona con…","options":["El color del papel","El tamaño del lápiz","La altura visual del observador"],"answer":"C","hint":"Agrupa las rectas según su dirección espacial.","level":2},{"id":"b-perspective:q2","question":"¿Todas las paralelas del espacio comparten un único punto de fuga?","options":["Sí","No: depende de su dirección","Solo si son cortas"],"answer":"B","hint":"Agrupa las rectas según su dirección espacial.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial."},{"id":"i-sort","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Clasificar objetos","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Clasificar objetos","clasificar","clasificacion de objetos","agrupar objetos"],"explanation":"Clasificar es reunir cosas que comparten una característica. Podemos agrupar por color, por forma o por uso. Antes de empezar, elegimos una regla y la mantenemos mientras formamos los grupos.","simpler":"Pon juntas las piezas que se parecen en la característica elegida. Hoy podemos mirar solo el color.","example":"Con un adulto y piezas grandes, separa las rojas de las azules. Después prueba otra regla: redondas y no redondas. Una pieza puede cambiar de grupo si cambia la regla.","why":"Un mismo objeto tiene varias características. Al clasificar seleccionamos una y dejamos de lado las demás durante ese juego.","misconception":"Clasificar por tamaño y por color al mismo tiempo puede ser difícil: empieza con una sola regla.","hints":["Recuerda la regla que has elegido para comparar los objetos.","Pon juntas las piezas que se parecen en la característica elegida. Hoy podemos mirar solo el color.","Con un adulto y piezas grandes, separa las rojas de las azules. Después prueba otra regla: redondas y no redondas. Una pieza puede cambiar de grupo si cambia la regla."],"quiz":[{"id":"i-sort:q0","question":"Si agrupamos por color, una pieza roja va con…","options":["Las rojas","Las grandes aunque sean azules","Todas sin mirar"],"answer":"A","hint":"Recuerda la regla que has elegido para comparar los objetos.","level":1},{"id":"i-sort:q1","question":"¿Podemos clasificar las mismas piezas de otra manera?","options":["No","Sí, cambiando la regla","Solo rompiéndolas"],"answer":"B","hint":"Recuerda la regla que has elegido para comparar los objetos.","level":2},{"id":"i-sort:q2","question":"Antes de formar grupos conviene…","options":["Elegir al azar","Mirar solo la primera pieza","Decidir qué característica observamos"],"answer":"C","hint":"Recuerda la regla que has elegido para comparar los objetos.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"i-size","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Grande y pequeño","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Grande y pequeño","grande y pequeno","tamanos","comparar tamanos"],"explanation":"Grande y pequeño sirven para comparar tamaños. Algo puede ser grande al lado de un objeto y pequeño al lado de otro. Por eso ayuda indicar con qué lo estamos comparando.","simpler":"Pon dos objetos cerca y mira cuál ocupa más espacio. Compara sin decir que uno es mejor que otro.","example":"Una caja mediana es grande junto a una cajita, pero pequeña junto a una caja enorme. La caja mediana no ha cambiado.","why":"Los tamaños relativos se comprenden comparando; cambiar la referencia cambia la comparación, no el objeto.","misconception":"Grande no significa mejor, y pequeño no significa peor.","hints":["Coloca los objetos juntos y usa el mismo criterio.","Pon dos objetos cerca y mira cuál ocupa más espacio. Compara sin decir que uno es mejor que otro.","Una caja mediana es grande junto a una cajita, pero pequeña junto a una caja enorme. La caja mediana no ha cambiado."],"quiz":[{"id":"i-size:q0","question":"Una caja puede ser grande o pequeña según…","options":["Su color siempre","Con qué la compares","Quién la quiera más"],"answer":"B","hint":"Coloca los objetos juntos y usa el mismo criterio.","level":1},{"id":"i-size:q1","question":"Si cambiamos el objeto de referencia, la caja mediana…","options":["Puede parecer mayor o menor","Cambia necesariamente de tamaño","Desaparece"],"answer":"A","hint":"Coloca los objetos juntos y usa el mismo criterio.","level":2},{"id":"i-size:q2","question":"Comparar tamaños nos dice…","options":["Qué objeto es mejor","Quién debe jugar primero","Cuál es mayor respecto a otro"],"answer":"C","hint":"Coloca los objetos juntos y usa el mismo criterio.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"i-full","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Lleno y vacío","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Lleno y vacío","lleno y vacio","recipientes","llenar y vaciar"],"explanation":"Un recipiente está vacío respecto a un material cuando no contiene ese material. Decimos que está lleno cuando ya no cabe más de lo que ponemos, según la capacidad que estamos usando.","simpler":"Mira qué contiene el recipiente. Podemos decir vacío de agua o lleno de piezas.","example":"Con un adulto, usa dos cajas y piezas grandes: deja una sin piezas y llena la otra sin forzarla. La caja sin piezas puede contener aire, aunque digamos que está vacía.","why":"Precisar el material evita confundir la ausencia de una cosa con la ausencia absoluta de todo.","misconception":"Vacío de agua no significa necesariamente vacío de aire.","hints":["Observa el material del que estamos hablando.","Mira qué contiene el recipiente. Podemos decir vacío de agua o lleno de piezas.","Con un adulto, usa dos cajas y piezas grandes: deja una sin piezas y llena la otra sin forzarla. La caja sin piezas puede contener aire, aunque digamos que está vacía."],"quiz":[{"id":"i-full:q0","question":"Una caja sin piezas está…","options":["Vacía de piezas","Siempre sin aire","Llena de piezas"],"answer":"A","hint":"Observa el material del que estamos hablando.","level":1},{"id":"i-full:q1","question":"La capacidad de una caja indica…","options":["Solo su color","Cuánto puede contener","Cuántos años tiene"],"answer":"B","hint":"Observa el material del que estamos hablando.","level":2},{"id":"i-full:q2","question":"Decir que un vaso está vacío de agua significa…","options":["Que no existe","Que está lleno de agua","Que no contiene agua"],"answer":"C","hint":"Observa el material del que estamos hablando.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"i-weight","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Pesado y ligero","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Pesado y ligero","pesado y ligero","comparar pesos"],"explanation":"Podemos comparar objetos para notar cuál resulta más pesado o más ligero. El tamaño no basta: algunos objetos grandes son ligeros y otros pequeños pesan más. Usamos objetos seguros y fáciles de manejar.","simpler":"No mires solo el tamaño. Una caja grande vacía puede ser más ligera que una pequeña llena.","example":"Con un adulto, compara una caja de cartón vacía y otra igual con piezas grandes. Si hay una balanza de platillos, observa qué lado baja, sin usar objetos peligrosos.","why":"Los materiales y la cantidad de materia influyen; un volumen grande de un material ligero puede pesar menos que uno pequeño de otro material.","misconception":"El tamaño y lo pesado que resulta un objeto no son lo mismo.","hints":["Compara usando objetos seguros o una balanza, no solo mirando.","No mires solo el tamaño. Una caja grande vacía puede ser más ligera que una pequeña llena.","Con un adulto, compara una caja de cartón vacía y otra igual con piezas grandes. Si hay una balanza de platillos, observa qué lado baja, sin usar objetos peligrosos."],"quiz":[{"id":"i-weight:q0","question":"Entre dos cajas iguales, una vacía y otra llena de piezas, suele pesar más…","options":["La vacía","La llena de piezas","Pesan igual siempre"],"answer":"B","hint":"Compara usando objetos seguros o una balanza, no solo mirando.","level":1},{"id":"i-weight:q1","question":"¿Un objeto más grande siempre pesa más?","options":["No","Sí","Solo si es rojo"],"answer":"A","hint":"Compara usando objetos seguros o una balanza, no solo mirando.","level":2},{"id":"i-weight:q2","question":"¿Qué nos puede ayudar a comparar?","options":["Un dibujo del objeto","Su nombre","Una balanza adecuada"],"answer":"C","hint":"Compara usando objetos seguros o una balanza, no solo mirando.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"i-up-down","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Arriba y abajo","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Arriba y abajo","arriba y abajo","encima y debajo"],"explanation":"Arriba, abajo, encima y debajo nos ayudan a describir posiciones. Necesitamos un objeto o lugar de referencia. Podemos decir que un libro está encima de la mesa y una caja debajo de ella.","simpler":"Mira la mesa: encima está el tablero; debajo queda el espacio hacia el suelo.","example":"Con un adulto, pon un muñeco encima de una caja baja y otro en el suelo junto a ella. Describe dónde está cada uno sin subirte a muebles.","why":"Las palabras espaciales permiten que otra persona imagine la posición sin tener que verla directamente.","misconception":"Un objeto no está arriba o abajo de todo: depende de la referencia elegida.","hints":["Usa la mesa o la caja como referencia durante todo el juego.","Mira la mesa: encima está el tablero; debajo queda el espacio hacia el suelo.","Con un adulto, pon un muñeco encima de una caja baja y otro en el suelo junto a ella. Describe dónde está cada uno sin subirte a muebles."],"quiz":[{"id":"i-up-down:q0","question":"Un libro sobre la mesa está…","options":["Debajo de la mesa","Dentro de la mesa","Encima de la mesa"],"answer":"C","hint":"Usa la mesa o la caja como referencia durante todo el juego.","level":1},{"id":"i-up-down:q1","question":"Para indicar una posición ayuda…","options":["Decir respecto a qué objeto","Cambiar siempre de referencia sin avisar","Nombrar solo el color"],"answer":"A","hint":"Usa la mesa o la caja como referencia durante todo el juego.","level":2},{"id":"i-up-down:q2","question":"Para observar lo alto de un mueble debemos…","options":["Trepar solos","Pedir ayuda a un adulto","Subirnos a una silla inestable"],"answer":"B","hint":"Usa la mesa o la caja como referencia durante todo el juego.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"i-front-back","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Delante y detrás","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Delante y detrás","delante y detras","frente y espalda"],"explanation":"Delante y detrás indican posiciones respecto a una persona, un objeto orientado o un punto de vista acordado. Para entendernos conviene mirar desde el mismo lugar o explicar la referencia.","simpler":"Mira hacia dónde está mirando el muñeco. Delante queda hacia su cara y detrás hacia su espalda.","example":"Con un adulto, coloca un coche de juguete delante de un muñeco y una caja detrás. Gira el muñeco y vuelve a describir las posiciones desde su orientación.","why":"Acordar la orientación evita confusiones: describir el espacio también exige ponerse en el punto de vista de otra persona.","misconception":"Tu delante y el delante de alguien que te mira pueden apuntar en sentidos distintos.","hints":["Fíjate en hacia dónde mira la figura que usamos como referencia.","Mira hacia dónde está mirando el muñeco. Delante queda hacia su cara y detrás hacia su espalda.","Con un adulto, coloca un coche de juguete delante de un muñeco y una caja detrás. Gira el muñeco y vuelve a describir las posiciones desde su orientación."],"quiz":[{"id":"i-front-back:q0","question":"Respecto a una persona, delante está hacia…","options":["Su cara","Su espalda","Siempre la ventana"],"answer":"A","hint":"Fíjate en hacia dónde mira la figura que usamos como referencia.","level":1},{"id":"i-front-back:q1","question":"Para entendernos al describir delante y detrás conviene…","options":["Usar referencias distintas sin decirlo","Acordar la referencia","Cerrar los ojos siempre"],"answer":"B","hint":"Fíjate en hacia dónde mira la figura que usamos como referencia.","level":2},{"id":"i-front-back:q2","question":"Si gira el muñeco, delante de él…","options":["Nunca cambia","Siempre es el norte","Puede quedar hacia otro lugar"],"answer":"C","hint":"Fíjate en hacia dónde mira la figura que usamos como referencia.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"i-loud-soft","stage":"infantil","subject":"Comunicación y representación de la realidad","title":"Sonidos fuertes y suaves","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Sonidos fuertes y suaves","sonidos fuertes y suaves","fuerte y suave en musica"],"explanation":"Los sonidos pueden tener distinta intensidad: algunos se oyen fuertes y otros suaves. Fuerte no significa rápido ni agudo. Jugamos a escuchar sin gritar cerca del oído ni producir ruidos molestos.","simpler":"Da una palmada suave y luego otra un poco más fuerte, a una distancia cómoda. Escucha cuánto cambia.","example":"Un adulto puede tocar un tambor de juguete suavemente y después algo más fuerte. Podemos mantener el mismo ritmo mientras cambia la intensidad.","why":"Cambiar cuánto vibra un objeto puede cambiar la intensidad sin cambiar necesariamente la rapidez del patrón.","misconception":"La intensidad y la rapidez del ritmo son cualidades diferentes.","hints":["Escucha cuánto destaca el sonido, no cuántas veces se repite.","Da una palmada suave y luego otra un poco más fuerte, a una distancia cómoda. Escucha cuánto cambia.","Un adulto puede tocar un tambor de juguete suavemente y después algo más fuerte. Podemos mantener el mismo ritmo mientras cambia la intensidad."],"quiz":[{"id":"i-loud-soft:q0","question":"Fuerte y suave describen…","options":["La velocidad siempre","La intensidad del sonido","El color del instrumento"],"answer":"B","hint":"Escucha cuánto destaca el sonido, no cuántas veces se repite.","level":1},{"id":"i-loud-soft:q1","question":"¿Un sonido fuerte tiene que ser rápido?","options":["No","Sí","Solo si lo hace un tambor"],"answer":"A","hint":"Escucha cuánto destaca el sonido, no cuántas veces se repite.","level":2},{"id":"i-loud-soft:q2","question":"Para jugar con sonidos debemos…","options":["Gritar junto al oído","Buscar el ruido más molesto","Mantener un volumen cómodo"],"answer":"C","hint":"Escucha cuánto destaca el sonido, no cuántas veces se repite.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"i-fast-slow","stage":"infantil","subject":"Crecimiento en armonía","title":"Rápido y lento","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Rápido y lento","rapido y lento","velocidad de movimientos"],"explanation":"Rápido y lento describen cómo ocurre un movimiento o una secuencia en relación con el tiempo. Podemos variar la rapidez sin competir. Cada cuerpo tiene posibilidades distintas y merece respeto.","simpler":"Haz el mismo gesto despacio y después algo más deprisa, siempre sin dolor y en un espacio seguro.","example":"Con un adulto, mueve las manos como alas: primero despacio y luego más deprisa. Puedes hacerlo sentado o adaptar el gesto a tus posibilidades.","why":"Separar rapidez, fuerza y amplitud ayuda a conocer el movimiento sin convertir las diferencias personales en rankings.","misconception":"Moverse más rápido no significa aprender mejor ni valer más.","hints":["Compara el mismo gesto durante un tiempo parecido.","Haz el mismo gesto despacio y después algo más deprisa, siempre sin dolor y en un espacio seguro.","Con un adulto, mueve las manos como alas: primero despacio y luego más deprisa. Puedes hacerlo sentado o adaptar el gesto a tus posibilidades."],"quiz":[{"id":"i-fast-slow:q0","question":"Al repetir un gesto más veces en el mismo tiempo, lo hacemos…","options":["Más rápido","Más lento","Siempre más fuerte"],"answer":"A","hint":"Compara el mismo gesto durante un tiempo parecido.","level":1},{"id":"i-fast-slow:q1","question":"¿Hace falta competir para explorar movimientos?","options":["Sí","No","Solo si estamos sentados"],"answer":"B","hint":"Compara el mismo gesto durante un tiempo parecido.","level":2},{"id":"i-fast-slow:q2","question":"Una actividad de movimiento debe…","options":["Ser igual para todos sin adaptación","Hacerse aunque duela","Adaptarse y ser segura"],"answer":"C","hint":"Compara el mismo gesto durante un tiempo parecido.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"i-shadow","stage":"infantil","subject":"Descubrimiento y exploración del entorno","title":"Luz y sombras","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Luz y sombras","luz y sombras","sombras","como se forma una sombra"],"explanation":"Una sombra aparece cuando un objeto impide que parte de la luz llegue a una superficie. Su forma y tamaño pueden cambiar al mover el objeto o la luz. Observamos sin mirar al Sol ni dirigir luces intensas a los ojos.","simpler":"La luz llega a la pared. Si pones un objeto delante, queda una zona con menos luz: su sombra.","example":"Un adulto ilumina una pared con una linterna suave. Mueve un muñeco entre la linterna y la pared y observa su sombra sin acercar la luz a los ojos.","why":"La posición de la luz y del objeto determina qué zonas reciben luz y cuáles quedan parcialmente bloqueadas.","misconception":"La sombra no es un objeto separado que podamos guardar en una caja.","hints":["Busca la luz, el objeto y la superficie donde aparece la zona oscura.","La luz llega a la pared. Si pones un objeto delante, queda una zona con menos luz: su sombra.","Un adulto ilumina una pared con una linterna suave. Mueve un muñeco entre la linterna y la pared y observa su sombra sin acercar la luz a los ojos."],"quiz":[{"id":"i-shadow:q0","question":"Para formar una sombra con un muñeco necesitamos…","options":["Solo sonido","Una luz y una superficie","Solo agua"],"answer":"B","hint":"Busca la luz, el objeto y la superficie donde aparece la zona oscura.","level":1},{"id":"i-shadow:q1","question":"La sombra aparece porque el objeto…","options":["Bloquea parte de la luz","Crea otra pared","Siempre cambia de color"],"answer":"A","hint":"Busca la luz, el objeto y la superficie donde aparece la zona oscura.","level":2},{"id":"i-shadow:q2","question":"Al mover el muñeco respecto a la luz, su sombra…","options":["Nunca cambia","Desaparece para siempre","Puede cambiar de tamaño o posición"],"answer":"C","hint":"Busca la luz, el objeto y la superficie donde aparece la zona oscura.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"i-save-water","stage":"infantil","subject":"Crecimiento en armonía","title":"Cuidar el agua","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Cuidar el agua","cuidar el agua","ahorrar agua"],"explanation":"Usamos agua para beber, cocinar, limpiar y cuidar seres vivos. Podemos evitar desperdiciarla con acciones pequeñas y seguras. Un adulto ayuda a decidir qué agua es adecuada para cada uso.","simpler":"Usa la que necesitas y cierra el grifo cuando ya no lo usas. Si ves una fuga, avisa a un adulto.","example":"Mientras un adulto te ayuda a lavarte las manos, puedes cerrar el grifo al enjabonarte y abrirlo para aclarar. Nunca bebas agua de origen desconocido.","why":"Usar responsablemente un recurso significa atender nuestras necesidades sin desperdiciar ni poner en riesgo la salud.","misconception":"Que el agua parezca limpia no demuestra que sea potable.","hints":["Distingue cuidar un recurso de dejar de usarlo cuando lo necesitas.","Usa la que necesitas y cierra el grifo cuando ya no lo usas. Si ves una fuga, avisa a un adulto.","Mientras un adulto te ayuda a lavarte las manos, puedes cerrar el grifo al enjabonarte y abrirlo para aclarar. Nunca bebas agua de origen desconocido."],"quiz":[{"id":"i-save-water:q0","question":"Si el grifo gotea sin parar, conviene…","options":["Avisar a un adulto","Beber del suelo","Dejarlo siempre abierto"],"answer":"A","hint":"Distingue cuidar un recurso de dejar de usarlo cuando lo necesitas.","level":1},{"id":"i-save-water:q1","question":"¿Podemos beber cualquier agua transparente?","options":["Sí","No","Solo si está fría"],"answer":"B","hint":"Distingue cuidar un recurso de dejar de usarlo cuando lo necesitas.","level":2},{"id":"i-save-water:q2","question":"Cuidar el agua significa…","options":["No lavarse nunca","No beber cuando lo necesitas","Evitar desperdiciarla y usarla de forma segura"],"answer":"C","hint":"Distingue cuidar un recurso de dejar de usarlo cuando lo necesitas.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"i-story","stage":"infantil","subject":"Comunicación y representación de la realidad","title":"Contar una historia","grade_min":4,"grade_max":5,"school_years":["Infantil · 4 años","Infantil · 5 años"],"aliases":["Contar una historia","contar una historia","inventar un cuento","partes de un cuento"],"explanation":"Una historia puede presentar personajes, contar qué les sucede y mostrar cómo termina ese episodio. Podemos inventarla hablando, con dibujos o con gestos. No hace falta saber escribir ni que todos los cuentos sean iguales.","simpler":"Elige un personaje. Piensa qué le ocurre y cuenta qué pasa después.","example":"Un conejo pierde su cesta, pide ayuda a una tortuga y la encuentran junto a un árbol. Hay un personaje, algo que sucede y una forma de resolverlo.","why":"Ordenar acontecimientos y relacionar personajes ayuda a quien escucha a construir el significado de la historia.","misconception":"No existe una única historia correcta cuando estamos creando un cuento.","hints":["Piensa quién participa y qué le ocurre primero.","Elige un personaje. Piensa qué le ocurre y cuenta qué pasa después.","Un conejo pierde su cesta, pide ayuda a una tortuga y la encuentran junto a un árbol. Hay un personaje, algo que sucede y una forma de resolverlo."],"quiz":[{"id":"i-story:q0","question":"En nuestro cuento, ¿quién pierde la cesta?","options":["La tortuga","El conejo","El árbol"],"answer":"B","hint":"Piensa quién participa y qué le ocurre primero.","level":1},{"id":"i-story:q1","question":"¿Podemos contar una historia con dibujos?","options":["Sí","No","Solo si escribimos todo"],"answer":"A","hint":"Piensa quién participa y qué le ocurre primero.","level":2},{"id":"i-story:q2","question":"Para que alguien siga la historia ayuda…","options":["Cambiar todos los hechos sin avisar","No contar qué sucede","Ordenar los acontecimientos"],"answer":"C","hint":"Piensa quién participa y qué le ocurre primero.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"i-team","stage":"infantil","subject":"Crecimiento en armonía","title":"Colaborar","grade_min":3,"grade_max":5,"school_years":["Infantil · 3 años","Infantil · 4 años","Infantil · 5 años"],"aliases":["Colaborar","colaborar","trabajar juntos","ayudarnos"],"explanation":"Colaborar es hacer algo con otras personas aportando y escuchando. Podemos repartir tareas de forma justa y pedir ayuda. Nadie tiene que hacerlo todo ni dejar de participar por necesitar una adaptación.","simpler":"Cada persona puede aportar una parte. Preguntamos qué necesita la otra y acordamos cómo hacerlo.","example":"Para ordenar materiales, una persona reúne las piezas grandes y otra coloca las cajas. Un adulto ayuda a adaptar las tareas para que todas puedan participar.","why":"La colaboración aprovecha aportaciones diferentes y coordina los esfuerzos hacia una meta compartida.","misconception":"Hacer algo de otra manera no significa colaborar menos.","hints":["Busca cómo puede participar cada persona.","Cada persona puede aportar una parte. Preguntamos qué necesita la otra y acordamos cómo hacerlo.","Para ordenar materiales, una persona reúne las piezas grandes y otra coloca las cajas. Un adulto ayuda a adaptar las tareas para que todas puedan participar."],"quiz":[{"id":"i-team:q0","question":"Colaborar significa…","options":["Que una persona haga todo","Ganar a los demás","Aportar y escuchar"],"answer":"C","hint":"Busca cómo puede participar cada persona.","level":1},{"id":"i-team:q1","question":"Si una tarea me cuesta, puedo…","options":["Pedir ayuda","Ocultarlo siempre","Quitarle el trabajo a otro"],"answer":"A","hint":"Busca cómo puede participar cada persona.","level":2},{"id":"i-team:q2","question":"Repartir tareas de forma justa supone…","options":["Dar siempre lo mismo sin escuchar","Tener en cuenta posibilidades y necesidades","Dejar fuera a quien necesita apoyo"],"answer":"B","hint":"Busca cómo puede participar cada persona.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-1654","curriculum_source_key":"BOE-A-2022-1654","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-even","stage":"primaria","subject":"Matemáticas","title":"Números pares e impares","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Números pares e impares","pares e impares","numeros pares","numeros impares"],"explanation":"Un número natural es par si se puede repartir en parejas sin que sobre ningún elemento. Si sobra uno, es impar. En escritura decimal son pares los números que terminan en 0, 2, 4, 6 u 8. El cero también es par.","simpler":"Forma grupos de dos. Si no sobra nada, la cantidad es par; si sobra una pieza, es impar.","example":"Con 8 fichas haces cuatro parejas. Con 9 haces cuatro parejas y queda una ficha sin pareja.","why":"Un número par puede expresarse como dos por un entero; un impar queda una unidad por encima de algún número par.","misconception":"No todos los números de dos cifras son pares; importa si son divisibles entre dos.","hints":["Prueba a repartir en grupos de dos o mira la última cifra.","Forma grupos de dos. Si no sobra nada, la cantidad es par; si sobra una pieza, es impar.","Con 8 fichas haces cuatro parejas. Con 9 haces cuatro parejas y queda una ficha sin pareja."],"quiz":[{"id":"p-even:q0","question":"¿Qué número es par?","options":["13","18","21"],"answer":"B","hint":"Prueba a repartir en grupos de dos o mira la última cifra.","level":1},{"id":"p-even:q1","question":"Al formar parejas con 7 fichas sobra…","options":["Una ficha","Ninguna","Tres siempre"],"answer":"A","hint":"Prueba a repartir en grupos de dos o mira la última cifra.","level":2},{"id":"p-even:q2","question":"¿El cero es par?","options":["No","Solo algunas veces","Sí"],"answer":"C","hint":"Prueba a repartir en grupos de dos o mira la última cifra.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-factors","stage":"primaria","subject":"Matemáticas","title":"Múltiplos y divisores","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Múltiplos y divisores","multiplos y divisores","multiplos","divisores"],"explanation":"Los múltiplos de un número se obtienen multiplicándolo por números enteros. En naturales, 12 es múltiplo de 3 porque 3 × 4 = 12; a la vez, 3 es divisor de 12 porque la división es exacta. Son dos maneras de describir una relación.","simpler":"Si 3 cabe exactamente cuatro veces en 12, 3 divide a 12 y 12 es un múltiplo de 3.","example":"Los múltiplos naturales de 4 empiezan 0, 4, 8, 12, 16. Los divisores positivos de 12 son 1, 2, 3, 4, 6 y 12.","why":"La multiplicación muestra cuántas veces cabe una cantidad en otra; la división exacta expresa esa misma relación al revés.","misconception":"Divisor y múltiplo no son palabras intercambiables: describe cuál divide a cuál.","hints":["Comprueba la relación con una multiplicación o una división exacta.","Si 3 cabe exactamente cuatro veces en 12, 3 divide a 12 y 12 es un múltiplo de 3.","Los múltiplos naturales de 4 empiezan 0, 4, 8, 12, 16. Los divisores positivos de 12 son 1, 2, 3, 4, 6 y 12."],"quiz":[{"id":"p-factors:q0","question":"¿Cuál es múltiplo de 4?","options":["14","18","20"],"answer":"C","hint":"Comprueba la relación con una multiplicación o una división exacta.","level":1},{"id":"p-factors:q1","question":"¿Cuál es divisor de 12?","options":["3","5","7"],"answer":"A","hint":"Comprueba la relación con una multiplicación o una división exacta.","level":2},{"id":"p-factors:q2","question":"Si 5 × 6 = 30, entonces…","options":["30 es divisor de 5","5 es divisor de 30","6 no divide a 30"],"answer":"B","hint":"Comprueba la relación con una multiplicación o una división exacta.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-lcm","stage":"primaria","subject":"Matemáticas","title":"Mínimo común múltiplo","grade_min":5,"grade_max":6,"school_years":["5º de Primaria","6º de Primaria"],"aliases":["Mínimo común múltiplo","minimo comun multiplo","mcm"],"explanation":"El mínimo común múltiplo de dos enteros positivos es el menor múltiplo positivo que comparten. Puedes listar múltiplos hasta encontrar el primero en común. No basta con sumar los números.","simpler":"Busca un número que esté en las dos listas de múltiplos y elige el menor positivo.","example":"Múltiplos positivos de 4: 4, 8, 12, 16. De 6: 6, 12, 18. El primero compartido es 12: mcm(4,6) = 12.","why":"Una coincidencia de ciclos ocurre cuando el tiempo transcurrido contiene un número entero de repeticiones de ambos ciclos.","misconception":"El producto de dos números es un múltiplo común, pero no siempre el mínimo.","hints":["Enumera los múltiplos positivos y busca la primera coincidencia.","Busca un número que esté en las dos listas de múltiplos y elige el menor positivo.","Múltiplos positivos de 4: 4, 8, 12, 16. De 6: 6, 12, 18. El primero compartido es 12: mcm(4,6) = 12."],"quiz":[{"id":"p-lcm:q0","question":"El mcm de 3 y 4 es…","options":["7","12","24"],"answer":"B","hint":"Enumera los múltiplos positivos y busca la primera coincidencia.","level":1},{"id":"p-lcm:q1","question":"El mcm de 5 y 10 es…","options":["10","15","50"],"answer":"A","hint":"Enumera los múltiplos positivos y busca la primera coincidencia.","level":2},{"id":"p-lcm:q2","question":"Si dos señales se repiten cada 4 y 6 minutos y coinciden ahora, volverán a coincidir por primera vez en…","options":["2 minutos","10 minutos","12 minutos"],"answer":"C","hint":"Enumera los múltiplos positivos y busca la primera coincidencia.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-gcd","stage":"primaria","subject":"Matemáticas","title":"Máximo común divisor","grade_min":5,"grade_max":6,"school_years":["5º de Primaria","6º de Primaria"],"aliases":["Máximo común divisor","maximo comun divisor","mcd"],"explanation":"El máximo común divisor de dos enteros positivos es el mayor divisor positivo que comparten. Sirve, por ejemplo, para formar grupos iguales del mayor tamaño posible sin que sobre nada, cuando las condiciones del problema lo piden.","simpler":"Busca qué números dividen exactamente a las dos cantidades. Elige el mayor.","example":"Los divisores de 12 son 1, 2, 3, 4, 6 y 12. Los de 18 son 1, 2, 3, 6, 9 y 18. El mayor común es 6.","why":"Un divisor común permite repartir ambas cantidades exactamente; elegir el mayor optimiza el tamaño del grupo bajo esa condición.","misconception":"No confundas buscar el mayor divisor común con buscar el menor múltiplo común.","hints":["Empieza por los divisores de la cantidad menor.","Busca qué números dividen exactamente a las dos cantidades. Elige el mayor.","Los divisores de 12 son 1, 2, 3, 4, 6 y 12. Los de 18 son 1, 2, 3, 6, 9 y 18. El mayor común es 6."],"quiz":[{"id":"p-gcd:q0","question":"El mcd de 12 y 18 es…","options":["6","12","36"],"answer":"A","hint":"Empieza por los divisores de la cantidad menor.","level":1},{"id":"p-gcd:q1","question":"El mcd de 8 y 12 es…","options":["2","4","24"],"answer":"B","hint":"Empieza por los divisores de la cantidad menor.","level":2},{"id":"p-gcd:q2","question":"Para ser divisor común, un número debe…","options":["Ser mayor que ambos","Ser su suma","Dividir exactamente a los dos"],"answer":"C","hint":"Empieza por los divisores de la cantidad menor.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-number-line","stage":"primaria","subject":"Matemáticas","title":"La recta numérica","grade_min":2,"grade_max":6,"school_years":["2º de Primaria","3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La recta numérica","recta numerica","ordenar numeros en la recta"],"explanation":"La recta numérica representa números mediante posiciones. Los intervalos de igual valor deben ocupar la misma distancia. En la orientación habitual, los números aumentan hacia la derecha. Para leerla, observa primero la escala.","simpler":"Mira cuánto vale cada salto. Avanzar a la derecha aumenta el número en la orientación habitual.","example":"Si marcas 0, 2, 4 y 6 a distancias iguales, cada salto vale 2. El punto intermedio entre 4 y 6 representa 5.","why":"La distancia representa diferencias numéricas; una escala constante permite interpolar posiciones entre las marcas.","misconception":"No todos los dibujos de rectas tienen saltos de una unidad.","hints":["Lee dos marcas consecutivas y calcula su diferencia.","Mira cuánto vale cada salto. Avanzar a la derecha aumenta el número en la orientación habitual.","Si marcas 0, 2, 4 y 6 a distancias iguales, cada salto vale 2. El punto intermedio entre 4 y 6 representa 5."],"quiz":[{"id":"p-number-line:q0","question":"En 0, 2, 4, 6, cada intervalo vale…","options":["1","2","6"],"answer":"B","hint":"Lee dos marcas consecutivas y calcula su diferencia.","level":1},{"id":"p-number-line:q1","question":"El punto a mitad entre 4 y 6 representa…","options":["5","4","10"],"answer":"A","hint":"Lee dos marcas consecutivas y calcula su diferencia.","level":2},{"id":"p-number-line:q2","question":"Antes de leer una recta debemos comprobar…","options":["Solo su color","La longitud del papel","La escala de sus intervalos"],"answer":"C","hint":"Lee dos marcas consecutivas y calcula su diferencia.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-angles","stage":"primaria","subject":"Matemáticas","title":"Los ángulos","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Los ángulos","angulos","angulo recto","angulos agudos y obtusos"],"explanation":"Un ángulo se forma con dos semirrectas de origen común. Su amplitud mide el giro entre ellas, no la longitud de sus lados. Un ángulo recto mide 90°; uno agudo, menos de 90°; uno obtuso, más de 90° y menos de 180°.","simpler":"Piensa en cuánto giras de una dirección a otra. Abrir más los lados aumenta el ángulo.","example":"La esquina de un rectángulo representa un ángulo recto. Un ángulo de 40° es agudo y uno de 120° es obtuso.","why":"Medir un ángulo significa medir un giro relativo; prolongar sus lados no modifica las direcciones que lo forman.","misconception":"La longitud de los lados dibujados no determina la amplitud.","hints":["Compara la amplitud con los 90° de un ángulo recto.","Piensa en cuánto giras de una dirección a otra. Abrir más los lados aumenta el ángulo.","La esquina de un rectángulo representa un ángulo recto. Un ángulo de 40° es agudo y uno de 120° es obtuso."],"quiz":[{"id":"p-angles:q0","question":"Un ángulo de 120° es…","options":["Agudo","Recto","Obtuso"],"answer":"C","hint":"Compara la amplitud con los 90° de un ángulo recto.","level":1},{"id":"p-angles:q1","question":"Un ángulo recto mide…","options":["90°","45°","180°"],"answer":"A","hint":"Compara la amplitud con los 90° de un ángulo recto.","level":2},{"id":"p-angles:q2","question":"Al alargar los lados dibujados sin cambiar su dirección, el ángulo…","options":["Siempre aumenta","Conserva su amplitud","Desaparece"],"answer":"B","hint":"Compara la amplitud con los 90° de un ángulo recto.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-symmetry","stage":"primaria","subject":"Matemáticas","title":"Simetría axial","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Simetría axial","simetria axial","eje de simetria","simetria"],"explanation":"Una figura tiene simetría axial respecto a una línea si al reflejarla sobre esa línea coincide consigo misma. Los puntos correspondientes quedan a la misma distancia del eje en lados opuestos. No todas las figuras tienen un eje de simetría.","simpler":"Imagina doblar una figura por una línea. Si ambas partes coinciden, esa línea es un eje de simetría.","example":"Un rectángulo que no sea cuadrado tiene dos ejes de simetría: las líneas por su centro paralelas a sus lados. Sus diagonales no son ejes.","why":"La simetría exige correspondencia punto a punto, no solo igualdad de tamaños o áreas.","misconception":"Dividir una figura en dos áreas iguales no garantiza que esas partes sean imágenes reflejadas.","hints":["Prueba la coincidencia mediante un reflejo o un doblez imaginario.","Imagina doblar una figura por una línea. Si ambas partes coinciden, esa línea es un eje de simetría.","Un rectángulo que no sea cuadrado tiene dos ejes de simetría: las líneas por su centro paralelas a sus lados. Sus diagonales no son ejes."],"quiz":[{"id":"p-symmetry:q0","question":"Un rectángulo no cuadrado tiene…","options":["Dos ejes de simetría","Cuatro siempre","Ninguno"],"answer":"A","hint":"Prueba la coincidencia mediante un reflejo o un doblez imaginario.","level":1},{"id":"p-symmetry:q1","question":"Dos puntos reflejados respecto al eje están…","options":["En el mismo lado siempre","A igual distancia del eje","A cualquier distancia"],"answer":"B","hint":"Prueba la coincidencia mediante un reflejo o un doblez imaginario.","level":2},{"id":"p-symmetry:q2","question":"Las diagonales de un rectángulo no cuadrado…","options":["Siempre son sus únicos ejes","Son cuatro","No son ejes de simetría"],"answer":"C","hint":"Prueba la coincidencia mediante un reflejo o un doblez imaginario.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-volume","stage":"primaria","subject":"Matemáticas","title":"Volumen de un prisma rectangular","grade_min":5,"grade_max":6,"school_years":["5º de Primaria","6º de Primaria"],"aliases":["Volumen de un prisma rectangular","volumen","volumen de un prisma","volumen de una caja"],"explanation":"El volumen mide el espacio tridimensional que ocupa un cuerpo. En un prisma rectangular se calcula largo × ancho × alto, con las tres medidas en la misma unidad. Se expresa en unidades cúbicas, como cm³.","simpler":"Cuenta cubitos en una capa y multiplica por el número de capas.","example":"Una caja interior de 4 cm por 3 cm por 2 cm tiene 12 cubitos de 1 cm³ en cada capa y dos capas: 24 cm³.","why":"Cada cubito aporta una unidad de volumen; multiplicar las tres dimensiones cuenta filas, columnas y capas.","misconception":"Área y volumen no tienen las mismas unidades.","hints":["Cuenta primero una capa y después cuántas capas caben.","Cuenta cubitos en una capa y multiplica por el número de capas.","Una caja interior de 4 cm por 3 cm por 2 cm tiene 12 cubitos de 1 cm³ en cada capa y dos capas: 24 cm³."],"quiz":[{"id":"p-volume:q0","question":"Un prisma de 4 × 3 × 2 cm tiene volumen…","options":["9 cm³","24 cm³","24 cm²"],"answer":"B","hint":"Cuenta primero una capa y después cuántas capas caben.","level":1},{"id":"p-volume:q1","question":"El volumen se expresa en…","options":["Unidades cúbicas","Solo unidades cuadradas","Grados"],"answer":"A","hint":"Cuenta primero una capa y después cuántas capas caben.","level":2},{"id":"p-volume:q2","question":"Si duplicas la altura y mantienes largo y ancho, el volumen…","options":["Se mantiene","Se reduce a la mitad","Se duplica"],"answer":"C","hint":"Cuenta primero una capa y después cuántas capas caben.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-synonyms","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"Sinónimos y antónimos","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Sinónimos y antónimos","sinonimos y antonimos","sinonimos","antonimos"],"explanation":"Los sinónimos tienen un significado igual o parecido en un contexto; los antónimos expresan significados opuestos en algún aspecto. Una palabra puede tener varios sentidos, así que no basta sustituirla sin leer la oración.","simpler":"Busca palabras que expresen algo parecido o algo contrario, pero comprueba la frase completa.","example":"En «un camino largo», extenso puede tener un sentido parecido y corto uno contrario. En otros contextos, largo puede necesitar otra sustitución.","why":"El significado depende también de las palabras que acompañan al término y de la situación comunicativa.","misconception":"Dos sinónimos no son intercambiables en todos los usos.","hints":["Lee la oración entera para decidir qué sentido tiene la palabra.","Busca palabras que expresen algo parecido o algo contrario, pero comprueba la frase completa.","En «un camino largo», extenso puede tener un sentido parecido y corto uno contrario. En otros contextos, largo puede necesitar otra sustitución."],"quiz":[{"id":"p-synonyms:q0","question":"Un antónimo de largo en «un camino largo» es…","options":["Ancho","Corto","Extenso"],"answer":"B","hint":"Lee la oración entera para decidir qué sentido tiene la palabra.","level":1},{"id":"p-synonyms:q1","question":"Los sinónimos tienen significados…","options":["Parecidos en un contexto","Siempre opuestos","Siempre idénticos en cualquier frase"],"answer":"A","hint":"Lee la oración entera para decidir qué sentido tiene la palabra.","level":2},{"id":"p-synonyms:q2","question":"Antes de sustituir una palabra conviene…","options":["Mirar solo su primera letra","Contar sus sílabas","Comprobar el contexto"],"answer":"C","hint":"Lee la oración entera para decidir qué sentido tiene la palabra.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-affixes","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"Prefijos y sufijos","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Prefijos y sufijos","prefijos y sufijos","prefijos","sufijos"],"explanation":"Un prefijo se coloca antes de una base y un sufijo después. Pueden formar palabras nuevas y modificar su significado o categoría. No toda secuencia de letras al principio o al final de una palabra es un afijo.","simpler":"Mira si añadimos una parte antes o después de una palabra o base reconocible.","example":"En rehacer, re- indica repetición y aparece antes de hacer. En panadero, -ero ayuda a formar un nombre de oficio a partir de pan.","why":"Los afijos son unidades con función en la formación de palabras, no simples fragmentos de escritura elegidos al azar.","misconception":"Coincidir en unas letras iniciales no demuestra que dos palabras compartan prefijo.","hints":["Localiza la base y observa qué parte se añade.","Mira si añadimos una parte antes o después de una palabra o base reconocible.","En rehacer, re- indica repetición y aparece antes de hacer. En panadero, -ero ayuda a formar un nombre de oficio a partir de pan."],"quiz":[{"id":"p-affixes:q0","question":"En rehacer, re- es…","options":["Un sufijo","La palabra completa","Un prefijo"],"answer":"C","hint":"Localiza la base y observa qué parte se añade.","level":1},{"id":"p-affixes:q1","question":"En panadero, -ero aparece…","options":["Después de la base","Antes de pan","Fuera de la palabra"],"answer":"A","hint":"Localiza la base y observa qué parte se añade.","level":2},{"id":"p-affixes:q2","question":"Para identificar un afijo debemos…","options":["Separar letras al azar","Reconocer su relación con una base y su función","Mirar solo la longitud"],"answer":"B","hint":"Localiza la base y observa qué parte se añade.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-determiners","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"Los determinantes","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Los determinantes","determinantes","articulos y demostrativos"],"explanation":"Los determinantes acompañan al sustantivo y ayudan a precisar su referencia, cantidad u otras propiedades. Los artículos y demostrativos son ejemplos. En muchos casos concuerdan en género y número con el sustantivo.","simpler":"En «esta mochila», esta ayuda a señalar de qué mochila hablamos.","example":"En «las casas», las es un artículo. En «aquellos libros», aquellos es un demostrativo y concuerda con libros en masculino plural.","why":"Los determinantes orientan al oyente sobre qué entidades se mencionan y cómo se identifican dentro del contexto.","misconception":"Un determinante no es simplemente cualquier palabra situada cerca de un nombre.","hints":["Busca la palabra que presenta o precisa el sustantivo.","En «esta mochila», esta ayuda a señalar de qué mochila hablamos.","En «las casas», las es un artículo. En «aquellos libros», aquellos es un demostrativo y concuerda con libros en masculino plural."],"quiz":[{"id":"p-determiners:q0","question":"En «esta mochila», el determinante es…","options":["Esta","Mochila","Ninguno"],"answer":"A","hint":"Busca la palabra que presenta o precisa el sustantivo.","level":1},{"id":"p-determiners:q1","question":"¿Qué grupo concuerda?","options":["Aquella libros","Aquellos libros","Aquellos libro"],"answer":"B","hint":"Busca la palabra que presenta o precisa el sustantivo.","level":2},{"id":"p-determiners:q2","question":"En «las casas», las es…","options":["Un verbo","Un adjetivo de color","Un artículo"],"answer":"C","hint":"Busca la palabra que presenta o precisa el sustantivo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-pronouns","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"Los pronombres personales","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Los pronombres personales","pronombres personales","pronombres"],"explanation":"Los pronombres personales pueden referirse a quienes participan en la comunicación o a otras personas y entidades sin repetir sus nombres. Yo señala a quien habla; tú, a su interlocutor. Su referencia cambia según quién los use.","simpler":"Un pronombre permite hablar de alguien sin repetir su nombre: Ana puede pasar a ser ella.","example":"«Ana canta. Ella canta». Ella se refiere a Ana en ese contexto. Si Ana dice «yo», yo se refiere a Ana; si lo dice Luis, a Luis.","why":"Algunos pronombres dependen de la situación comunicativa; otros recuperan una referencia ya mencionada.","misconception":"Un pronombre no conserva siempre el mismo referente en todas las conversaciones.","hints":["Pregunta quién habla y a quién se refiere cada palabra.","Un pronombre permite hablar de alguien sin repetir su nombre: Ana puede pasar a ser ella.","«Ana canta. Ella canta». Ella se refiere a Ana en ese contexto. Si Ana dice «yo», yo se refiere a Ana; si lo dice Luis, a Luis."],"quiz":[{"id":"p-pronouns:q0","question":"En «Ana llega. Ella saluda», ella se refiere a…","options":["La llegada","Ana","Otra persona siempre"],"answer":"B","hint":"Pregunta quién habla y a quién se refiere cada palabra.","level":1},{"id":"p-pronouns:q1","question":"Yo se refiere normalmente a…","options":["Quien habla","Quien escucha siempre","Un lugar"],"answer":"A","hint":"Pregunta quién habla y a quién se refiere cada palabra.","level":2},{"id":"p-pronouns:q2","question":"¿Qué palabra es un pronombre personal?","options":["Mesa","Rojo","Nosotros"],"answer":"C","hint":"Pregunta quién habla y a quién se refiere cada palabra.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-punctuation","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"El punto y la coma","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El punto y la coma","el punto y la coma","signos de puntuacion"],"explanation":"El punto cierra un enunciado y después suele comenzar otro con mayúscula. La coma puede separar elementos de una enumeración o delimitar ciertos fragmentos. No se coloca automáticamente cada vez que respiramos ni entre sujeto y verbo sin otra razón.","simpler":"La puntuación ayuda a organizar el significado. No es solo una marca de pausa al hablar.","example":"«Traje pan, queso y fruta». Las comas separan elementos de la lista. «Mi hermana lee» no necesita una coma entre hermana y lee.","why":"Los signos guían la lectura de relaciones gramaticales e ideas; una pausa oral no determina por sí sola un signo escrito.","misconception":"La coma no debe separar por sistema el sujeto de su verbo.","hints":["Observa la estructura y el significado, no solo las pausas de la voz.","La puntuación ayuda a organizar el significado. No es solo una marca de pausa al hablar.","«Traje pan, queso y fruta». Las comas separan elementos de la lista. «Mi hermana lee» no necesita una coma entre hermana y lee."],"quiz":[{"id":"p-punctuation:q0","question":"Después de un punto que cierra un enunciado, la siguiente palabra suele empezar con…","options":["Minúscula siempre","Un número","Mayúscula"],"answer":"C","hint":"Observa la estructura y el significado, no solo las pausas de la voz.","level":1},{"id":"p-punctuation:q1","question":"En una lista, la coma puede…","options":["Separar elementos","Cambiar la ortografía de todos","Sustituir siempre todas las palabras"],"answer":"A","hint":"Observa la estructura y el significado, no solo las pausas de la voz.","level":2},{"id":"p-punctuation:q2","question":"¿Es correcta sin otra circunstancia la coma de «Mi hermana, lee»?","options":["Sí, siempre","No, separa sujeto y verbo sin motivo","Solo porque hacemos una pausa"],"answer":"B","hint":"Observa la estructura y el significado, no solo las pausas de la voz.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-inference","stage":"primaria","subject":"Lengua Castellana y Literatura","title":"Comprensión e inferencias","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Comprensión e inferencias","inferencias","comprension inferencial","inferir en un texto"],"explanation":"Comprender un texto incluye distinguir lo que dice expresamente de lo que podemos inferir con apoyo en sus pistas. Una inferencia razonable no es una certeza absoluta ni una invitación a inventar detalles sin base.","simpler":"Busca una pista en el texto y explica qué te hace pensar. Diferencia lo seguro de lo probable.","example":"Texto: «Al entrar, Julia dejó un paraguas mojado junto a la puerta». Sabemos que el paraguas estaba mojado; es razonable pensar que había llovido, pero el texto no lo afirma directamente.","why":"El lector combina pistas y conocimientos, pero debe distinguir el grado de apoyo de cada conclusión.","misconception":"Inferir no significa afirmar como hecho cualquier cosa imaginable.","hints":["Señala qué palabras del texto apoyan tu interpretación.","Busca una pista en el texto y explica qué te hace pensar. Diferencia lo seguro de lo probable.","Texto: «Al entrar, Julia dejó un paraguas mojado junto a la puerta». Sabemos que el paraguas estaba mojado; es razonable pensar que había llovido, pero el texto no lo afirma directamente."],"quiz":[{"id":"p-inference:q0","question":"¿Qué dice expresamente el texto?","options":["Que había tormenta","Que el paraguas estaba mojado","Que Julia iba al colegio"],"answer":"B","hint":"Señala qué palabras del texto apoyan tu interpretación.","level":1},{"id":"p-inference:q1","question":"Que había llovido es…","options":["Una inferencia posible","Una frase literal del texto","La única causa imaginable"],"answer":"A","hint":"Señala qué palabras del texto apoyan tu interpretación.","level":2},{"id":"p-inference:q2","question":"¿Qué detalle no podemos asegurar con esas pistas?","options":["Que hay una puerta","Que Julia entra","La edad de Julia"],"answer":"C","hint":"Señala qué palabras del texto apoyan tu interpretación.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-digestion","stage":"primaria","subject":"Conocimiento del Medio","title":"La digestión","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La digestión","digestion","aparato digestivo","sistema digestivo"],"explanation":"La digestión transforma los alimentos para que sus componentes aprovechables puedan ser absorbidos. Comienza en la boca y continúa en distintos órganos. La mayor parte de la absorción de nutrientes ocurre en el intestino delgado; no todo sucede en el estómago.","simpler":"El cuerpo descompone los alimentos y absorbe sustancias que puede utilizar. Cada parte del aparato digestivo cumple una función.","example":"Al masticar, fragmentas el alimento y lo mezclas con saliva. Más adelante, el intestino delgado absorbe gran parte de los nutrientes hacia el medio interno.","why":"La transformación y la absorción son procesos relacionados y distintos que requieren la acción coordinada de varios órganos.","misconception":"El estómago es importante, pero no realiza por sí solo todo el proceso.","hints":["Sigue el recorrido del alimento y distingue transformar de absorber.","El cuerpo descompone los alimentos y absorbe sustancias que puede utilizar. Cada parte del aparato digestivo cumple una función.","Al masticar, fragmentas el alimento y lo mezclas con saliva. Más adelante, el intestino delgado absorbe gran parte de los nutrientes hacia el medio interno."],"quiz":[{"id":"p-digestion:q0","question":"La digestión comienza en…","options":["La boca","El intestino grueso siempre","Los pulmones"],"answer":"A","hint":"Sigue el recorrido del alimento y distingue transformar de absorber.","level":1},{"id":"p-digestion:q1","question":"La mayor parte de la absorción de nutrientes ocurre en…","options":["El esófago","El intestino delgado","La tráquea"],"answer":"B","hint":"Sigue el recorrido del alimento y distingue transformar de absorber.","level":2},{"id":"p-digestion:q2","question":"¿Toda la digestión sucede en el estómago?","options":["Sí","Solo de noche","No"],"answer":"C","hint":"Sigue el recorrido del alimento y distingue transformar de absorber.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-breathing","stage":"primaria","subject":"Conocimiento del Medio","title":"La respiración y los pulmones","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La respiración y los pulmones","aparato respiratorio","pulmones","respiracion pulmonar"],"explanation":"Al ventilar, el aire entra y sale de los pulmones. En los alvéolos se intercambian gases con la sangre: entra oxígeno en ella y sale dióxido de carbono. La respiración celular es otro proceso, relacionado con el uso de sustancias y energía en las células.","simpler":"Los pulmones ayudan a pasar oxígeno del aire a la sangre y a eliminar dióxido de carbono.","example":"El aire pasa por las vías respiratorias hasta los pulmones. Los alvéolos ofrecen una gran superficie para intercambiar gases con los capilares.","why":"Los gases atraviesan superficies de intercambio; la sangre transporta después sustancias entre órganos y tejidos.","misconception":"Respirar no significa que el aire entero circule por todas las arterias.","hints":["Distingue el movimiento del aire y el intercambio de gases.","Los pulmones ayudan a pasar oxígeno del aire a la sangre y a eliminar dióxido de carbono.","El aire pasa por las vías respiratorias hasta los pulmones. Los alvéolos ofrecen una gran superficie para intercambiar gases con los capilares."],"quiz":[{"id":"p-breathing:q0","question":"El intercambio de gases ocurre principalmente en…","options":["El esófago","Los alvéolos","El estómago"],"answer":"B","hint":"Distingue el movimiento del aire y el intercambio de gases.","level":1},{"id":"p-breathing:q1","question":"El oxígeno pasa desde el aire alveolar hacia…","options":["La sangre","Los alimentos","La vejiga"],"answer":"A","hint":"Distingue el movimiento del aire y el intercambio de gases.","level":2},{"id":"p-breathing:q2","question":"Ventilar significa…","options":["Fabricar huesos","Digerir alimentos","Mover aire hacia dentro y fuera de los pulmones"],"answer":"C","hint":"Distingue el movimiento del aire y el intercambio de gases.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-circulation","stage":"primaria","subject":"Conocimiento del Medio","title":"La circulación sanguínea","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La circulación sanguínea","circulacion sanguinea","aparato circulatorio","corazon y sangre"],"explanation":"El corazón impulsa la sangre por vasos sanguíneos. Las arterias llevan sangre desde el corazón; las venas la devuelven hacia él. Los capilares permiten intercambios con los tejidos. Arteria no significa siempre sangre rica en oxígeno.","simpler":"Piensa en una red de transporte impulsada por el corazón: salen arterias, vuelven venas y hay intercambios en capilares.","example":"La arteria pulmonar lleva sangre del corazón a los pulmones aunque sea pobre en oxígeno respecto a la sangre que regresa de ellos.","why":"La circulación coordina transporte e intercambio; el nombre del vaso depende de su conexión con el corazón.","misconception":"Arteria y vena se definen por el recorrido, no simplemente por el oxígeno.","hints":["Clasifica los vasos por el sentido respecto al corazón.","Piensa en una red de transporte impulsada por el corazón: salen arterias, vuelven venas y hay intercambios en capilares.","La arteria pulmonar lleva sangre del corazón a los pulmones aunque sea pobre en oxígeno respecto a la sangre que regresa de ellos."],"quiz":[{"id":"p-circulation:q0","question":"Una arteria lleva sangre…","options":["Desde el corazón","Siempre hacia el corazón","Solo al estómago"],"answer":"A","hint":"Clasifica los vasos por el sentido respecto al corazón.","level":1},{"id":"p-circulation:q1","question":"Los capilares permiten principalmente…","options":["Masticar","Intercambios con tejidos","Mover el aire de la tráquea"],"answer":"B","hint":"Clasifica los vasos por el sentido respecto al corazón.","level":2},{"id":"p-circulation:q2","question":"¿Todas las arterias llevan sangre rica en oxígeno?","options":["Sí","Solo las pequeñas","No"],"answer":"C","hint":"Clasifica los vasos por el sentido respecto al corazón.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-solar","stage":"primaria","subject":"Conocimiento del Medio","title":"El sistema solar","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El sistema solar","sistema solar","planetas del sistema solar"],"explanation":"El sistema solar incluye el Sol y los cuerpos ligados gravitatoriamente a él, como planetas, planetas enanos, asteroides y cometas. El Sol es una estrella. La Tierra es un planeta y la Luna es su satélite natural.","simpler":"El Sol es la estrella de nuestro sistema. Los planetas, incluida la Tierra, se mueven en órbitas alrededor de él.","example":"La Tierra orbita el Sol y la Luna orbita la Tierra mientras ambos se desplazan por el sistema solar. La Luna no emite luz visible como una estrella: refleja luz solar.","why":"Las clasificaciones describen características físicas y órbitas; el brillo aparente por sí solo no basta para distinguir los cuerpos.","misconception":"La Luna no es una estrella y el Sol no es un planeta.","hints":["Distingue estrella, planeta y satélite por sus características y relaciones.","El Sol es la estrella de nuestro sistema. Los planetas, incluida la Tierra, se mueven en órbitas alrededor de él.","La Tierra orbita el Sol y la Luna orbita la Tierra mientras ambos se desplazan por el sistema solar. La Luna no emite luz visible como una estrella: refleja luz solar."],"quiz":[{"id":"p-solar:q0","question":"El Sol es…","options":["Un satélite","Un planeta rocoso","Una estrella"],"answer":"C","hint":"Distingue estrella, planeta y satélite por sus características y relaciones.","level":1},{"id":"p-solar:q1","question":"La Luna es principalmente…","options":["Un satélite natural de la Tierra","Una estrella","El centro del sistema solar"],"answer":"A","hint":"Distingue estrella, planeta y satélite por sus características y relaciones.","level":2},{"id":"p-solar:q2","question":"La luz visible que vemos de la Luna procede sobre todo de…","options":["Una bombilla interna","La luz solar reflejada","Los océanos terrestres"],"answer":"B","hint":"Distingue estrella, planeta y satélite por sus características y relaciones.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-earth-motions","stage":"primaria","subject":"Conocimiento del Medio","title":"Rotación y traslación de la Tierra","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Rotación y traslación de la Tierra","rotacion y traslacion","movimientos de la tierra","dia noche y estaciones"],"explanation":"La rotación de la Tierra produce la alternancia habitual de día y noche. Su traslación alrededor del Sol dura aproximadamente un año. Las estaciones se deben principalmente a la inclinación del eje terrestre junto con esa traslación, no a estar simplemente más cerca del Sol.","simpler":"La Tierra gira sobre sí misma y también alrededor del Sol. Su eje inclinado hace que cambie la iluminación a lo largo del año.","example":"Cuando un hemisferio está inclinado hacia el Sol recibe luz más directa y días más largos. Por eso las estaciones son opuestas entre los dos hemisferios.","why":"La inclinación cambia el ángulo de llegada de la luz y la duración del día en cada hemisferio.","misconception":"El verano no ocurre porque toda la Tierra esté simplemente más cerca del Sol.","hints":["Separa el giro diario del recorrido anual y observa la inclinación.","La Tierra gira sobre sí misma y también alrededor del Sol. Su eje inclinado hace que cambie la iluminación a lo largo del año.","Cuando un hemisferio está inclinado hacia el Sol recibe luz más directa y días más largos. Por eso las estaciones son opuestas entre los dos hemisferios."],"quiz":[{"id":"p-earth-motions:q0","question":"El día y la noche se relacionan principalmente con…","options":["La rotación","La fotosíntesis","Las mareas"],"answer":"A","hint":"Separa el giro diario del recorrido anual y observa la inclinación.","level":1},{"id":"p-earth-motions:q1","question":"La traslación terrestre dura aproximadamente…","options":["Una hora","Un año","Una semana"],"answer":"B","hint":"Separa el giro diario del recorrido anual y observa la inclinación.","level":2},{"id":"p-earth-motions:q2","question":"Las estaciones se explican principalmente por…","options":["La distancia al Sol solamente","Las nubes solamente","La inclinación del eje y la traslación"],"answer":"C","hint":"Separa el giro diario del recorrido anual y observa la inclinación.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-mixtures","stage":"primaria","subject":"Conocimiento del Medio","title":"Mezclas y separación","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Mezclas y separación","mezclas","separacion de mezclas","filtracion"],"explanation":"Una mezcla reúne sustancias sin que todas se transformen necesariamente en otras nuevas. Elegimos cómo separarlas según sus propiedades. La filtración retiene partículas insolubles suficientemente grandes; no separa la sal ya disuelta en agua con un filtro ordinario.","simpler":"Piensa qué diferencia a los componentes: tamaño de partículas, densidad o facilidad para evaporarse.","example":"Puedes separar arena del agua con un filtro adecuado. Para recuperar sal disuelta, se puede evaporar el agua bajo condiciones seguras y supervisadas; no se hace con calor sin un adulto.","why":"Una sustancia disuelta permanece distribuida en partículas demasiado pequeñas para quedar retenidas por un filtro ordinario.","misconception":"Disolver sal no significa que haya desaparecido.","hints":["Pregunta si hay partículas sin disolver que el filtro pueda retener.","Piensa qué diferencia a los componentes: tamaño de partículas, densidad o facilidad para evaporarse.","Puedes separar arena del agua con un filtro adecuado. Para recuperar sal disuelta, se puede evaporar el agua bajo condiciones seguras y supervisadas; no se hace con calor sin un adulto."],"quiz":[{"id":"p-mixtures:q0","question":"Un filtro ordinario permite separar mejor…","options":["Sal disuelta del agua","Arena del agua","El agua en oxígeno e hidrógeno"],"answer":"B","hint":"Pregunta si hay partículas sin disolver que el filtro pueda retener.","level":1},{"id":"p-mixtures:q1","question":"Elegimos un método de separación según…","options":["Las propiedades de los componentes","Solo el color del recipiente","El nombre de quien mezcla"],"answer":"A","hint":"Pregunta si hay partículas sin disolver que el filtro pueda retener.","level":2},{"id":"p-mixtures:q2","question":"¿Un filtro de papel quita la sal que está disuelta?","options":["Siempre","Solo si es blanco","No de forma ordinaria"],"answer":"C","hint":"Pregunta si hay partículas sin disolver que el filtro pueda retener.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-relief","stage":"primaria","subject":"Conocimiento del Medio","title":"El relieve terrestre","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["El relieve terrestre","relieve","montanas llanuras y mesetas"],"explanation":"El relieve es el conjunto de formas de la superficie terrestre. Podemos distinguir montañas, llanuras, mesetas y valles. Una meseta es una superficie relativamente llana y elevada respecto a zonas cercanas; llano no significa necesariamente estar al nivel del mar.","simpler":"Observa la forma y la altura relativa. Una zona puede ser llana y estar elevada.","example":"Una meseta combina bastante altura y una superficie relativamente plana. Un valle es una depresión alargada entre zonas más altas.","why":"La forma y la posición relativa describen aspectos diferentes del relieve.","misconception":"Llanura y meseta no se distinguen solo por que una tenga vegetación.","hints":["Distingue la forma de la superficie de su altitud.","Observa la forma y la altura relativa. Una zona puede ser llana y estar elevada.","Una meseta combina bastante altura y una superficie relativamente plana. Un valle es una depresión alargada entre zonas más altas."],"quiz":[{"id":"p-relief:q0","question":"Una meseta es…","options":["Relativamente llana y elevada","Siempre el fondo del mar","Una nube"],"answer":"A","hint":"Distingue la forma de la superficie de su altitud.","level":1},{"id":"p-relief:q1","question":"Un valle suele ser…","options":["Una estrella","Una depresión alargada","Una capa del aire"],"answer":"B","hint":"Distingue la forma de la superficie de su altitud.","level":2},{"id":"p-relief:q2","question":"Una zona llana…","options":["Está siempre al nivel del mar","No puede estar elevada","Puede estar a distinta altitud"],"answer":"C","hint":"Distingue la forma de la superficie de su altitud.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-economy","stage":"primaria","subject":"Conocimiento del Medio","title":"Sectores económicos","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Sectores económicos","sectores economicos","sector primario secundario y terciario"],"explanation":"Una clasificación escolar distingue actividades primarias, que obtienen recursos de la naturaleza; secundarias, que transforman materiales; y terciarias, que prestan servicios. Una cadena de producción puede incluir los tres sectores.","simpler":"Obtener, transformar y prestar servicios son tres formas de agrupar actividades económicas.","example":"Cultivar trigo es una actividad primaria; elaborar pan, secundaria; venderlo o transportarlo, terciaria. Las personas de los tres sectores aportan al proceso.","why":"La clasificación se refiere a la actividad realizada; una cadena económica conecta obtención, transformación y servicios.","misconception":"Un mismo producto pasa por actividades de sectores distintos.","hints":["Mira qué se hace en esa actividad concreta, no solo qué producto aparece.","Obtener, transformar y prestar servicios son tres formas de agrupar actividades económicas.","Cultivar trigo es una actividad primaria; elaborar pan, secundaria; venderlo o transportarlo, terciaria. Las personas de los tres sectores aportan al proceso."],"quiz":[{"id":"p-economy:q0","question":"Cultivar trigo pertenece al sector…","options":["Terciario","Primario","Secundario"],"answer":"B","hint":"Mira qué se hace en esa actividad concreta, no solo qué producto aparece.","level":1},{"id":"p-economy:q1","question":"Elaborar pan a partir de harina se clasifica como…","options":["Secundario","Primario","Ninguno"],"answer":"A","hint":"Mira qué se hace en esa actividad concreta, no solo qué producto aparece.","level":2},{"id":"p-economy:q2","question":"Transportar mercancías es una actividad…","options":["Agrícola siempre","Extractiva","Terciaria"],"answer":"C","hint":"Mira qué se hace en esa actividad concreta, no solo qué producto aparece.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-prehistory","stage":"primaria","subject":"Conocimiento del Medio","title":"La Prehistoria","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["La Prehistoria","prehistoria","paleolitico y neolitico"],"explanation":"Prehistoria es un término usado para estudiar sociedades anteriores a las fuentes escritas de cada región. Se investiga mediante restos materiales. Paleolítico y Neolítico describen grandes procesos diferentes; las fechas y cambios no fueron iguales en todos los lugares.","simpler":"Podemos conocer el pasado a través de herramientas, restos de viviendas y otros hallazgos, aunque no haya textos.","example":"En el Neolítico se extendieron la agricultura y la ganadería en distintas regiones y momentos. No todas las sociedades cambiaron de la misma forma ni al mismo tiempo.","why":"Las etapas son formas de organizar el estudio de procesos; no convierten historias regionales distintas en una sola secuencia idéntica.","misconception":"La aparición de escritura no ocurrió el mismo año en todas las sociedades.","hints":["Distingue una herramienta de estudio del pasado de una fecha universal.","Podemos conocer el pasado a través de herramientas, restos de viviendas y otros hallazgos, aunque no haya textos.","En el Neolítico se extendieron la agricultura y la ganadería en distintas regiones y momentos. No todas las sociedades cambiaron de la misma forma ni al mismo tiempo."],"quiz":[{"id":"p-prehistory:q0","question":"Para estudiar sociedades sin escritura son importantes…","options":["Solo novelas","Solo fotografías actuales","Los restos arqueológicos"],"answer":"C","hint":"Distingue una herramienta de estudio del pasado de una fecha universal.","level":1},{"id":"p-prehistory:q1","question":"En el Neolítico se extendieron…","options":["La agricultura y la ganadería","Las fábricas de vapor","Los teléfonos"],"answer":"A","hint":"Distingue una herramienta de estudio del pasado de una fecha universal.","level":2},{"id":"p-prehistory:q2","question":"¿Los cambios ocurrieron simultáneamente en todas las regiones?","options":["Sí","No","Solo porque lo dice un calendario"],"answer":"B","hint":"Distingue una herramienta de estudio del pasado de una fecha universal.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-there","stage":"primaria","subject":"Lengua Extranjera: Inglés","title":"There is y there are","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["There is y there are","there is y there are","there is","there are"],"explanation":"En inglés, there is y there are permiten indicar que hay algo. En el uso básico empleamos there is con un nombre contable singular y there are con un plural. Para preguntar invertimos: Is there…? o Are there…?","simpler":"Para una cosa: there is. Para varias: there are. Mira el número del sustantivo.","example":"«There is a book on the desk» indica que hay un libro en la mesa. «There are two books» indica que hay dos.","why":"La estructura presenta la existencia de algo; la forma verbal debe concordar con el grupo correspondiente en estos ejemplos básicos.","misconception":"There y they no son la misma palabra ni cumplen la misma función.","hints":["Identifica si hablamos de un elemento singular o de varios.","Para una cosa: there is. Para varias: there are. Mira el número del sustantivo.","«There is a book on the desk» indica que hay un libro en la mesa. «There are two books» indica que hay dos."],"quiz":[{"id":"p-there:q0","question":"Completa: There ___ two cats.","options":["Is","Are","Am"],"answer":"B","hint":"Identifica si hablamos de un elemento singular o de varios.","level":1},{"id":"p-there:q1","question":"Completa: There ___ a chair.","options":["Is","Are","Be"],"answer":"A","hint":"Identifica si hablamos de un elemento singular o de varios.","level":2},{"id":"p-there:q2","question":"¿Qué pregunta está bien formada?","options":["There are two books? únicamente","Is there two books?","Are there two books?"],"answer":"C","hint":"Identifica si hablamos de un elemento singular o de varios.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-have","stage":"primaria","subject":"Lengua Extranjera: Inglés","title":"Have got y has got","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Have got y has got","have got","has got","have got y has got"],"explanation":"Have got puede expresar posesión en inglés. En presente usamos has got con he, she e it; have got con I, you, we y they. En preguntas básicas se antepone have o has al sujeto.","simpler":"Con she usamos has got; con they usamos have got. Primero localiza el sujeto.","example":"«She has got a bike» significa que ella tiene una bicicleta. La pregunta es «Has she got a bike?».","why":"La forma de la pregunta depende de la construcción usada; cambiar de estructura exige ajustar también el auxiliar.","misconception":"No mezcles sin más las estructuras have got y do…have.","hints":["Relaciona cada sujeto con have o has.","Con she usamos has got; con they usamos have got. Primero localiza el sujeto.","«She has got a bike» significa que ella tiene una bicicleta. La pregunta es «Has she got a bike?»."],"quiz":[{"id":"p-have:q0","question":"Completa: She ___ got a bike.","options":["Have","Are","Has"],"answer":"C","hint":"Relaciona cada sujeto con have o has.","level":1},{"id":"p-have:q1","question":"Completa: We ___ got a ball.","options":["Have","Has","Is"],"answer":"A","hint":"Relaciona cada sujeto con have o has.","level":2},{"id":"p-have:q2","question":"La pregunta correspondiente es…","options":["She has got a bike? siempre","Has she got a bike?","Does she has got a bike?"],"answer":"B","hint":"Relaciona cada sujeto con have o has.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-sound","stage":"primaria","subject":"Educación Artística: Música","title":"Cualidades del sonido","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Cualidades del sonido","cualidades del sonido","altura intensidad duracion y timbre"],"explanation":"Podemos describir un sonido por su altura, intensidad, duración y timbre. La altura distingue agudo y grave; la intensidad, fuerte y suave; la duración, largo y corto; el timbre ayuda a distinguir fuentes sonoras. Son propiedades diferentes.","simpler":"Pregunta si el sonido es agudo o grave, fuerte o suave, largo o corto y qué lo produce.","example":"Una flauta y un violín pueden tocar la misma nota con duración parecida y aun así sonar distintos por su timbre.","why":"Las propiedades del sonido permiten describir aspectos distintos; variar uno no obliga a variar todos los demás.","misconception":"Altura e intensidad no son sinónimos.","hints":["No confundas qué tan agudo es con qué tan fuerte se escucha.","Pregunta si el sonido es agudo o grave, fuerte o suave, largo o corto y qué lo produce.","Una flauta y un violín pueden tocar la misma nota con duración parecida y aun así sonar distintos por su timbre."],"quiz":[{"id":"p-sound:q0","question":"Agudo y grave describen…","options":["La altura","La duración","Solo el volumen"],"answer":"A","hint":"No confundas qué tan agudo es con qué tan fuerte se escucha.","level":1},{"id":"p-sound:q1","question":"El timbre ayuda a distinguir…","options":["Solo segundos","Fuentes sonoras","Solo distancias"],"answer":"B","hint":"No confundas qué tan agudo es con qué tan fuerte se escucha.","level":2},{"id":"p-sound:q2","question":"Un sonido puede ser…","options":["Agudo solo si es fuerte","Grave solo si es largo","Agudo y suave a la vez"],"answer":"C","hint":"No confundas qué tan agudo es con qué tan fuerte se escucha.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-colours","stage":"primaria","subject":"Educación Artística: Plástica","title":"Colores cálidos y fríos","grade_min":3,"grade_max":6,"school_years":["3º de Primaria","4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Colores cálidos y fríos","colores calidos y frios","colores calidos","colores frios"],"explanation":"En muchas propuestas artísticas se llaman cálidos a colores asociados a rojos, naranjas y amarillos, y fríos a los relacionados con azules y algunos verdes o violetas. Son asociaciones visuales y culturales, no una medida física de la temperatura del objeto.","simpler":"Un dibujo puede sugerir calidez con naranjas o frescor con azules. La sensación también depende de los colores que lo rodean.","example":"Puedes pintar dos versiones de una misma habitación con colores distintos y comparar qué sensaciones producen, sin afirmar que todas las personas sentirán lo mismo.","why":"El lenguaje del color usa convenciones y relaciones visuales; no permite deducir propiedades físicas sin medirlas.","misconception":"Un objeto azul no está necesariamente más frío que uno rojo.","hints":["Distingue una asociación artística de una temperatura medida con termómetro.","Un dibujo puede sugerir calidez con naranjas o frescor con azules. La sensación también depende de los colores que lo rodean.","Puedes pintar dos versiones de una misma habitación con colores distintos y comparar qué sensaciones producen, sin afirmar que todas las personas sentirán lo mismo."],"quiz":[{"id":"p-colours:q0","question":"En esta clasificación, el naranja suele considerarse…","options":["Frío","Cálido","Transparente"],"answer":"B","hint":"Distingue una asociación artística de una temperatura medida con termómetro.","level":1},{"id":"p-colours:q1","question":"La temperatura cromática es…","options":["Una asociación visual","La temperatura real del papel","Una prueba médica"],"answer":"A","hint":"Distingue una asociación artística de una temperatura medida con termómetro.","level":2},{"id":"p-colours:q2","question":"Las sensaciones ante un color…","options":["Son idénticas en todas las personas","No dependen del contexto","Pueden variar entre personas y contextos"],"answer":"C","hint":"Distingue una asociación artística de una temperatura medida con termómetro.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"p-fact-opinion","stage":"primaria","subject":"Conocimiento del Medio","title":"Hechos y opiniones","grade_min":4,"grade_max":6,"school_years":["4º de Primaria","5º de Primaria","6º de Primaria"],"aliases":["Hechos y opiniones","hechos y opiniones","hecho y opinion"],"explanation":"Una afirmación sobre un hecho pretende describir algo que puede contrastarse con pruebas. Una opinión expresa una valoración o preferencia. Que una frase tenga apariencia de hecho no significa que sea verdadera: hay que comprobarla.","simpler":"«El libro tiene 20 páginas» se puede contar. «Es el mejor libro» expresa una valoración.","example":"En «La biblioteca abre a las nueve y es mi lugar favorito», la hora debe verificarse en una fuente actual; la preferencia pertenece a quien habla.","why":"Distinguir la intención de una afirmación es el primer paso; después evaluamos la calidad de las pruebas disponibles.","misconception":"Una opinión muy repetida no se convierte por eso en un hecho demostrado.","hints":["Pregunta qué pruebas podrían confirmar la frase y si expresa una preferencia.","«El libro tiene 20 páginas» se puede contar. «Es el mejor libro» expresa una valoración.","En «La biblioteca abre a las nueve y es mi lugar favorito», la hora debe verificarse en una fuente actual; la preferencia pertenece a quien habla."],"quiz":[{"id":"p-fact-opinion:q0","question":"¿Cuál expresa una preferencia?","options":["La caja mide 10 cm","Me gusta más este cuento","Hay tres mesas"],"answer":"B","hint":"Pregunta qué pruebas podrían confirmar la frase y si expresa una preferencia.","level":1},{"id":"p-fact-opinion:q1","question":"Una afirmación comprobable…","options":["Puede resultar verdadera o falsa al contrastarla","Es verdadera por sonar segura","Nunca necesita pruebas"],"answer":"A","hint":"Pregunta qué pruebas podrían confirmar la frase y si expresa una preferencia.","level":2},{"id":"p-fact-opinion:q2","question":"Para verificar un horario conviene…","options":["Usar solo un recuerdo antiguo","Elegir la hora que nos guste","Consultar una fuente vigente del lugar"],"answer":"C","hint":"Pregunta qué pruebas podrían confirmar la frase y si expresa una preferencia.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-3296","curriculum_source_key":"BOE-A-2022-3296","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-systems","stage":"eso","subject":"Matemáticas","title":"Sistemas de dos ecuaciones","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Sistemas de dos ecuaciones","sistemas de ecuaciones","sistemas de dos ecuaciones","sustitucion en sistemas"],"explanation":"Resolver un sistema es encontrar valores que satisfagan todas sus ecuaciones a la vez. En sustitución despejamos una incógnita, la reemplazamos en la otra ecuación y comprobamos la pareja obtenida en ambas. Un sistema puede tener una, ninguna o infinitas soluciones.","simpler":"La solución tiene que cumplir dos condiciones al mismo tiempo, no solo una.","example":"En x + y = 7 y x − y = 1, al sumar obtenemos 2x = 8; así x = 4 e y = 3. Se verifica: 4 + 3 = 7 y 4 − 3 = 1.","why":"Cada ecuación impone una restricción; la solución pertenece a la intersección de los conjuntos que las cumplen.","misconception":"Cumplir una ecuación no basta para resolver el sistema.","hints":["Sustituye la pareja en cada ecuación por separado.","La solución tiene que cumplir dos condiciones al mismo tiempo, no solo una.","En x + y = 7 y x − y = 1, al sumar obtenemos 2x = 8; así x = 4 e y = 3. Se verifica: 4 + 3 = 7 y 4 − 3 = 1."],"quiz":[{"id":"e-systems:q0","question":"¿Qué pareja resuelve el sistema del ejemplo?","options":["x = 4, y = 3","x = 3, y = 4","x = 7, y = 1"],"answer":"A","hint":"Sustituye la pareja en cada ecuación por separado.","level":1},{"id":"e-systems:q1","question":"Una solución debe cumplir…","options":["Solo la primera ecuación","Las dos ecuaciones","Solo la que resulte más fácil"],"answer":"B","hint":"Sustituye la pareja en cada ecuación por separado.","level":2},{"id":"e-systems:q2","question":"Un sistema puede tener…","options":["Siempre una sola solución","Siempre dos soluciones","Una, ninguna o infinitas soluciones según el caso"],"answer":"C","hint":"Sustituye la pareja en cada ecuación por separado.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-quadratic","stage":"eso","subject":"Matemáticas","title":"Ecuaciones de segundo grado","grade_min":3,"grade_max":4,"school_years":["3º de ESO","4º de ESO"],"aliases":["Ecuaciones de segundo grado","ecuaciones de segundo grado","ecuacion cuadratica"],"explanation":"Una ecuación de segundo grado puede escribirse ax² + bx + c = 0 con a distinto de cero. Para resolverla usamos factorización u otros métodos. El discriminante b² − 4ac indica si hay dos, una doble o ninguna raíz real.","simpler":"Busca valores de x que hagan cero toda la expresión, no solo una parte.","example":"x² − 5x + 6 = 0 se factoriza como (x − 2)(x − 3) = 0. Sus soluciones son x = 2 y x = 3.","why":"Elevar al cuadrado elimina la diferencia de signo; por eso comprobar y considerar todas las raíces es esencial.","misconception":"x² = 9 tiene dos raíces reales: 3 y −3; no olvides la negativa.","hints":["Si un producto es cero, alguno de sus factores debe ser cero.","Busca valores de x que hagan cero toda la expresión, no solo una parte.","x² − 5x + 6 = 0 se factoriza como (x − 2)(x − 3) = 0. Sus soluciones son x = 2 y x = 3."],"quiz":[{"id":"e-quadratic:q0","question":"Las soluciones del ejemplo son…","options":["5 y 6","2 y 3","−2 y −3"],"answer":"B","hint":"Si un producto es cero, alguno de sus factores debe ser cero.","level":1},{"id":"e-quadratic:q1","question":"Para que sea de segundo grado, a debe ser…","options":["Distinto de cero","Siempre uno","Cero"],"answer":"A","hint":"Si un producto es cero, alguno de sus factores debe ser cero.","level":2},{"id":"e-quadratic:q2","question":"Si el discriminante es negativo, no hay…","options":["Coeficientes","Ecuación","Raíces reales"],"answer":"C","hint":"Si un producto es cero, alguno de sus factores debe ser cero.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-inequality","stage":"eso","subject":"Matemáticas","title":"Inecuaciones lineales","grade_min":3,"grade_max":4,"school_years":["3º de ESO","4º de ESO"],"aliases":["Inecuaciones lineales","inecuaciones","inecuaciones lineales","desigualdades lineales"],"explanation":"Una inecuación pide los valores que hacen verdadera una desigualdad. Al sumar lo mismo en ambos miembros se conserva su sentido. Al multiplicar o dividir por un número negativo, el signo de desigualdad se invierte.","simpler":"Resuelves una condición, no necesariamente un único número. Cuidado al dividir por un negativo.","example":"En −2x > 6, dividimos entre −2 y cambiamos el sentido: x < −3. El valor −4 cumple la desigualdad original.","why":"Multiplicar por un negativo invierte el orden en la recta numérica; de ahí el cambio de signo relacional.","misconception":"El extremo no se incluye en una desigualdad estricta como menor que.","hints":["Comprueba un valor del intervalo en la desigualdad original.","Resuelves una condición, no necesariamente un único número. Cuidado al dividir por un negativo.","En −2x > 6, dividimos entre −2 y cambiamos el sentido: x < −3. El valor −4 cumple la desigualdad original."],"quiz":[{"id":"e-inequality:q0","question":"La solución de −2x > 6 es…","options":["x > −3","x > 3","x < −3"],"answer":"C","hint":"Comprueba un valor del intervalo en la desigualdad original.","level":1},{"id":"e-inequality:q1","question":"Al dividir una desigualdad por un negativo hay que…","options":["Invertir su sentido","Dejar siempre el signo igual","Borrar la incógnita"],"answer":"A","hint":"Comprueba un valor del intervalo en la desigualdad original.","level":2},{"id":"e-inequality:q2","question":"¿Qué valor cumple x < −3?","options":["0","−4","−3"],"answer":"B","hint":"Comprueba un valor del intervalo en la desigualdad original.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-trig","stage":"eso","subject":"Matemáticas","title":"Razones trigonométricas","grade_min":4,"grade_max":4,"school_years":["4º de ESO"],"aliases":["Razones trigonométricas","razones trigonometricas","seno coseno y tangente","trigonometria en triangulos rectangulos"],"explanation":"En un triángulo rectángulo, respecto a un ángulo agudo, seno = cateto opuesto/hipotenusa; coseno = cateto adyacente/hipotenusa; tangente = opuesto/adyacente. Primero identifica el ángulo y los lados correspondientes.","simpler":"La razón cambia según qué lado esté enfrente del ángulo elegido. La hipotenusa está frente al ángulo recto.","example":"En un triángulo de lados 3, 4 y 5, para el ángulo opuesto al lado 3: seno = 3/5, coseno = 4/5 y tangente = 3/4.","why":"Los triángulos rectángulos semejantes conservan las razones entre lados, lo que permite asociarlas al ángulo.","misconception":"Opuesto y adyacente dependen del ángulo; la hipotenusa no cambia al elegir otro ángulo agudo.","hints":["Marca el ángulo de referencia antes de nombrar los catetos.","La razón cambia según qué lado esté enfrente del ángulo elegido. La hipotenusa está frente al ángulo recto.","En un triángulo de lados 3, 4 y 5, para el ángulo opuesto al lado 3: seno = 3/5, coseno = 4/5 y tangente = 3/4."],"quiz":[{"id":"e-trig:q0","question":"El seno del ángulo del ejemplo es…","options":["3/5","4/5","5/3"],"answer":"A","hint":"Marca el ángulo de referencia antes de nombrar los catetos.","level":1},{"id":"e-trig:q1","question":"La hipotenusa se encuentra frente al ángulo…","options":["Más pequeño siempre","Recto","Elegido al azar"],"answer":"B","hint":"Marca el ángulo de referencia antes de nombrar los catetos.","level":2},{"id":"e-trig:q2","question":"La tangente relaciona…","options":["Hipotenusa y perímetro","Área e hipotenusa","Cateto opuesto y adyacente"],"answer":"C","hint":"Marca el ángulo de referencia antes de nombrar los catetos.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-similarity","stage":"eso","subject":"Matemáticas","title":"Figuras semejantes","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Figuras semejantes","semejanza","figuras semejantes","razon de semejanza"],"explanation":"Dos figuras semejantes conservan la forma: sus ángulos correspondientes son iguales y sus longitudes correspondientes están en la misma proporción. Si la razón lineal es k, las áreas correspondientes varían con k².","simpler":"Ampliar una figura sin deformarla multiplica todas sus longitudes por el mismo factor.","example":"Un rectángulo de 2 por 3 y otro de 4 por 6 son semejantes con razón 2. Sus áreas son 6 y 24: la segunda es cuatro veces la primera.","why":"El área combina dos dimensiones; si ambas se multiplican por k, su producto se multiplica por k².","misconception":"Duplicar los lados no duplica el área: la cuadruplica.","hints":["Distingue factores de longitud y de superficie.","Ampliar una figura sin deformarla multiplica todas sus longitudes por el mismo factor.","Un rectángulo de 2 por 3 y otro de 4 por 6 son semejantes con razón 2. Sus áreas son 6 y 24: la segunda es cuatro veces la primera."],"quiz":[{"id":"e-similarity:q0","question":"La razón lineal del ejemplo es…","options":["4","2","6"],"answer":"B","hint":"Distingue factores de longitud y de superficie.","level":1},{"id":"e-similarity:q1","question":"Al duplicar todas las longitudes, el área se multiplica por…","options":["4","2","8"],"answer":"A","hint":"Distingue factores de longitud y de superficie.","level":2},{"id":"e-similarity:q2","question":"Para conservar semejanza debemos…","options":["Cambiar solo un lado","Conservar únicamente el perímetro","Multiplicar longitudes correspondientes por un mismo factor"],"answer":"C","hint":"Distingue factores de longitud y de superficie.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-median","stage":"eso","subject":"Matemáticas","title":"Mediana y moda","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Mediana y moda","mediana y moda","mediana","moda estadistica"],"explanation":"La mediana ocupa el centro de los datos ordenados; si hay un número par de datos numéricos, se toma la media de los dos centrales. La moda es un valor de frecuencia máxima. Un conjunto puede tener varias modas.","simpler":"Ordena antes de buscar el centro. Para la moda, cuenta cuántas veces aparece cada valor.","example":"En 2, 3, 3, 8 y 9, la mediana es 3 y la moda también es 3. En 2, 4, 6 y 8, la mediana es (4 + 6)/2 = 5.","why":"Cada medida resume un aspecto del conjunto; valores extremos afectan a la media de manera distinta que a la mediana.","misconception":"Media, mediana y moda son medidas distintas y no tienen por qué coincidir.","hints":["No confundas posición central con frecuencia.","Ordena antes de buscar el centro. Para la moda, cuenta cuántas veces aparece cada valor.","En 2, 3, 3, 8 y 9, la mediana es 3 y la moda también es 3. En 2, 4, 6 y 8, la mediana es (4 + 6)/2 = 5."],"quiz":[{"id":"e-median:q0","question":"La mediana de 2, 4, 6 y 8 es…","options":["4","6","5"],"answer":"C","hint":"No confundas posición central con frecuencia.","level":1},{"id":"e-median:q1","question":"Antes de localizar la mediana debemos…","options":["Ordenar los datos","Eliminar todos los repetidos","Sumar solo los extremos"],"answer":"A","hint":"No confundas posición central con frecuencia.","level":2},{"id":"e-median:q2","question":"La moda es…","options":["Siempre el valor central","Un valor de máxima frecuencia","Siempre el mayor dato"],"answer":"B","hint":"No confundas posición central con frecuencia.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-mitosis","stage":"eso","subject":"Biología y Geología","title":"La mitosis","grade_min":3,"grade_max":4,"school_years":["3º de ESO","4º de ESO"],"aliases":["La mitosis","mitosis","division mitotica"],"explanation":"La mitosis reparte los cromosomas previamente duplicados entre dos núcleos hijos. Normalmente, seguida de citocinesis, produce dos células con el mismo número cromosómico que la célula de partida. No debe confundirse con la meiosis.","simpler":"Primero se copia el ADN y luego la mitosis organiza su reparto. Copiar y repartir son etapas distintas.","example":"Una célula somática humana con 46 cromosomas puede originar, tras mitosis y citocinesis normales, dos células con 46 cromosomas cada una.","why":"El reparto equilibrado conserva la dotación cromosómica mientras permite crecimiento y renovación de muchos tejidos.","misconception":"Duplicar ADN no significa que cada célula hija normal acabe con el doble de cromosomas.","hints":["Separa duplicación del ADN, reparto nuclear y división del citoplasma.","Primero se copia el ADN y luego la mitosis organiza su reparto. Copiar y repartir son etapas distintas.","Una célula somática humana con 46 cromosomas puede originar, tras mitosis y citocinesis normales, dos células con 46 cromosomas cada una."],"quiz":[{"id":"e-mitosis:q0","question":"Tras una mitosis normal, el número cromosómico por núcleo hijo…","options":["Se conserva","Se reduce siempre a la mitad","Se multiplica por cuatro"],"answer":"A","hint":"Separa duplicación del ADN, reparto nuclear y división del citoplasma.","level":1},{"id":"e-mitosis:q1","question":"La copia del ADN ocurre normalmente…","options":["Después de repartirse sin más","Antes de la mitosis, en interfase","Solo en el último segundo"],"answer":"B","hint":"Separa duplicación del ADN, reparto nuclear y división del citoplasma.","level":2},{"id":"e-mitosis:q2","question":"La citocinesis consiste en…","options":["Crear todos los genes","Duplicar necesariamente los cromosomas","Dividir el citoplasma celular"],"answer":"C","hint":"Separa duplicación del ADN, reparto nuclear y división del citoplasma.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-mendel","stage":"eso","subject":"Biología y Geología","title":"Herencia mendeliana sencilla","grade_min":4,"grade_max":4,"school_years":["4º de ESO"],"aliases":["Herencia mendeliana sencilla","herencia mendeliana","leyes de mendel","dominante y recesivo"],"explanation":"En un modelo mendeliano sencillo, un gen tiene variantes llamadas alelos. Dominante describe qué alelo se expresa en el heterocigoto para el rasgo estudiado; no significa mejor, más frecuente ni más fuerte. Muchos rasgos no siguen este modelo simple.","simpler":"Usa letras para representar alelos, pero recuerda que es un modelo concreto y no explica por sí solo todos los rasgos.","example":"En Aa × Aa, con dominancia completa de A, las combinaciones esperadas son AA, Aa, Aa y aa. La probabilidad de aa es 1/4 en cada descendiente, bajo las condiciones del modelo.","why":"Las probabilidades describen resultados esperables a gran escala bajo ciertas condiciones, no un cupo que deba cumplirse en cada grupo pequeño.","misconception":"Una probabilidad de 1/4 no garantiza un resultado concreto en cuatro nacimientos.","hints":["Dibuja las combinaciones posibles de los gametos y cuenta las equiprobables.","Usa letras para representar alelos, pero recuerda que es un modelo concreto y no explica por sí solo todos los rasgos.","En Aa × Aa, con dominancia completa de A, las combinaciones esperadas son AA, Aa, Aa y aa. La probabilidad de aa es 1/4 en cada descendiente, bajo las condiciones del modelo."],"quiz":[{"id":"e-mendel:q0","question":"En el cruce del ejemplo, la probabilidad de aa es…","options":["1/2","1/4","3/4"],"answer":"B","hint":"Dibuja las combinaciones posibles de los gametos y cuenta las equiprobables.","level":1},{"id":"e-mendel:q1","question":"Dominante significa aquí…","options":["Que se expresa en el heterocigoto","Que siempre es más frecuente","Que es mejor biológicamente"],"answer":"A","hint":"Dibuja las combinaciones posibles de los gametos y cuenta las equiprobables.","level":2},{"id":"e-mendel:q2","question":"Estas proporciones…","options":["Obligan a que cada familia de cuatro tenga una persona aa","Explican todos los rasgos","Son probabilidades del modelo, no un reparto obligatorio en familias pequeñas"],"answer":"C","hint":"Dibuja las combinaciones posibles de los gametos y cuenta las equiprobables.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-motion","stage":"eso","subject":"Física y Química","title":"Velocidad y aceleración","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Velocidad y aceleración","velocidad y aceleracion","aceleracion","velocidad media"],"explanation":"La velocidad incluye rapidez y dirección; la aceleración mide cómo cambia la velocidad con el tiempo. Puede haber aceleración aunque la rapidez sea constante, si cambia la dirección. En un movimiento rectilíneo uniforme la velocidad es constante y la aceleración es cero.","simpler":"Ir rápido no es lo mismo que acelerar. Acelerar significa cambiar la velocidad.","example":"En línea recta, pasar de 2 m/s a 8 m/s en 3 s da una aceleración media de (8 − 2)/3 = 2 m/s².","why":"La velocidad es vectorial: cambiar su dirección también la modifica, aunque su módulo permanezca constante.","misconception":"Rapidez elevada y aceleración elevada no significan lo mismo.","hints":["Calcula el cambio de velocidad y divídelo entre el tiempo transcurrido.","Ir rápido no es lo mismo que acelerar. Acelerar significa cambiar la velocidad.","En línea recta, pasar de 2 m/s a 8 m/s en 3 s da una aceleración media de (8 − 2)/3 = 2 m/s²."],"quiz":[{"id":"e-motion:q0","question":"La aceleración media del ejemplo es…","options":["6 m/s²","3 m/s²","2 m/s²"],"answer":"C","hint":"Calcula el cambio de velocidad y divídelo entre el tiempo transcurrido.","level":1},{"id":"e-motion:q1","question":"Si cambia la dirección aunque no cambie la rapidez…","options":["Puede haber aceleración","La velocidad es idéntica","No hay movimiento"],"answer":"A","hint":"Calcula el cambio de velocidad y divídelo entre el tiempo transcurrido.","level":2},{"id":"e-motion:q2","question":"En movimiento rectilíneo uniforme, la aceleración es…","options":["Siempre 1 m/s²","Cero","Igual a la distancia"],"answer":"B","hint":"Calcula el cambio de velocidad y divídelo entre el tiempo transcurrido.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-electric","stage":"eso","subject":"Física y Química","title":"Corriente, tensión y resistencia","grade_min":3,"grade_max":4,"school_years":["3º de ESO","4º de ESO"],"aliases":["Corriente, tensión y resistencia","corriente tension y resistencia","electricidad basica","ley de ohm"],"explanation":"La corriente mide el paso de carga por unidad de tiempo; la tensión se relaciona con la energía por carga entre dos puntos; la resistencia limita la corriente en un elemento. Para un conductor óhmico bajo condiciones adecuadas, V = I·R. Solo trabajamos con circuitos escolares seguros, nunca con enchufes domésticos.","simpler":"En una resistencia óhmica, conocer tensión y resistencia permite calcular la corriente: I = V/R.","example":"Con 6 V y una resistencia óhmica de 3 Ω, la corriente es 2 A. Es un cálculo teórico, no una instrucción para manipular instalaciones.","why":"La ley de Ohm describe una relación entre magnitudes bajo ciertas condiciones, no una identidad aplicable a cualquier componente.","misconception":"Tensión y corriente no son la misma magnitud.","hints":["Escribe la relación V = I·R y conserva las unidades.","En una resistencia óhmica, conocer tensión y resistencia permite calcular la corriente: I = V/R.","Con 6 V y una resistencia óhmica de 3 Ω, la corriente es 2 A. Es un cálculo teórico, no una instrucción para manipular instalaciones."],"quiz":[{"id":"e-electric:q0","question":"La corriente del ejemplo es…","options":["2 A","18 A","0,5 A"],"answer":"A","hint":"Escribe la relación V = I·R y conserva las unidades.","level":1},{"id":"e-electric:q1","question":"La resistencia se mide en…","options":["Voltios","Ohmios","Segundos"],"answer":"B","hint":"Escribe la relación V = I·R y conserva las unidades.","level":2},{"id":"e-electric:q2","question":"¿Se debe practicar conectando cables a un enchufe doméstico?","options":["Sí","Solo con las manos secas","No"],"answer":"C","hint":"Escribe la relación V = I·R y conserva las unidades.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-solution","stage":"eso","subject":"Física y Química","title":"Disoluciones y concentración","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Disoluciones y concentración","disoluciones","concentracion en masa","soluto y disolvente"],"explanation":"Una disolución es una mezcla homogénea de componentes. La concentración en masa puede expresarse como masa de soluto dividida entre volumen de disolución, por ejemplo en g/L. El volumen de disolución no siempre es la suma exacta de los volúmenes iniciales.","simpler":"Indica cuánto soluto hay por cada volumen de mezcla final, usando unidades claras.","example":"Si 10 g de soluto están en 2 L de disolución, la concentración en masa es 5 g/L. Si añades disolvente sin perder soluto, esa concentración disminuye.","why":"La misma masa puede distribuirse en volúmenes distintos; la concentración compara cantidad de soluto con una cantidad de disolución.","misconception":"Cantidad total de soluto y concentración no son sinónimos.","hints":["Comprueba si el problema proporciona masa de soluto y volumen de mezcla final.","Indica cuánto soluto hay por cada volumen de mezcla final, usando unidades claras.","Si 10 g de soluto están en 2 L de disolución, la concentración en masa es 5 g/L. Si añades disolvente sin perder soluto, esa concentración disminuye."],"quiz":[{"id":"e-solution:q0","question":"La concentración del ejemplo es…","options":["20 g/L","5 g/L","0,2 g/L"],"answer":"B","hint":"Comprueba si el problema proporciona masa de soluto y volumen de mezcla final.","level":1},{"id":"e-solution:q1","question":"Al añadir disolvente sin perder soluto, la concentración en masa…","options":["Disminuye","Aumenta siempre","Se vuelve cero siempre"],"answer":"A","hint":"Comprueba si el problema proporciona masa de soluto y volumen de mezcla final.","level":2},{"id":"e-solution:q2","question":"En g/L, el denominador es el volumen de…","options":["Solo soluto","Cualquier recipiente vacío","La disolución final"],"answer":"C","hint":"Comprueba si el problema proporciona masa de soluto y volumen de mezcla final.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-bond","stage":"eso","subject":"Física y Química","title":"Enlaces químicos","grade_min":3,"grade_max":4,"school_years":["3º de ESO","4º de ESO"],"aliases":["Enlaces químicos","enlace quimico","enlaces ionico covalente y metalico"],"explanation":"Los enlaces químicos describen interacciones que mantienen unidos átomos o iones en estructuras. En el modelo básico, el covalente comparte densidad electrónica; el iónico implica atracción entre iones opuestos; el metálico se describe con electrones deslocalizados. No todas las sustancias forman moléculas discretas.","simpler":"Distingue compartir electrones, atraer iones de carga opuesta y deslocalizar electrones en un metal.","example":"El agua forma moléculas con enlaces covalentes. El cloruro de sodio sólido forma una red de iones, no una colección de pequeñas moléculas independientes de sal.","why":"Las estructuras y fuerzas entre partículas ayudan a explicar propiedades macroscópicas como conductividad y temperatura de fusión.","misconception":"No toda fórmula química representa una molécula aislada.","hints":["Relaciona el tipo de interacción con la estructura resultante.","Distingue compartir electrones, atraer iones de carga opuesta y deslocalizar electrones en un metal.","El agua forma moléculas con enlaces covalentes. El cloruro de sodio sólido forma una red de iones, no una colección de pequeñas moléculas independientes de sal."],"quiz":[{"id":"e-bond:q0","question":"En un enlace iónico actúan principalmente…","options":["Imanes macroscópicos","Solo neutrones","Atracciones entre iones opuestos"],"answer":"C","hint":"Relaciona el tipo de interacción con la estructura resultante.","level":1},{"id":"e-bond:q1","question":"El agua presenta enlaces…","options":["Covalentes","Metálicos","Iónicos entre todas sus moléculas"],"answer":"A","hint":"Relaciona el tipo de interacción con la estructura resultante.","level":2},{"id":"e-bond:q2","question":"El NaCl sólido se describe mejor como…","options":["Un único átomo","Una red iónica","Un gas molecular siempre"],"answer":"B","hint":"Relaciona el tipo de interacción con la estructura resultante.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-renaissance","stage":"eso","subject":"Geografía e Historia","title":"El Renacimiento","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["El Renacimiento","renacimiento","humanismo renacentista"],"explanation":"El Renacimiento fue un conjunto de transformaciones culturales y artísticas desarrollado en Europa, con importantes focos italianos, entre los siglos XIV y XVI aproximadamente. Recuperó y reinterpretó modelos clásicos. No supuso que todo el mundo europeo cambiara de forma idéntica o dejara de ser religioso.","simpler":"Se estudiaron textos y formas de la Antigüedad para crear nuevas propuestas, no simplemente copiarlas.","example":"El interés por la proporción, el estudio del cuerpo y la perspectiva influyó en distintas artes. El humanismo promovió el estudio crítico de textos y lenguas clásicas.","why":"Los periodos históricos agrupan tendencias; conviven novedades, continuidades y diferencias regionales.","misconception":"Renacimiento no significa ausencia de religión ni un cambio simultáneo de toda la sociedad.","hints":["Sitúa el proceso cultural sin convertirlo en una ruptura total y uniforme.","Se estudiaron textos y formas de la Antigüedad para crear nuevas propuestas, no simplemente copiarlas.","El interés por la proporción, el estudio del cuerpo y la perspectiva influyó en distintas artes. El humanismo promovió el estudio crítico de textos y lenguas clásicas."],"quiz":[{"id":"e-renaissance:q0","question":"El Renacimiento recuperó especialmente modelos de…","options":["La Antigüedad clásica","La Revolución Industrial","La informática"],"answer":"A","hint":"Sitúa el proceso cultural sin convertirlo en una ruptura total y uniforme.","level":1},{"id":"e-renaissance:q1","question":"El humanismo prestó atención al estudio de…","options":["Solo máquinas de vapor","Textos y lenguas clásicas","Solo estadísticas actuales"],"answer":"B","hint":"Sitúa el proceso cultural sin convertirlo en una ruptura total y uniforme.","level":2},{"id":"e-renaissance:q2","question":"¿Las transformaciones fueron idénticas en toda Europa?","options":["Sí","Solo en un día concreto","No"],"answer":"C","hint":"Sitúa el proceso cultural sin convertirlo en una ruptura total y uniforme.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-enlightenment","stage":"eso","subject":"Geografía e Historia","title":"La Ilustración","grade_min":3,"grade_max":4,"school_years":["3º de ESO","4º de ESO"],"aliases":["La Ilustración","ilustracion","siglo de las luces"],"explanation":"La Ilustración reunió corrientes intelectuales que, especialmente en el siglo XVIII europeo, defendieron el examen racional, la crítica y la difusión del conocimiento. Sus autores no pensaban igual en todo. Influyó en debates políticos y sociales, pero no eliminó por sí sola las desigualdades.","simpler":"La idea central es examinar las afirmaciones con razones y pruebas, en lugar de aceptarlas solo por autoridad.","example":"La Enciclopedia francesa buscó reunir y difundir conocimientos. Distintos ilustrados discutieron sobre educación, tolerancia, leyes y formas de gobierno.","why":"Las ideas influyen en los cambios, pero las estructuras económicas, políticas y sociales no se transforman solo por formularlas.","misconception":"No debe confundirse una propuesta intelectual con su aplicación completa en toda la sociedad.","hints":["Distingue tendencias compartidas de opiniones idénticas.","La idea central es examinar las afirmaciones con razones y pruebas, en lugar de aceptarlas solo por autoridad.","La Enciclopedia francesa buscó reunir y difundir conocimientos. Distintos ilustrados discutieron sobre educación, tolerancia, leyes y formas de gobierno."],"quiz":[{"id":"e-enlightenment:q0","question":"La Ilustración se asocia especialmente con el siglo…","options":["XII","XVIII","XXI"],"answer":"B","hint":"Distingue tendencias compartidas de opiniones idénticas.","level":1},{"id":"e-enlightenment:q1","question":"Una actitud ilustrada característica es…","options":["Examinar críticamente con razones","Aceptar todo sin preguntar","Rechazar cualquier conocimiento"],"answer":"A","hint":"Distingue tendencias compartidas de opiniones idénticas.","level":2},{"id":"e-enlightenment:q2","question":"Los ilustrados…","options":["Coincidían en absolutamente todo","Eran un solo partido moderno","Formaban corrientes diversas"],"answer":"C","hint":"Distingue tendencias compartidas de opiniones idénticas.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-french","stage":"eso","subject":"Geografía e Historia","title":"La Revolución francesa","grade_min":4,"grade_max":4,"school_years":["4º de ESO"],"aliases":["La Revolución francesa","revolucion francesa","revolucion de 1789"],"explanation":"La Revolución francesa comenzó en 1789 y atravesó fases políticas diferentes. Intervinieron crisis financieras, desigualdades y conflictos políticos, junto con nuevas ideas. Cuestionó el Antiguo Régimen, pero sus resultados, derechos y exclusiones deben estudiarse históricamente, no como un cambio simple y uniforme.","simpler":"No fue un solo acontecimiento ni tuvo una única causa. Sigue la cronología y distingue actores e intereses.","example":"La toma de la Bastilla, en julio de 1789, se convirtió en un símbolo. La declaración de derechos de ese año no significó que todas las personas disfrutaran inmediatamente de igualdad efectiva.","why":"La historia exige comparar principios declarados, instituciones y experiencias de grupos sociales distintos.","misconception":"Una revolución no convierte de inmediato todas sus aspiraciones en realidades universales.","hints":["Separa causas, acontecimientos y consecuencias.","No fue un solo acontecimiento ni tuvo una única causa. Sigue la cronología y distingue actores e intereses.","La toma de la Bastilla, en julio de 1789, se convirtió en un símbolo. La declaración de derechos de ese año no significó que todas las personas disfrutaran inmediatamente de igualdad efectiva."],"quiz":[{"id":"e-french:q0","question":"La Revolución francesa comenzó en…","options":["1492","1812","1789"],"answer":"C","hint":"Separa causas, acontecimientos y consecuencias.","level":1},{"id":"e-french:q1","question":"Para explicar sus causas conviene…","options":["Combinar factores políticos, sociales y económicos","Atribuir todo a una sola persona","Ignorar las crisis financieras"],"answer":"A","hint":"Separa causas, acontecimientos y consecuencias.","level":2},{"id":"e-french:q2","question":"Una declaración de derechos…","options":["Garantiza por sí sola igualdad efectiva inmediata","Debe analizarse junto con su aplicación y exclusiones","No tiene importancia histórica"],"answer":"B","hint":"Separa causas, acontecimientos y consecuencias.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-population","stage":"eso","subject":"Geografía e Historia","title":"Cambios de población","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Cambios de población","demografia","crecimiento de poblacion","crecimiento natural y migratorio"],"explanation":"El cambio de población depende de nacimientos, defunciones, inmigración y emigración, entre otros ajustes estadísticos. El saldo natural es nacimientos menos defunciones; el migratorio, inmigración menos emigración. Una tasa requiere además una población de referencia y un periodo.","simpler":"Suma quienes nacen o llegan y resta quienes fallecen o se van durante el mismo periodo.","example":"Si hay 100 nacimientos, 80 defunciones, 30 llegadas y 20 salidas, el cambio por estos componentes es 100 − 80 + 30 − 20 = 30.","why":"El total resulta de componentes diferentes; analizar cada uno evita atribuir un cambio a una sola causa.","misconception":"Una población puede crecer aunque tenga saldo natural negativo si su saldo migratorio lo compensa.","hints":["No mezcles cantidades absolutas con tasas ni periodos distintos.","Suma quienes nacen o llegan y resta quienes fallecen o se van durante el mismo periodo.","Si hay 100 nacimientos, 80 defunciones, 30 llegadas y 20 salidas, el cambio por estos componentes es 100 − 80 + 30 − 20 = 30."],"quiz":[{"id":"e-population:q0","question":"El cambio del ejemplo es…","options":["30 personas","10 personas","230 personas"],"answer":"A","hint":"No mezcles cantidades absolutas con tasas ni periodos distintos.","level":1},{"id":"e-population:q1","question":"El saldo natural es…","options":["Inmigración menos emigración","Nacimientos menos defunciones","Población total dividida entre países"],"answer":"B","hint":"No mezcles cantidades absolutas con tasas ni periodos distintos.","level":2},{"id":"e-population:q2","question":"Para interpretar una tasa necesitamos…","options":["Solo un número aislado","Solo el nombre del lugar","Una referencia poblacional y temporal"],"answer":"C","hint":"No mezcles cantidades absolutas con tasas ni periodos distintos.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-direct-object","stage":"eso","subject":"Lengua Castellana y Literatura","title":"El complemento directo","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["El complemento directo","complemento directo","objeto directo"],"explanation":"El complemento directo completa el significado de muchos verbos transitivos. En español puede sustituirse en muchos casos por lo, la, los o las. Si designa a una persona específica suele llevar a. Una pregunta de significado no sustituye al análisis gramatical.","simpler":"Busca qué complemento se puede sustituir por lo o la manteniendo la estructura de la oración.","example":"En «Lucía lee el libro», el libro es complemento directo: «Lucía lo lee». En «Vi a Marta», a Marta también puede ser directo: «La vi».","why":"Las funciones sintácticas dependen de relaciones estructurales; una misma preposición puede aparecer en funciones distintas.","misconception":"La presencia de a no convierte automáticamente un complemento en indirecto.","hints":["Usa varias pruebas gramaticales y no una sola pregunta intuitiva.","Busca qué complemento se puede sustituir por lo o la manteniendo la estructura de la oración.","En «Lucía lee el libro», el libro es complemento directo: «Lucía lo lee». En «Vi a Marta», a Marta también puede ser directo: «La vi»."],"quiz":[{"id":"e-direct-object:q0","question":"En «Lucía lee el libro», el complemento directo es…","options":["Lucía","El libro","Lee"],"answer":"B","hint":"Usa varias pruebas gramaticales y no una sola pregunta intuitiva.","level":1},{"id":"e-direct-object:q1","question":"La sustitución adecuada es…","options":["Lucía lo lee","Lucía le lee el libro, necesariamente","Lucía allí lee"],"answer":"A","hint":"Usa varias pruebas gramaticales y no una sola pregunta intuitiva.","level":2},{"id":"e-direct-object:q2","question":"¿Un complemento directo puede llevar a?","options":["Nunca","Solo si es un lugar","Sí, en ciertos casos de persona"],"answer":"C","hint":"Usa varias pruebas gramaticales y no una sola pregunta intuitiva.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-subordinate","stage":"eso","subject":"Lengua Castellana y Literatura","title":"Oraciones subordinadas","grade_min":3,"grade_max":4,"school_years":["3º de ESO","4º de ESO"],"aliases":["Oraciones subordinadas","oraciones subordinadas","subordinacion"],"explanation":"Una oración subordinada se integra en una estructura mayor y depende sintácticamente de ella. Puede desempeñar funciones semejantes a un sustantivo, un adjetivo u otros complementos, según el análisis. El número de verbos por sí solo no determina el tipo de relación.","simpler":"Una oración puede ocupar un lugar dentro de otra, como una pieza que cumple una función.","example":"En «Espero que llegues pronto», «que llegues pronto» expresa lo esperado y funciona como complemento directo. Puede compararse con «Espero tu llegada».","why":"La subordinación se reconoce por dependencia y función, no solo por una palabra introductora.","misconception":"Que aparezca que no basta para clasificar automáticamente cualquier construcción.","hints":["Prueba qué función ocupa el segmento dentro de la oración completa.","Una oración puede ocupar un lugar dentro de otra, como una pieza que cumple una función.","En «Espero que llegues pronto», «que llegues pronto» expresa lo esperado y funciona como complemento directo. Puede compararse con «Espero tu llegada»."],"quiz":[{"id":"e-subordinate:q0","question":"En el ejemplo, la subordinada es…","options":["Espero","Pronto","Que llegues pronto"],"answer":"C","hint":"Prueba qué función ocupa el segmento dentro de la oración completa.","level":1},{"id":"e-subordinate:q1","question":"La subordinada del ejemplo expresa…","options":["Lo esperado","Quién espera necesariamente","Un número de personas"],"answer":"A","hint":"Prueba qué función ocupa el segmento dentro de la oración completa.","level":2},{"id":"e-subordinate:q2","question":"Para identificar la relación debemos estudiar…","options":["Solo cuántas letras hay","La función dentro de la estructura mayor","Solo si aparece una coma"],"answer":"B","hint":"Prueba qué función ocupa el segmento dentro de la oración completa.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-text-kinds","stage":"eso","subject":"Lengua Castellana y Literatura","title":"Narración, descripción y exposición","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Narración, descripción y exposición","tipos de texto","narracion descripcion y exposicion","texto expositivo"],"explanation":"Narrar cuenta acontecimientos; describir presenta rasgos; exponer explica información de forma organizada. Un texto puede combinar secuencias diferentes. Para clasificarlo, observa su propósito predominante y las relaciones entre sus partes.","simpler":"Pregunta si el fragmento cuenta qué pasó, muestra cómo es algo o explica un tema.","example":"«Ayer salimos y empezó a llover» narra. «La plaza es amplia y arbolada» describe. Un texto que explica el ciclo del agua es principalmente expositivo.","why":"Los autores combinan recursos según sus objetivos; identificar esa combinación mejora la lectura y la escritura.","misconception":"Las categorías textuales ayudan a analizar, pero no convierten todos los textos en formas puras.","hints":["Busca la finalidad de cada fragmento.","Pregunta si el fragmento cuenta qué pasó, muestra cómo es algo o explica un tema.","«Ayer salimos y empezó a llover» narra. «La plaza es amplia y arbolada» describe. Un texto que explica el ciclo del agua es principalmente expositivo."],"quiz":[{"id":"e-text-kinds:q0","question":"Un texto que explica el ciclo del agua es principalmente…","options":["Expositivo","Narrativo por obligación","Un anuncio siempre"],"answer":"A","hint":"Busca la finalidad de cada fragmento.","level":1},{"id":"e-text-kinds:q1","question":"«La plaza es amplia y arbolada» es una…","options":["Instrucción","Descripción","Demostración algebraica"],"answer":"B","hint":"Busca la finalidad de cada fragmento.","level":2},{"id":"e-text-kinds:q2","question":"Un texto real puede…","options":["Tener solo una clase de secuencia","No tener ninguna intención","Combinar narración, descripción y exposición"],"answer":"C","hint":"Busca la finalidad de cada fragmento.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-past","stage":"eso","subject":"Lengua Extranjera: Inglés","title":"Past simple","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Past simple","past simple","pasado simple en ingles"],"explanation":"El past simple suele situar hechos en un pasado terminado. Los verbos regulares forman el pasado con -ed; los irregulares tienen formas propias. En preguntas y negativas con did o did not, el verbo principal vuelve a su forma base, salvo construcciones diferentes como to be.","simpler":"En «Did she go?», did ya marca el pasado: no añadimos went después.","example":"«She visited Madrid yesterday». Para preguntar: «Did she visit Madrid yesterday?». Para negar: «She did not visit Madrid yesterday».","why":"El auxiliar aporta información gramatical, por lo que el verbo principal no conserva la misma flexión que en la afirmativa.","misconception":"No marques dos veces el pasado en «did + verbo» usando did went.","hints":["Localiza el auxiliar antes de cambiar el verbo principal.","En «Did she go?», did ya marca el pasado: no añadimos went después.","«She visited Madrid yesterday». Para preguntar: «Did she visit Madrid yesterday?». Para negar: «She did not visit Madrid yesterday»."],"quiz":[{"id":"e-past:q0","question":"¿Qué pregunta es correcta?","options":["Did she visited Madrid?","Did she visit Madrid?","Does she visited Madrid?"],"answer":"B","hint":"Localiza el auxiliar antes de cambiar el verbo principal.","level":1},{"id":"e-past:q1","question":"Tras did not usamos normalmente el verbo principal en…","options":["Forma base","Pasado con -ed siempre","Gerundio siempre"],"answer":"A","hint":"Localiza el auxiliar antes de cambiar el verbo principal.","level":2},{"id":"e-past:q2","question":"El pasado de go es…","options":["Goed","Goes","Went"],"answer":"C","hint":"Localiza el auxiliar antes de cambiar el verbo principal.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-perfect","stage":"eso","subject":"Lengua Extranjera: Inglés","title":"Present perfect","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Present perfect","present perfect","have plus participle"],"explanation":"El present perfect se forma con have o has y el participio. Puede relacionar experiencias o procesos pasados con el presente. No equivale en todos los contextos a un único tiempo español. En el contraste básico, un momento pasado terminado como yesterday suele requerir past simple.","simpler":"Usa have o has más participio y pregunta qué relación tiene el hecho con el presente.","example":"«I have lost my keys» puede destacar el resultado actual: no las tengo. «I lost my keys yesterday» sitúa el hecho en un momento pasado terminado.","why":"Los tiempos organizan relaciones temporales y discursivas; el contexto determina qué aspecto del acontecimiento destaca el hablante.","misconception":"No elijas el tiempo verbal traduciendo palabra por palabra desde el español.","hints":["Distingue resultado o experiencia conectada con el presente de un tiempo pasado cerrado.","Usa have o has más participio y pregunta qué relación tiene el hecho con el presente.","«I have lost my keys» puede destacar el resultado actual: no las tengo. «I lost my keys yesterday» sitúa el hecho en un momento pasado terminado."],"quiz":[{"id":"e-perfect:q0","question":"Completa: She ___ finished.","options":["Is","Did","Has"],"answer":"C","hint":"Distingue resultado o experiencia conectada con el presente de un tiempo pasado cerrado.","level":1},{"id":"e-perfect:q1","question":"La estructura básica es…","options":["Have/has más participio","Did más participio siempre","Am más pasado"],"answer":"A","hint":"Distingue resultado o experiencia conectada con el presente de un tiempo pasado cerrado.","level":2},{"id":"e-perfect:q2","question":"En el contraste básico, con yesterday suele usarse…","options":["Present perfect necesariamente","Past simple","Futuro siempre"],"answer":"B","hint":"Distingue resultado o experiencia conectada con el presente de un tiempo pasado cerrado.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-logic","stage":"eso","subject":"Tecnología y Digitalización","title":"Operadores lógicos","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Operadores lógicos","operadores logicos","and or not","logica booleana"],"explanation":"La lógica booleana trabaja con valores verdadero y falso. AND exige que ambas condiciones sean verdaderas; OR inclusivo basta con que al menos una lo sea; NOT invierte el valor. En programación hay que comprobar la definición concreta de cada operador.","simpler":"AND significa que se cumplen las dos; OR inclusivo, alguna o ambas; NOT cambia verdadero por falso y al revés.","example":"Si A es verdadero y B falso: A AND B es falso; A OR B es verdadero; NOT A es falso.","why":"Las tablas de verdad definen el resultado para cada combinación posible y evitan depender de interpretaciones coloquiales ambiguas.","misconception":"El OR inclusivo no excluye el caso en que ambas condiciones se cumplen.","hints":["Construye una pequeña tabla de verdad antes de decidir.","AND significa que se cumplen las dos; OR inclusivo, alguna o ambas; NOT cambia verdadero por falso y al revés.","Si A es verdadero y B falso: A AND B es falso; A OR B es verdadero; NOT A es falso."],"quiz":[{"id":"e-logic:q0","question":"Verdadero AND falso produce…","options":["Falso","Verdadero","Un número obligatorio"],"answer":"A","hint":"Construye una pequeña tabla de verdad antes de decidir.","level":1},{"id":"e-logic:q1","question":"Verdadero OR verdadero, con OR inclusivo, produce…","options":["Falso","Verdadero","Indefinido siempre"],"answer":"B","hint":"Construye una pequeña tabla de verdad antes de decidir.","level":2},{"id":"e-logic:q2","question":"NOT falso produce…","options":["Falso","Cero necesariamente en todos los lenguajes","Verdadero"],"answer":"C","hint":"Construye una pequeña tabla de verdad antes de decidir.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-critical","stage":"eso","subject":"Educación en Valores Cívicos y Éticos","title":"Evaluar una afirmación","grade_min":1,"grade_max":4,"school_years":["1º de ESO","2º de ESO","3º de ESO","4º de ESO"],"aliases":["Evaluar una afirmación","pensamiento critico","evaluar afirmaciones","comprobar una informacion"],"explanation":"Evaluar una afirmación exige identificar qué sostiene, qué pruebas la apoyan y qué límites tienen esas pruebas. Importan la fuente, el método y el contexto. Una persona experta puede aportar razones valiosas, pero ninguna autoridad sustituye por sí sola la evidencia.","simpler":"Pregunta qué prueba podría confirmar o refutar la idea y si realmente está disponible.","example":"Que dos cosas cambien juntas no demuestra que una cause la otra. Podría existir una tercera variable o una coincidencia; hace falta investigar la relación.","why":"El pensamiento crítico compara la fuerza de las pruebas y mantiene conclusiones proporcionales a lo que se sabe.","misconception":"Tener dudas no significa que todas las afirmaciones tengan el mismo respaldo.","hints":["Distingue lo observado de la explicación propuesta.","Pregunta qué prueba podría confirmar o refutar la idea y si realmente está disponible.","Que dos cosas cambien juntas no demuestra que una cause la otra. Podría existir una tercera variable o una coincidencia; hace falta investigar la relación."],"quiz":[{"id":"e-critical:q0","question":"Que dos variables estén correlacionadas…","options":["Demuestra siempre causalidad","No demuestra por sí solo causalidad","Impide cualquier investigación"],"answer":"B","hint":"Distingue lo observado de la explicación propuesta.","level":1},{"id":"e-critical:q1","question":"Una buena evaluación debe examinar…","options":["Pruebas y método","Solo cuántos seguidores hay","Solo si nos gusta la conclusión"],"answer":"A","hint":"Distingue lo observado de la explicación propuesta.","level":2},{"id":"e-critical:q2","question":"Cambiar de opinión ante pruebas mejores puede ser…","options":["Una derrota inevitable","Una señal de que nunca se debe pensar","Una revisión razonada"],"answer":"C","hint":"Distingue lo observado de la explicación propuesta.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"e-scale","stage":"eso","subject":"Educación Plástica, Visual y Audiovisual","title":"Escalas en dibujo técnico","grade_min":2,"grade_max":4,"school_years":["2º de ESO","3º de ESO","4º de ESO"],"aliases":["Escalas en dibujo técnico","escala en dibujo tecnico","escalas de dibujo"],"explanation":"Una escala relaciona longitud representada y longitud real en las mismas unidades. En 1:50, una unidad en el dibujo corresponde a 50 reales: es reducción. En 2:1, el dibujo duplica las longitudes reales: es ampliación. No es una razón entre áreas.","simpler":"Lee siempre dibujo:real y convierte las unidades antes de calcular.","example":"A escala 1:50, un segmento de 4 cm representa 200 cm, es decir, 2 m. A escala 2:1, un objeto de 3 cm se dibuja con 6 cm.","why":"Las dimensiones lineales varían con la escala; las áreas y volúmenes lo hacen con potencias de ese factor.","misconception":"Una escala de longitudes no se aplica directamente al área con el mismo factor.","hints":["Mantén el orden dibujo:real y revisa las unidades.","Lee siempre dibujo:real y convierte las unidades antes de calcular.","A escala 1:50, un segmento de 4 cm representa 200 cm, es decir, 2 m. A escala 2:1, un objeto de 3 cm se dibuja con 6 cm."],"quiz":[{"id":"e-scale:q0","question":"4 cm a escala 1:50 representan…","options":["200 m","50 cm","2 m"],"answer":"C","hint":"Mantén el orden dibujo:real y revisa las unidades.","level":1},{"id":"e-scale:q1","question":"La escala 2:1 indica…","options":["Ampliación","Reducción","Tamaño real"],"answer":"A","hint":"Mantén el orden dibujo:real y revisa las unidades.","level":2},{"id":"e-scale:q2","question":"La escala lineal relaciona…","options":["Áreas sin conversión","Longitudes en unidades compatibles","Pesos"],"answer":"B","hint":"Mantén el orden dibujo:real y revisa las unidades.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-4975","curriculum_source_key":"BOE-A-2022-4975","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-determinant","stage":"bachillerato","subject":"Matemáticas","title":"Determinantes de orden dos","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Determinantes de orden dos","determinantes","determinante de una matriz","determinantes de orden dos"],"explanation":"Para una matriz de orden dos con filas (a,b) y (c,d), el determinante es ad − bc. Es un escalar, no otra matriz. Si es distinto de cero, la matriz es invertible. Conviene conservar el orden de los productos y sus signos.","simpler":"Multiplica la diagonal principal y réstale el producto de la otra diagonal.","example":"Para la matriz con filas (1,2) y (3,4), el determinante es 1·4 − 2·3 = −2. Al ser distinto de cero, existe su inversa.","why":"La anulación del determinante indica dependencia que impide invertir la transformación lineal; un signo negativo no la hace singular.","misconception":"El signo negativo de un determinante no significa que la matriz no tenga inversa.","hints":["Escribe ad − bc antes de sustituir los números.","Multiplica la diagonal principal y réstale el producto de la otra diagonal.","Para la matriz con filas (1,2) y (3,4), el determinante es 1·4 − 2·3 = −2. Al ser distinto de cero, existe su inversa."],"quiz":[{"id":"b-determinant:q0","question":"El determinante del ejemplo es…","options":["−2","2","10"],"answer":"A","hint":"Escribe ad − bc antes de sustituir los números.","level":1},{"id":"b-determinant:q1","question":"Una matriz cuadrada con determinante distinto de cero es…","options":["Siempre diagonal","Invertible","Siempre nula"],"answer":"B","hint":"Escribe ad − bc antes de sustituir los números.","level":2},{"id":"b-determinant:q2","question":"El determinante es…","options":["Siempre una matriz de dos filas","Siempre positivo","Un escalar"],"answer":"C","hint":"Escribe ad − bc antes de sustituir los números.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-log","stage":"bachillerato","subject":"Matemáticas","title":"Los logaritmos","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Los logaritmos","logaritmos","logaritmo"],"explanation":"El logaritmo de x en base a responde a qué exponente hay que elevar a para obtener x: log_a(x) = y equivale a a^y = x. En los reales se exige a > 0, a distinto de 1 y x > 0. Las propiedades de productos no deben confundirse con sumas.","simpler":"Un logaritmo pregunta por un exponente. Piensa en la potencia equivalente.","example":"log_2(8) = 3 porque 2³ = 8. Para x e y positivos, log_a(xy) = log_a(x) + log_a(y); no existe esa misma regla para log_a(x + y).","why":"Las propiedades se derivan de las reglas de exponentes; aplicarlas exige conservar tanto la operación como el dominio.","misconception":"El logaritmo de una suma no se separa como suma de logaritmos.","hints":["Convierte la pregunta en una igualdad de potencias.","Un logaritmo pregunta por un exponente. Piensa en la potencia equivalente.","log_2(8) = 3 porque 2³ = 8. Para x e y positivos, log_a(xy) = log_a(x) + log_a(y); no existe esa misma regla para log_a(x + y)."],"quiz":[{"id":"b-log:q0","question":"log_2(8) vale…","options":["4","3","2"],"answer":"B","hint":"Convierte la pregunta en una igualdad de potencias.","level":1},{"id":"b-log:q1","question":"En logaritmos reales ordinarios, el argumento debe ser…","options":["Positivo","Siempre negativo","Cualquier real sin condiciones"],"answer":"A","hint":"Convierte la pregunta en una igualdad de potencias.","level":2},{"id":"b-log:q2","question":"¿Qué identidad es válida con condiciones adecuadas?","options":["log(x+y)=log(x)+log(y) siempre","log(xy)=log(x)·log(y) siempre","log(xy)=log(x)+log(y)"],"answer":"C","hint":"Convierte la pregunta en una igualdad de potencias.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-binomial","stage":"bachillerato","subject":"Matemáticas","title":"Distribución binomial","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Distribución binomial","distribucion binomial","binomial"],"explanation":"Una variable binomial cuenta éxitos en n ensayos independientes, con dos resultados y probabilidad de éxito p constante. Su esperanza es np. La fórmula de una probabilidad exacta incluye tanto la probabilidad de una secuencia como cuántas secuencias dan el mismo número de éxitos.","simpler":"Cuenta éxitos bajo condiciones precisas: mismo número de ensayos, independencia y misma probabilidad.","example":"En tres lanzamientos independientes de una moneda equilibrada, obtener exactamente dos caras tiene probabilidad 3·(1/2)³ = 3/8: hay tres posiciones posibles para la cruz.","why":"El coeficiente combinatorio cuenta posiciones; multiplicarlo por la probabilidad de cada secuencia suma casos disjuntos equivalentes.","misconception":"Calcular solo la probabilidad de una secuencia omite otras ordenaciones posibles.","hints":["Cuenta las secuencias distintas que cumplen el número de éxitos.","Cuenta éxitos bajo condiciones precisas: mismo número de ensayos, independencia y misma probabilidad.","En tres lanzamientos independientes de una moneda equilibrada, obtener exactamente dos caras tiene probabilidad 3·(1/2)³ = 3/8: hay tres posiciones posibles para la cruz."],"quiz":[{"id":"b-binomial:q0","question":"La probabilidad del ejemplo es…","options":["1/8","1/2","3/8"],"answer":"C","hint":"Cuenta las secuencias distintas que cumplen el número de éxitos.","level":1},{"id":"b-binomial:q1","question":"La esperanza de una binomial es…","options":["np","n+p","p/n siempre"],"answer":"A","hint":"Cuenta las secuencias distintas que cumplen el número de éxitos.","level":2},{"id":"b-binomial:q2","question":"Una condición del modelo es…","options":["Que p cambie libremente entre ensayos","Independencia y probabilidad constante","Que todos los resultados sean éxitos"],"answer":"B","hint":"Cuenta las secuencias distintas que cumplen el número de éxitos.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-normal","stage":"bachillerato","subject":"Matemáticas","title":"Distribución normal","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Distribución normal","distribucion normal","campana de gauss","tipificacion"],"explanation":"La distribución normal es un modelo continuo simétrico respecto a su media μ. La desviación típica σ, positiva, mide dispersión. Para tipificar usamos z = (x − μ)/σ. En una variable continua, las probabilidades se asocian a intervalos, no a puntos con masa positiva.","simpler":"Restar la media centra el dato; dividir entre la desviación típica indica a cuántas desviaciones está.","example":"Si μ = 100 y σ = 15, para x = 130 obtenemos z = 2. El dato está dos desviaciones típicas por encima de la media.","why":"La probabilidad continua se obtiene como área bajo una densidad; un único punto tiene anchura nula.","misconception":"La altura de la curva normal en un punto no es la probabilidad de ese valor exacto.","hints":["Distingue densidad en un punto de probabilidad de un intervalo.","Restar la media centra el dato; dividir entre la desviación típica indica a cuántas desviaciones está.","Si μ = 100 y σ = 15, para x = 130 obtenemos z = 2. El dato está dos desviaciones típicas por encima de la media."],"quiz":[{"id":"b-normal:q0","question":"En el ejemplo, z vale…","options":["2","15","30"],"answer":"A","hint":"Distingue densidad en un punto de probabilidad de un intervalo.","level":1},{"id":"b-normal:q1","question":"Un z negativo indica un valor…","options":["Siempre imposible","Por debajo de la media","De probabilidad negativa"],"answer":"B","hint":"Distingue densidad en un punto de probabilidad de un intervalo.","level":2},{"id":"b-normal:q2","question":"En una distribución continua, P(X = un valor exacto) es…","options":["Siempre 1","Siempre 1/2","0"],"answer":"C","hint":"Distingue densidad en un punto de probabilidad de un intervalo.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-dot","stage":"bachillerato","subject":"Matemáticas","title":"Producto escalar de vectores","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Producto escalar de vectores","producto escalar","producto punto"],"explanation":"En coordenadas cartesianas ortonormales, el producto escalar suma los productos de componentes correspondientes. También equivale al producto de módulos por el coseno del ángulo. Para dos vectores no nulos, producto escalar cero indica perpendicularidad.","simpler":"Multiplica componentes de la misma posición y suma. El resultado es un número.","example":"Para u = (1,2) y v = (2,−1), u·v = 1·2 + 2·(−1) = 0. Como ambos son no nulos, son perpendiculares.","why":"La relación con el coseno requiere módulos no nulos para interpretar geométricamente el ángulo.","misconception":"El vector cero no tiene un ángulo definido con otro vector aunque su producto escalar sea cero.","hints":["Conserva los signos de las componentes y comprueba las condiciones.","Multiplica componentes de la misma posición y suma. El resultado es un número.","Para u = (1,2) y v = (2,−1), u·v = 1·2 + 2·(−1) = 0. Como ambos son no nulos, son perpendiculares."],"quiz":[{"id":"b-dot:q0","question":"El producto escalar del ejemplo es…","options":["4","0","−4"],"answer":"B","hint":"Conserva los signos de las componentes y comprueba las condiciones.","level":1},{"id":"b-dot:q1","question":"El resultado de un producto escalar es…","options":["Un escalar","Siempre un vector","Siempre positivo"],"answer":"A","hint":"Conserva los signos de las componentes y comprueba las condiciones.","level":2},{"id":"b-dot:q2","question":"Para dos vectores no nulos, producto escalar cero indica…","options":["Paralelismo obligatorio","Igualdad de módulos","Perpendicularidad"],"answer":"C","hint":"Conserva los signos de las componentes y comprueba las condiciones.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-gravity","stage":"bachillerato","subject":"Física","title":"Gravitación universal","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Gravitación universal","gravitacion universal","fuerza gravitatoria","ley de gravitacion"],"explanation":"En el modelo newtoniano para masas puntuales, la fuerza gravitatoria tiene módulo F = GmM/r², es atractiva y actúa en la dirección que une las masas. Para cuerpos esféricos adecuados y puntos exteriores se puede usar su centro. r es una distancia entre centros en ese modelo.","simpler":"La fuerza aumenta con las masas y disminuye con el cuadrado de la separación.","example":"Si duplicas la distancia entre dos masas manteniendo las masas, la fuerza pasa a ser un cuarto de la inicial. No se reduce solo a la mitad.","why":"El cuadrado afecta al factor completo de distancia; confundir radio y altura cambia el modelo geométrico usado.","misconception":"Altura sobre la superficie y distancia al centro no son la misma magnitud.","hints":["Sustituye 2r en el denominador y eleva todo al cuadrado.","La fuerza aumenta con las masas y disminuye con el cuadrado de la separación.","Si duplicas la distancia entre dos masas manteniendo las masas, la fuerza pasa a ser un cuarto de la inicial. No se reduce solo a la mitad."],"quiz":[{"id":"b-gravity:q0","question":"Al duplicar r, la fuerza se multiplica por…","options":["2","1/2","1/4"],"answer":"C","hint":"Sustituye 2r en el denominador y eleva todo al cuadrado.","level":1},{"id":"b-gravity:q1","question":"La fuerza newtoniana entre dos masas es…","options":["Atractiva","Repulsiva siempre","Independiente de la distancia"],"answer":"A","hint":"Sustituye 2r en el denominador y eleva todo al cuadrado.","level":2},{"id":"b-gravity:q2","question":"En el modelo esférico exterior, r se mide…","options":["Desde cualquier superficie sin precisar","Entre los centros","Solo desde el suelo"],"answer":"B","hint":"Sustituye 2r en el denominador y eleva todo al cuadrado.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-waves","stage":"bachillerato","subject":"Física","title":"Frecuencia, periodo y longitud de onda","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Frecuencia, periodo y longitud de onda","frecuencia periodo y longitud de onda","ondas","longitud de onda"],"explanation":"El periodo T es el tiempo de un ciclo; la frecuencia f indica ciclos por segundo y cumple f = 1/T. La longitud de onda λ es la distancia entre puntos consecutivos en la misma fase. Para una onda periódica, v = λf en las condiciones del modelo.","simpler":"Periodo mide tiempo; longitud de onda mide distancia; frecuencia cuenta ciclos por tiempo.","example":"Si λ = 2 m y f = 5 Hz, la velocidad de propagación es 10 m/s. El periodo es 0,2 s.","why":"La perturbación se propaga mientras las partículas pueden oscilar localmente; son movimientos conceptualmente distintos.","misconception":"La velocidad de propagación no es necesariamente la velocidad de movimiento de cada partícula del medio.","hints":["Escribe las unidades para no confundir tiempo, distancia y frecuencia.","Periodo mide tiempo; longitud de onda mide distancia; frecuencia cuenta ciclos por tiempo.","Si λ = 2 m y f = 5 Hz, la velocidad de propagación es 10 m/s. El periodo es 0,2 s."],"quiz":[{"id":"b-waves:q0","question":"La velocidad del ejemplo es…","options":["10 m/s","2,5 m/s","7 m/s"],"answer":"A","hint":"Escribe las unidades para no confundir tiempo, distancia y frecuencia.","level":1},{"id":"b-waves:q1","question":"Con f = 5 Hz, el periodo es…","options":["5 s","0,2 s","2 s"],"answer":"B","hint":"Escribe las unidades para no confundir tiempo, distancia y frecuencia.","level":2},{"id":"b-waves:q2","question":"La longitud de onda se mide en…","options":["Hertz","Segundos","Unidades de longitud"],"answer":"C","hint":"Escribe las unidades para no confundir tiempo, distancia y frecuencia.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-equilibrium","stage":"bachillerato","subject":"Química","title":"Equilibrio químico","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Equilibrio químico","equilibrio quimico","equilibrio dinamico"],"explanation":"Un equilibrio químico dinámico se alcanza cuando las velocidades de las reacciones directa e inversa se igualan, bajo condiciones apropiadas. Las concentraciones permanecen constantes a escala macroscópica, pero no tienen por qué ser iguales entre sí. Un catalizador no cambia por sí solo la posición de equilibrio a temperatura fija.","simpler":"Que no cambien las cantidades observables no significa que se hayan detenido todas las transformaciones.","example":"En una reacción reversible en equilibrio, siguen ocurriendo ambos sentidos a igual velocidad. Añadir un catalizador puede acelerar la llegada al equilibrio sin cambiar su composición de equilibrio a la misma temperatura.","why":"El equilibrio es un balance de procesos, no una ausencia de procesos.","misconception":"Una concentración constante no demuestra que no ocurran reacciones microscópicas.","hints":["Distingue igualar velocidades de igualar concentraciones.","Que no cambien las cantidades observables no significa que se hayan detenido todas las transformaciones.","En una reacción reversible en equilibrio, siguen ocurriendo ambos sentidos a igual velocidad. Añadir un catalizador puede acelerar la llegada al equilibrio sin cambiar su composición de equilibrio a la misma temperatura."],"quiz":[{"id":"b-equilibrium:q0","question":"En equilibrio se igualan…","options":["Todas las concentraciones","Las velocidades directa e inversa","Todas las masas"],"answer":"B","hint":"Distingue igualar velocidades de igualar concentraciones.","level":1},{"id":"b-equilibrium:q1","question":"Un catalizador a temperatura fija…","options":["No cambia por sí solo la constante de equilibrio","Siempre desplaza el equilibrio hacia productos","Elimina la reacción inversa"],"answer":"A","hint":"Distingue igualar velocidades de igualar concentraciones.","level":2},{"id":"b-equilibrium:q2","question":"Equilibrio dinámico significa…","options":["Ausencia de movimiento de partículas","Que la reacción terminó para siempre","Transformaciones opuestas que se compensan macroscópicamente"],"answer":"C","hint":"Distingue igualar velocidades de igualar concentraciones.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-redox","stage":"bachillerato","subject":"Química","title":"Oxidación y reducción","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Oxidación y reducción","oxidacion y reduccion","redox","numero de oxidacion"],"explanation":"En una reacción redox cambian números de oxidación. Oxidarse corresponde a perder electrones en el balance; reducirse, a ganarlos. El agente oxidante se reduce y el reductor se oxida. No todas las oxidaciones requieren oxígeno como reactivo.","simpler":"Sigue los electrones: quien los cede se oxida y quien los recibe se reduce.","example":"Zn → Zn²⁺ + 2e⁻ representa una oxidación del zinc. Su número de oxidación pasa de 0 a +2 y ha cedido dos electrones.","why":"El lenguaje redox generaliza transferencias de electrones y cambios de oxidación más allá de las reacciones con oxígeno.","misconception":"Oxidación no equivale siempre a combinarse directamente con oxígeno.","hints":["Comprueba la conservación de carga además de los átomos.","Sigue los electrones: quien los cede se oxida y quien los recibe se reduce.","Zn → Zn²⁺ + 2e⁻ representa una oxidación del zinc. Su número de oxidación pasa de 0 a +2 y ha cedido dos electrones."],"quiz":[{"id":"b-redox:q0","question":"En el ejemplo, el zinc…","options":["Se reduce","No cambia","Se oxida"],"answer":"C","hint":"Comprueba la conservación de carga además de los átomos.","level":1},{"id":"b-redox:q1","question":"El agente oxidante…","options":["Se reduce","Se oxida siempre","No participa"],"answer":"A","hint":"Comprueba la conservación de carga además de los átomos.","level":2},{"id":"b-redox:q2","question":"Oxidarse implica en el balance…","options":["Ganar electrones","Perder electrones","Ganar protones necesariamente"],"answer":"B","hint":"Comprueba la conservación de carga además de los átomos.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-respiration","stage":"bachillerato","subject":"Biología","title":"Respiración celular aerobia","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Respiración celular aerobia","respiracion celular","respiracion aerobia","atp"],"explanation":"La respiración celular aerobia permite obtener ATP mediante la oxidación de moléculas y el acoplamiento energético. En eucariotas, la glucólisis ocurre en el citosol y otras etapas principalmente en mitocondrias. El oxígeno es el aceptor final de electrones de la cadena respiratoria aerobia; no es la fuente de carbono.","simpler":"La célula transforma energía química y parte se conserva en ATP. No confundas este proceso con ventilar pulmones.","example":"En el balance global de oxidación completa de glucosa se producen CO₂ y agua. Las plantas también realizan respiración celular, además de fotosíntesis en condiciones adecuadas.","why":"La obtención de ATP depende de reacciones y gradientes acoplados; el transporte de gases del organismo es un proceso relacionado pero distinto.","misconception":"La respiración celular no consiste simplemente en introducir aire en una célula.","hints":["Distingue localización, función de cada sustancia y balance energético.","La célula transforma energía química y parte se conserva en ATP. No confundas este proceso con ventilar pulmones.","En el balance global de oxidación completa de glucosa se producen CO₂ y agua. Las plantas también realizan respiración celular, además de fotosíntesis en condiciones adecuadas."],"quiz":[{"id":"b-respiration:q0","question":"La glucólisis en una célula eucariota ocurre en…","options":["El citosol","Solo el núcleo","Solo el aparato de Golgi"],"answer":"A","hint":"Distingue localización, función de cada sustancia y balance energético.","level":1},{"id":"b-respiration:q1","question":"En la cadena respiratoria aerobia, el oxígeno actúa como…","options":["Fuente de carbono","Aceptor final de electrones","Único productor de glucosa"],"answer":"B","hint":"Distingue localización, función de cada sustancia y balance energético.","level":2},{"id":"b-respiration:q2","question":"Las plantas…","options":["No respiran","Respiran solo si no tienen hojas","También realizan respiración celular"],"answer":"C","hint":"Distingue localización, función de cada sustancia y balance energético.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-kant","stage":"bachillerato","subject":"Filosofía","title":"Ética kantiana","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Ética kantiana","etica kantiana","imperativo categorico","kant etica"],"explanation":"La ética kantiana examina la acción desde el deber y la racionalidad moral, no solo por sus consecuencias. El imperativo categórico incluye la exigencia de actuar según máximas universalizables y tratar a las personas como fines, nunca únicamente como medios. Una explicación escolar debe distinguir interpretación y cita literal.","simpler":"Pregunta qué regla guía tu acción, si podría valer para todos y si respeta a las personas como sujetos, no solo como instrumentos.","example":"Mentir para obtener una ventaja plantea qué ocurriría si la máxima de prometer falsamente pudiera universalizarse. El análisis se centra en la regla y su justificación, no solo en si salió bien esta vez.","why":"La crítica se dirige a instrumentalizar personas sin reconocer su dignidad y autonomía moral.","misconception":"Usar medios para un proyecto no equivale automáticamente a tratar a una persona únicamente como medio.","hints":["Formula primero la máxima de la acción que quieres examinar.","Pregunta qué regla guía tu acción, si podría valer para todos y si respeta a las personas como sujetos, no solo como instrumentos.","Mentir para obtener una ventaja plantea qué ocurriría si la máxima de prometer falsamente pudiera universalizarse. El análisis se centra en la regla y su justificación, no solo en si salió bien esta vez."],"quiz":[{"id":"b-kant:q0","question":"En este enfoque importa examinar…","options":["Solo el beneficio obtenido","La máxima que guía la acción","Solo la popularidad"],"answer":"B","hint":"Formula primero la máxima de la acción que quieres examinar.","level":1},{"id":"b-kant:q1","question":"Tratar a alguien como fin implica…","options":["No reducirlo únicamente a un instrumento","No colaborar nunca con él","Ignorar su autonomía"],"answer":"A","hint":"Formula primero la máxima de la acción que quieres examinar.","level":2},{"id":"b-kant:q2","question":"Una explicación de Kant debe distinguir…","options":["Opiniones sin argumento de rumores solamente","Solo nombres de libros","Paráfrasis, interpretación y cita literal"],"answer":"C","hint":"Formula primero la máxima de la acción que quieres examinar.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-commentary","stage":"bachillerato","subject":"Lengua Castellana y Literatura","title":"Comentario crítico de texto","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Comentario crítico de texto","comentario de texto","comentario critico","analizar un texto"],"explanation":"Un comentario fundamentado distingue comprensión, análisis e interpretación. Identifica el tema, explica cómo se organiza el texto y relaciona recursos con su efecto. Las afirmaciones sobre intención, autoría o contexto deben apoyarse en el propio texto o en fuentes fiables, no inventarse.","simpler":"No basta decir si te gusta: explica qué hace el texto, cómo lo hace y con qué evidencias sostienes tu lectura.","example":"Si un texto repite una pregunta retórica, señala el fragmento y explica su posible función. No atribuyas una biografía al autor solo por la voz del narrador.","why":"El análisis explica cómo las decisiones lingüísticas y estructurales contribuyen a producir significado.","misconception":"Identificar una figura retórica no completa por sí solo su análisis.","hints":["Vincula cada interpretación con un fragmento concreto.","No basta decir si te gusta: explica qué hace el texto, cómo lo hace y con qué evidencias sostienes tu lectura.","Si un texto repite una pregunta retórica, señala el fragmento y explica su posible función. No atribuyas una biografía al autor solo por la voz del narrador."],"quiz":[{"id":"b-commentary:q0","question":"Un comentario crítico debe apoyar su interpretación con…","options":["Solo gustos","Solo la longitud del texto","Evidencias textuales y contexto contrastado"],"answer":"C","hint":"Vincula cada interpretación con un fragmento concreto.","level":1},{"id":"b-commentary:q1","question":"Narrador y autor real…","options":["No deben identificarse automáticamente","Son siempre la misma persona","Nunca tienen ninguna relación posible"],"answer":"A","hint":"Vincula cada interpretación con un fragmento concreto.","level":2},{"id":"b-commentary:q2","question":"Para analizar un recurso conviene…","options":["Nombrarlo sin explicar nada más","Relacionarlo con su función y efecto","Contar solo sus letras"],"answer":"B","hint":"Vincula cada interpretación con un fragmento concreto.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-constitution","stage":"bachillerato","subject":"Historia de España","title":"La Constitución de 1978","grade_min":2,"grade_max":2,"school_years":["2º de Bachillerato"],"aliases":["La Constitución de 1978","constitucion de 1978","constitucion espanola de 1978"],"explanation":"La Constitución de 1978 configura España como un Estado social y democrático de Derecho y establece una monarquía parlamentaria. Reconoce derechos y organiza instituciones. Para estudiar su aplicación y reformas hay que consultar fuentes oficiales vigentes y distinguir texto normativo, contexto histórico y práctica política.","simpler":"Estudia qué principios e instituciones establece, sin confundir la norma con cualquier opinión sobre su funcionamiento.","example":"El artículo 66 sitúa en las Cortes Generales, formadas por Congreso y Senado, la representación del pueblo español. Analizar ese texto no sustituye estudiar la transición y los debates de la época.","why":"Las normas establecen marcos jurídicos; el análisis histórico estudia además procesos, conflictos y aplicación efectiva.","misconception":"Una descripción constitucional no es una valoración automática de toda actuación política.","hints":["Separa principios constitucionales, instituciones y evolución histórica.","Estudia qué principios e instituciones establece, sin confundir la norma con cualquier opinión sobre su funcionamiento.","El artículo 66 sitúa en las Cortes Generales, formadas por Congreso y Senado, la representación del pueblo español. Analizar ese texto no sustituye estudiar la transición y los debates de la época."],"quiz":[{"id":"b-constitution:q0","question":"La forma política establecida es…","options":["Monarquía parlamentaria","Monarquía absoluta","República presidencialista"],"answer":"A","hint":"Separa principios constitucionales, instituciones y evolución histórica.","level":1},{"id":"b-constitution:q1","question":"Las Cortes Generales se componen de…","options":["Gobierno y tribunales","Congreso y Senado","Solo Congreso"],"answer":"B","hint":"Separa principios constitucionales, instituciones y evolución histórica.","level":2},{"id":"b-constitution:q2","question":"Para comprobar el texto vigente conviene…","options":["Usar cualquier resumen sin fecha","Basarse solo en una noticia","Consultar la publicación oficial y sus modificaciones"],"answer":"C","hint":"Separa principios constitucionales, instituciones y evolución histórica.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-market","stage":"bachillerato","subject":"Economía","title":"Oferta y demanda","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Oferta y demanda","oferta y demanda","equilibrio de mercado"],"explanation":"En el modelo básico, manteniendo otros factores constantes, una variación del precio provoca un movimiento a lo largo de una curva de demanda u oferta. Cambios en renta, preferencias o costes pueden desplazar curvas. El equilibrio describe compatibilidad entre cantidades ofrecidas y demandadas, no garantiza por sí solo justicia social.","simpler":"Distingue moverse sobre una curva porque cambia el precio de cambiar toda la curva por otro factor.","example":"Si aumentan las preferencias por un bien, su demanda puede desplazarse a la derecha. No es lo mismo que comprar más únicamente porque baja su precio, con la demanda dada.","why":"Distinguir parámetros y variables del modelo permite interpretar movimientos y desplazamientos sin mezclar causas.","misconception":"Demanda y cantidad demandada no son términos equivalentes en el análisis de curvas.","hints":["Identifica qué variable cambia y cuáles mantenemos constantes.","Distingue moverse sobre una curva porque cambia el precio de cambiar toda la curva por otro factor.","Si aumentan las preferencias por un bien, su demanda puede desplazarse a la derecha. No es lo mismo que comprar más únicamente porque baja su precio, con la demanda dada."],"quiz":[{"id":"b-market:q0","question":"Cambiar la cantidad demandada por un cambio de precio, manteniendo lo demás, es…","options":["Siempre desplazar toda la curva","Moverse sobre la curva","Eliminar la demanda"],"answer":"B","hint":"Identifica qué variable cambia y cuáles mantenemos constantes.","level":1},{"id":"b-market:q1","question":"Un aumento de preferencias por un bien puede…","options":["Desplazar su curva de demanda","Cambiar solo las unidades de medida","No influir nunca"],"answer":"A","hint":"Identifica qué variable cambia y cuáles mantenemos constantes.","level":2},{"id":"b-market:q2","question":"El equilibrio de mercado…","options":["Garantiza toda forma de justicia","Elimina todas las necesidades","No implica por sí solo una valoración ética favorable"],"answer":"C","hint":"Identifica qué variable cambia y cuáles mantenemos constantes.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-conditionals","stage":"bachillerato","subject":"Lengua Extranjera: Inglés","title":"Condicionales en inglés","grade_min":1,"grade_max":2,"school_years":["1º de Bachillerato","2º de Bachillerato"],"aliases":["Condicionales en inglés","condicionales en ingles","first and second conditional","second conditional"],"explanation":"En el contraste didáctico básico, first conditional suele combinar if + presente con will + base para una posibilidad futura. Second conditional suele combinar if + pasado con would + base para una hipótesis más distante o irreal. Estas son construcciones frecuentes, no todas las combinaciones posibles del idioma.","simpler":"Compara una posibilidad futura con una situación hipotética. La forma pasada puede expresar distancia hipotética, no tiempo pasado real.","example":"«If it rains, we will stay home». «If I had more time, I would read more». En el segundo ejemplo, had no obliga a situar la situación en el pasado.","why":"Las formas verbales también expresan la actitud hacia la probabilidad o realidad de una situación, no solo su ubicación temporal.","misconception":"Los nombres escolares de condicionales no agotan todos los usos posibles de if.","hints":["Observa el sentido de la condición además de las formas verbales.","Compara una posibilidad futura con una situación hipotética. La forma pasada puede expresar distancia hipotética, no tiempo pasado real.","«If it rains, we will stay home». «If I had more time, I would read more». En el segundo ejemplo, had no obliga a situar la situación en el pasado."],"quiz":[{"id":"b-conditionals:q0","question":"La segunda oración del ejemplo utiliza…","options":["Third conditional","Presente perfecto","Second conditional"],"answer":"C","hint":"Observa el sentido de la condición además de las formas verbales.","level":1},{"id":"b-conditionals:q1","question":"En «If I had more time…», had puede expresar…","options":["Distancia hipotética","Solo un hecho pasado terminado","Una orden"],"answer":"A","hint":"Observa el sentido de la condición además de las formas verbales.","level":2},{"id":"b-conditionals:q2","question":"La forma básica tras would es…","options":["Siempre el participio","La forma base del verbo","Siempre -ing"],"answer":"B","hint":"Observa el sentido de la condición además de las formas verbales.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"},{"id":"b-medieval-art","stage":"bachillerato","subject":"Historia del Arte","title":"Románico y gótico","grade_min":2,"grade_max":2,"school_years":["2º de Bachillerato"],"aliases":["Románico y gótico","romanico y gotico","arte romanico y gotico"],"explanation":"Románico y gótico designan conjuntos de tendencias artísticas medievales con diferencias regionales y cronológicas. En arquitectura románica son frecuentes el arco de medio punto y la bóveda de cañón; en la gótica, el arco apuntado y la bóveda de crucería. Ningún rasgo aislado basta para fechar o clasificar toda obra.","simpler":"Compara varios elementos de estructura, espacio, decoración y contexto, no solo la forma de un arco.","example":"Una iglesia puede conservar partes de épocas diferentes. Antes de clasificarla, examina la planta, cubiertas, soportes y documentación disponible.","why":"Las obras tienen historia material: ampliaciones, reformas y restauraciones pueden combinar rasgos de periodos diferentes.","misconception":"Los estilos no son etiquetas que se asignen con seguridad a partir de un único detalle.","hints":["Reúne indicios convergentes y distingue fases de construcción.","Compara varios elementos de estructura, espacio, decoración y contexto, no solo la forma de un arco.","Una iglesia puede conservar partes de épocas diferentes. Antes de clasificarla, examina la planta, cubiertas, soportes y documentación disponible."],"quiz":[{"id":"b-medieval-art:q0","question":"La bóveda de crucería se asocia especialmente con…","options":["La arquitectura gótica","La arquitectura informática","Solo los templos griegos"],"answer":"A","hint":"Reúne indicios convergentes y distingue fases de construcción.","level":1},{"id":"b-medieval-art:q1","question":"Un arco de medio punto…","options":["Fecha por sí solo cualquier edificio con exactitud","Debe interpretarse junto con otros rasgos","Prueba que todo es gótico"],"answer":"B","hint":"Reúne indicios convergentes y distingue fases de construcción.","level":2},{"id":"b-medieval-art:q2","question":"Un edificio histórico puede…","options":["Pertenecer siempre a una única fase","No sufrir modificaciones nunca","Conservar elementos de varias épocas"],"answer":"C","hint":"Reúne indicios convergentes y distingue fases de construcción.","level":3}],"curriculum_source":"https://www.boe.es/buscar/act.php?id=BOE-A-2022-5521","curriculum_source_key":"BOE-A-2022-5521","source_kind":"original_teaching_material","grade_mapping":"editorial_progression_not_official_grade_mandate","review_method":"AI-assisted editorial review plus structural and deterministic tests; not human teacher certification","human_teacher_reviewed":false,"language":"es","license_note":"Material original preparado para ETERNA; referencia curricular por etapa, sin aval oficial.","curriculum_alignment_status":"stage_subject_reference_not_exhaustive_criterion_mapping","introduced_in_release":"eterna-library-2026.09-v2-160"}]};
